INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('94319045-2283-5745-8944-995a1279df5e', 'yq-754', 'yq-754', 'YQ-754', '{"ar":"CeraVe غسول زيت رغوي مرطب","en":"CeraVe Cleanser"}'::jsonb, '{"ar":"CeraVe منظف بتركيبة رغوية، ينظف البشرة ويزيل الشوائب بلطف. كما أنه ينظف بلطف دون جفاف، ويزيل الأوساخ والزيوت الزائدة. وهو مناسب للبشرة عادية وجافة ودهنية، يلبي احتياجات البشرة التي تعاني من حب الشباب واللمعان الزائد. تتضمن تركيبته مكونات مثل ماء وجلسرين ومستخلص الصبار. طريقة الاستخدام: بللي وجهك بالماء الفاتر.","en":"CeraVe Cleanser that cleanses the skin and removes impurities gently. Suitable for عادية, جافة, دهنية skin. Key ingredients include Aqua, Glycerin, Aloe Vera Extract."}'::jsonb, '1c48bc43-635e-5769-8a44-223edcb31ce7', 'b73b3a97-b924-5435-8662-59d9a0f2247f', '{"price":11800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/CeraVe_SA_Smoothing_Cleanser_for_normal_dry_and_rough_skin_236ml.jpg?v=1752919012"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/CeraVe_SA_Smoothing_Cleanser_for_normal_dry_and_rough_skin_236ml.jpg?v=1752919012"]'::jsonb, '{"ar":["ماء","جلسرين","مستخلص الصبار","بابونج"],"en":["Aqua","Glycerin","Aloe Vera Extract","Chamomile"]}'::jsonb, '{"ar":"ضعي المنتج على وجه مبلل بالماء الفاتر، ضعي على البشرة كمية مناسبة بحركات دائرية، اشطفي بالماء جيداً ثم جففي بلطف","en":"Apply the product on a damp face. Apply an appropriate amount to the skin, massaging gently. Rinse well with water, then pat dry."}'::jsonb, '["Apply the product on a damp face.","Apply an appropriate amount to the skin, massaging gently.","Rinse well with water, then pat dry."]'::jsonb, '["ضعي المنتج على وجه مبلل بالماء الفاتر","ضعي على البشرة كمية مناسبة بحركات دائرية","اشطفي بالماء جيداً ثم جففي بلطف"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["acne","oiliness","sensitivity"]'::jsonb, '{"ar":["ينظف البشرة ويزيل الشوائب بلطف","يعيد للبشرة إحساس النظافة والانتعاش","تركيبة رغوية خفيفة سهلة التوزيع","يجذب الرطوبة ويرطب البشرة","يرطب البشرة ويهدئها","يساعد على تنظيم مظهر الحبوب"],"en":["cleanses the skin and removes impurities gently","restores a clean, refreshed feeling to the skin","a light foam formula that spreads easily","attracts moisture and hydrates the skin","hydrates and soothes the skin","helps manage the look of blemishes"]}'::jsonb, 25, TRUE, 25, 4.5, 6, FALSE, FALSE, FALSE, FALSE, '["skincare","cleansers","cerave"]'::jsonb, '{"title":{"ar":"CeraVe غسول زيت رغوي مرطب - Luminous Derma","en":"CeraVe Cleanser - Luminous Derma"},"description":{"ar":"CeraVe منظف، يعمل على ينظف البشرة ويزيل الشوائب بلطف ويلبي احتياجات البشرة التي تعاني من حب الشباب واللمعان الزائد ويتميز بمكونات تشمل ماء وجلسرين ومستخلص الصبار وهو مناسب للبشرة عادية وجافة.","en":"CeraVe Cleanser that cleanses the skin and removes impurities gently, addressing حب الشباب and اللمعان الزائد, with key ingredients including Aqua, Glycerin, Aloe Vera Extract, suitable for عادية and جافة skin."},"keywords":["Cleansers","skincare"]}'::jsonb);
