INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('4a174e3b-cdcc-545f-80d8-58332d0ee653', 'yq-1051', 'yq-1051', 'YQ-1051', '{"ar":"The Ordinary تونر مقشر بحمض الجليكوليك 7% 100 مل","en":"The Ordinary Toner 100 مل"}'::jsonb, '{"ar":"The Ordinary تونر بتركيبة جل بحجم 100 مل بتركيز 7%، يوازن البشرة ويحضرها لخطوات العناية التالية. كما أنه يوازن درجة حموضة البشرة، ويقلل مظهر المسام الواسعة. وهو مناسب للبشرة عادية وجافة ودهنية، يلبي احتياجات البشرة التي تعاني من اللمعان الزائد والمسام الواسعة. تتضمن تركيبته مكونات مثل ماء الورد ونياسيناميد وحمض الهيالورونيك. طريقة الاستخدام: ضعي التونر على قطنة نظيفة.","en":"The Ordinary Toner (100 مل, 7%) that balances and prepares the skin for the next steps. Suitable for عادية, جافة, دهنية skin. Key ingredients include Rose Water, Niacinamide, Hyaluronic Acid."}'::jsonb, 'bde3d316-a661-57b4-8070-887c5e0bd7bf', 'cfe8d43a-f885-5659-8689-ccc049e2b833', '{"price":9800,"currency":"YER"}'::jsonb, 0, '["/images/products/yq-1051.png"]'::jsonb, '["/images/products/yq-1051.png"]'::jsonb, '{"ar":["ماء الورد","نياسيناميد","حمض الهيالورونيك","مستخلص الخيار"],"en":["Rose Water","Niacinamide","Hyaluronic Acid","Cucumber Extract"]}'::jsonb, '{"ar":"امسحي على الوجه، ثم يُطبق المرطب","en":"Wipe over the face. Follow with moisturizer."}'::jsonb, '["Wipe over the face.","Follow with moisturizer."]'::jsonb, '["امسحي على الوجه","ثم يُطبق المرطب"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["oiliness","large_pores","uneven_texture"]'::jsonb, '{"ar":["يوازن البشرة ويحضرها لخطوات العناية التالية","يعيد للبشرة إحساس النقاء والانتعاش","تركيبة جل منعشة سهلة الاستخدام","بتركيز 7% من المكون النشط","ينعش البشرة","يهدئ البشرة ويدعم توازنها"],"en":["balances and prepares the skin for the next steps","restores a clean, refreshed feeling to the skin","a refreshing gel formula that is easy to use","with a 7% concentration of the active ingredient","refreshes the skin","soothes the skin and supports its balance"]}'::jsonb, 25, TRUE, 25, 4.5, 24, FALSE, FALSE, FALSE, FALSE, '["skincare","toners","the-ordinary"]'::jsonb, '{"title":{"ar":"The Ordinary تونر مقشر بحمض الجليكوليك 7% 100 مل - Luminous Derma","en":"The Ordinary Toner 100 مل - Luminous Derma"},"description":{"ar":"The Ordinary تونر بحجم 100 مل بتركيز 7%، يعمل على يوازن البشرة ويحضرها لخطوات العناية التالية ويلبي احتياجات البشرة التي تعاني من اللمعان الزائد والمسام الواسعة ويتميز بمكونات تشمل ماء الورد ونياسيناميد وحمض الهيالورونيك وهو مناسب للبشرة عادية وجافة.","en":"The Ordinary Toner (100 مل), 7% that balances and prepares the skin for the next steps, addressing اللمعان الزائد and المسام الواسعة, with key ingredients including Rose Water, Niacinamide, Hyaluronic Acid, suitable for عادية and جافة skin."},"keywords":["Toners","skincare"]}'::jsonb);
