INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('5839687c-bc74-5a52-8873-c93b5f9411be', 'yq-629', 'yq-629', 'YQ-629', '{"ar":"The Ordinary طقم عرض سيروم نياسيناميد + سيروم حمض الهيالورونيك","en":"The Ordinary Serum"}'::jsonb, '{"ar":"The Ordinary سيروم، يمنح البشرة عناية مركزة بمكونات فعالة. كما أنه تركيبة مركزة عالية الفعالية، ونتائج سريعة وملحوظة. وهو مناسب للبشرة عادية وجافة ودهنية، يلبي احتياجات البشرة التي تعاني من حب الشباب والتصبغات. تتضمن تركيبته مكونات مثل فيتامين C وحمض الهيالورونيك ونياسيناميد. طريقة الاستخدام: نظفي بشرتك جيداً.","en":"The Ordinary Serum that delivers concentrated, effective care. Suitable for عادية, جافة, دهنية skin. Key ingredients include Vitamin C, Hyaluronic Acid, Niacinamide."}'::jsonb, '29e558a9-3a4b-52d6-874c-0662648849c0', 'cfe8d43a-f885-5659-8689-ccc049e2b833', '{"price":15800,"currency":"YER"}'::jsonb, 0, '["/images/products/yq-629.png"]'::jsonb, '["/images/products/yq-629.png"]'::jsonb, '{"ar":["فيتامين C","حمض الهيالورونيك","نياسيناميد","الريتينول"],"en":["Vitamin C","Hyaluronic Acid","Niacinamide","Retinol"]}'::jsonb, '{"ar":"بعد تنظيف البشرة جيداً، دلكي على الوجه بضع قطرات، اتركيه حتى يُمتص، ثم يُطبق المرطب","en":"بعد تنظيف البشرة جيداً. Massage a few drops into the face. Leave it until absorbed. Follow with moisturizer."}'::jsonb, '["بعد تنظيف البشرة جيداً.","Massage a few drops into the face.","Leave it until absorbed.","Follow with moisturizer."]'::jsonb, '["بعد تنظيف البشرة جيداً","دلكي على الوجه بضع قطرات","اتركيه حتى يُمتص","ثم يُطبق المرطب"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["acne","pigmentation","aging","uneven_texture"]'::jsonb, '{"ar":["يمنح البشرة عناية مركزة بمكونات فعالة","يوفر عناية مركزة للبشرة","يدعم حماية البشرة بمضادات الأكسدة","يرطب البشرة بعمق ويحبس الرطوبة","يساعد على تنظيم مظهر الحبوب","يعتني بمظهر البشرة بلطف"],"en":["delivers concentrated, effective care","delivers concentrated care","supports skin protection with antioxidants","deeply hydrates the skin and locks in moisture","helps manage the look of blemishes","gently cares for the look of the skin"]}'::jsonb, 25, TRUE, 25, 4.5, 36, FALSE, FALSE, FALSE, FALSE, '["skincare","serums","the-ordinary"]'::jsonb, '{"title":{"ar":"The Ordinary طقم عرض سيروم نياسيناميد + سيروم حمض الهيالورونيك - Luminous Derma","en":"The Ordinary Serum - Luminous Derma"},"description":{"ar":"The Ordinary سيروم، يعمل على يمنح البشرة عناية مركزة بمكونات فعالة ويلبي احتياجات البشرة التي تعاني من حب الشباب والتصبغات ويتميز بمكونات تشمل فيتامين C وحمض الهيالورونيك ونياسيناميد وهو مناسب للبشرة عادية وجافة.","en":"The Ordinary Serum that delivers concentrated, effective care, addressing حب الشباب and التصبغات, with key ingredients including Vitamin C, Hyaluronic Acid, Niacinamide, suitable for عادية and جافة skin."},"keywords":["Serums","skincare"]}'::jsonb);
