INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('2533719d-0f25-5e41-8657-92b8cc4b168d', 'yq-129', 'yq-129', 'YQ-129', '{"ar":"La Roche-Posay كريم مرطب مرمم سيكابلاست بوم بي 5 بعامل حمايه 50+","en":"La Roche-Posay Moisturizer SPF50+"}'::jsonb, '{"ar":"La Roche-Posay مرطب، يرطب البشرة ويدعم حاجزها الطبيعي. كما أنه ترطيب عميق يدوم طوال اليوم، ويمنح البشرة نعومة وإشراقة. وهو مناسب للبشرة عادية وجافة ودهنية، يلبي احتياجات البشرة التي تعاني من الجفاف والبشرة الحساسة. تتضمن تركيبته مكونات مثل جلسرين وسيراميد وزبدة الشيا. طريقة الاستخدام: نظفي بشرتك ثم جففيها.","en":"La Roche-Posay Moisturizer that hydrates the skin and supports its natural barrier. Suitable for عادية, جافة, دهنية skin. Key ingredients include Glycerin, Ceramides, Shea Butter."}'::jsonb, 'a16f522c-12bf-569c-8fd3-72a53a3a2c58', '8c88bc9f-1413-5364-87ea-b2e44dfd4b5d', '{"price":11800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/LaRoche-PosayEffaclarHIsobiomeMoisturizingCreamforoily_andacneproneskin40ml.jpg?v=1714979708"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/LaRoche-PosayEffaclarHIsobiomeMoisturizingCreamforoily_andacneproneskin40ml.jpg?v=1714979708"]'::jsonb, '{"ar":["جلسرين","سيراميد","زبدة الشيا","حمض الهيالورونيك"],"en":["Glycerin","Ceramides","Shea Butter","Hyaluronic Acid"]}'::jsonb, '{"ar":"دلكي المنتج على بشرة نظيفة وجافة، دلكي على الوجه كمية مناسبة، اتركيه حتى يُمتص","en":"Apply the product on clean, dry skin. Massage an appropriate amount into the face. Leave it until absorbed."}'::jsonb, '["Apply the product on clean, dry skin.","Massage an appropriate amount into the face.","Leave it until absorbed."]'::jsonb, '["دلكي المنتج على بشرة نظيفة وجافة","دلكي على الوجه كمية مناسبة","اتركيه حتى يُمتص"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["dryness","sensitivity","aging"]'::jsonb, '{"ar":["يرطب البشرة ويدعم حاجزها الطبيعي","يساعد على تقوية حاجز البشرة","بمعامل حماية 50 من الشمس","يجذب الرطوبة ويرطب البشرة","يدعم حاجز البشرة ويحافظ على رطوبتها","يخفف إحساس الجفاف"],"en":["hydrates the skin and supports its natural barrier","helps strengthen the skin''s barrier","with sun protection factor 50","attracts moisture and hydrates the skin","supports the skin barrier and retains moisture","relieves the feeling of dryness"]}'::jsonb, 25, TRUE, 25, 4.5, 71, FALSE, FALSE, FALSE, FALSE, '["skincare","moisturizers","la-roche-posay"]'::jsonb, '{"title":{"ar":"La Roche-Posay كريم مرطب مرمم سيكابلاست بوم بي 5 بعامل حمايه 50+ - Luminous Derma","en":"La Roche-Posay Moisturizer SPF50+ - Luminous Derma"},"description":{"ar":"La Roche-Posay مرطب، يعمل على يرطب البشرة ويدعم حاجزها الطبيعي ويلبي احتياجات البشرة التي تعاني من الجفاف والبشرة الحساسة ويتميز بمكونات تشمل جلسرين وسيراميد وزبدة الشيا وهو مناسب للبشرة عادية وجافة.","en":"La Roche-Posay Moisturizer that hydrates the skin and supports its natural barrier, addressing الجفاف and البشرة الحساسة, with key ingredients including Glycerin, Ceramides, Shea Butter, suitable for عادية and جافة skin."},"keywords":["Moisturizers","skincare"]}'::jsonb);
