INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('32a90e0a-1313-5761-8b88-2fa5e72847ab', 'yq-1660', 'yq-1660', 'YQ-1660', '{"ar":"La Roche-Posay واقي شمس سائل انثيلوس يو في مون 400 بدون لون","en":"La Roche-Posay Sunscreen"}'::jsonb, '{"ar":"La Roche-Posay واقي شمسي بتركيبة سائلة، يوفر حماية يومية من أشعة الشمس. كما أنه حماية واسعة من الأشعة UVA وUVB، ووقاية من التصبغات والتصبغ المبكر. وهو مناسب للبشرة عادية وجافة ودهنية، يلبي احتياجات البشرة التي تعاني من التصبغات وعلامات تقدم السن. تتضمن تركيبته مكونات مثل أكسيد الزنك وثاني أكسيد التيتانيوم وفيتامين E. طريقة الاستخدام: ضعي كمية وفيرة قبل التعرض للشمس.","en":"La Roche-Posay Sunscreen that provides daily sun protection. Suitable for عادية, جافة, دهنية skin. Key ingredients include Zinc Oxide, Titanium Dioxide, Vitamin E."}'::jsonb, '3f21fce6-6fd0-588c-8138-aba94299246f', '8c88bc9f-1413-5364-87ea-b2e44dfd4b5d', '{"price":15800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/LaRoche-PosayAntheliosUVMune400OilControlFluidInvisibleSunscreenSPF50_50ml_9ba5f6e9-1017-4506-b091-0f1549cd20b5.jpg?v=1752129401"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/LaRoche-PosayAntheliosUVMune400OilControlFluidInvisibleSunscreenSPF50_50ml_9ba5f6e9-1017-4506-b091-0f1549cd20b5.jpg?v=1752129401"]'::jsonb, '{"ar":["أكسيد الزنك","ثاني أكسيد التيتانيوم","فيتامين E","ألانتوين"],"en":["Zinc Oxide","Titanium Dioxide","Vitamin E","Allantoin"]}'::jsonb, '{"ar":"ضعي على الوجه كمية وفيرة، أعيدي وضعه كل ساعتين","en":"Apply a generous amount to the face. Reapply every two hours."}'::jsonb, '["Apply a generous amount to the face.","Reapply every two hours."]'::jsonb, '["ضعي على الوجه كمية وفيرة","أعيدي وضعه كل ساعتين"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["pigmentation","aging","redness"]'::jsonb, '{"ar":["يوفر حماية يومية من أشعة الشمس","يساعد على حماية البشرة من الأشعة الضارة","تركيبة سائلة خفيفة سهلة الاستخدام","يدعم حاجز البشرة الطبيعي","يهدئ البشرة","يعتني بمظهر البشرة بلطف"],"en":["provides daily sun protection","helps protect skin from harmful rays","a light liquid formula that is easy to use","supports the skin''s natural barrier","calms the skin","gently cares for the look of the skin"]}'::jsonb, 25, TRUE, 25, 4.5, 12, FALSE, TRUE, FALSE, FALSE, '["skincare","sunscreen","la-roche-posay"]'::jsonb, '{"title":{"ar":"La Roche-Posay واقي شمس سائل انثيلوس يو في مون 400 بدون لون - Luminous Derma","en":"La Roche-Posay Sunscreen - Luminous Derma"},"description":{"ar":"La Roche-Posay واقي شمسي، يعمل على يوفر حماية يومية من أشعة الشمس ويلبي احتياجات البشرة التي تعاني من التصبغات وعلامات تقدم السن ويتميز بمكونات تشمل أكسيد الزنك وثاني أكسيد التيتانيوم وفيتامين E وهو مناسب للبشرة عادية وجافة.","en":"La Roche-Posay Sunscreen that provides daily sun protection, addressing التصبغات and علامات تقدم السن, with key ingredients including Zinc Oxide, Titanium Dioxide, Vitamin E, suitable for عادية and جافة skin."},"keywords":["Sunscreen","skincare"]}'::jsonb);
