INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('2313b354-0742-5574-89bb-ef8629a2b7c8', 'yq-306', 'yq-306', 'YQ-306', '{"ar":"The Ordinary سيروم كافيين رعاية للعين","en":"The Ordinary Eye Care"}'::jsonb, '{"ar":"The Ordinary رعاية للعين، يعتني بمنطقة العين الحساسة. كما أنه يقلل الهالات السوداء، وينعّم الخطوط الدقيقة. وهو مناسب للبشرة عادية وجافة ودهنية، يلبي احتياجات البشرة التي تعاني من الهالات السوداء وعلامات تقدم السن. تتضمن تركيبته مكونات مثل الكافيين وفيتامين C وحمض الهيالورونيك. طريقة الاستخدام: ضعي كمية صغيرة تحت العين.","en":"The Ordinary Eye Care that cares for the delicate eye area. Suitable for عادية, جافة, دهنية skin. Key ingredients include Caffeine, Vitamin C, Hyaluronic Acid."}'::jsonb, '6b70b2eb-a8b0-56c8-851d-ac7bf7635246', 'cfe8d43a-f885-5659-8689-ccc049e2b833', '{"price":7800,"currency":"YER"}'::jsonb, 0, '["/images/products/yq-306.png"]'::jsonb, '["/images/products/yq-306.png"]'::jsonb, '{"ar":["الكافيين","فيتامين C","حمض الهيالورونيك","ببتيدات"],"en":["Caffeine","Vitamin C","Hyaluronic Acid","Peptides"]}'::jsonb, '{"ar":"دلكي تحت العين كمية صغيرة، مرتين يومياً، صباحاً ومساءً","en":"Massage a small amount under the eyes. Use daily, use morning and evening."}'::jsonb, '["Massage a small amount under the eyes.","Use daily, use morning and evening."]'::jsonb, '["دلكي تحت العين كمية صغيرة","مرتين يومياً، صباحاً ومساءً"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["dark_circles","aging"]'::jsonb, '{"ar":["يعتني بمنطقة العين الحساسة","يهدئ منطقة العين الحساسة","يستخدم في روتين العناية صباحاً ومساءً","يدعم انتعاش البشرة","يدعم حماية البشرة بمضادات الأكسدة","يعتني بمظهر منطقة العين"],"en":["cares for the delicate eye area","soothes the delicate eye area","used in both morning and evening care","supports a refreshed look","supports skin protection with antioxidants","cares for the eye area"]}'::jsonb, 25, TRUE, 25, 4.5, 26, FALSE, FALSE, FALSE, FALSE, '["skincare","eye-care","the-ordinary"]'::jsonb, '{"title":{"ar":"The Ordinary سيروم كافيين رعاية للعين - Luminous Derma","en":"The Ordinary Eye Care - Luminous Derma"},"description":{"ar":"The Ordinary رعاية للعين، يعمل على يعتني بمنطقة العين الحساسة ويلبي احتياجات البشرة التي تعاني من الهالات السوداء وعلامات تقدم السن ويتميز بمكونات تشمل الكافيين وفيتامين C وحمض الهيالورونيك وهو مناسب للبشرة عادية وجافة.","en":"The Ordinary Eye Care that cares for the delicate eye area, addressing الهالات السوداء and علامات تقدم السن, with key ingredients including Caffeine, Vitamin C, Hyaluronic Acid, suitable for عادية and جافة skin."},"keywords":["Eye Care","skincare"]}'::jsonb);
