INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('0301c7b9-d756-5140-811e-019b69fa5083', 'yq-821', 'yq-821', 'YQ-821', '{"ar":"Jumjum Pharma جل ديفرين مقشرات","en":"Jumjum Pharma Exfoliator"}'::jsonb, '{"ar":"Jumjum Pharma مقشرات بتركيبة جل، يقشر البشرة بلطف ويزيل الخلايا الميتة. كما أنه يزيل خلايا الجلد الميتة، ويوحد لون البشرة. وهو مناسب للبشرة عادية وجافة ودهنية، يلبي احتياجات البشرة التي تعاني من حب الشباب وملمس البشرة غير المتساوي. تتضمن تركيبته مكونات مثل حمض الساليسيليك وحمض الجليكوليك وحبيبات دقيقة. طريقة الاستخدام: طبقي على بشرة رطبة ونظيفة.","en":"Jumjum Pharma Exfoliator that gently exfoliates and removes dead cells. Suitable for عادية, جافة, دهنية skin. Key ingredients include Salicylic Acid, Glycolic Acid, Fine Exfoliating Particles."}'::jsonb, '7907841f-c414-5d82-814f-9ef070c20c6d', '3ab51e73-3675-5c90-85f3-914a0d75eef3', '{"price":5800,"currency":"YER"}'::jsonb, 0, '["/images/products/yq-821.png"]'::jsonb, '["/images/products/yq-821.png"]'::jsonb, '{"ar":["حمض الساليسيليك","حمض الجليكوليك","حبيبات دقيقة","مستخلص الشوفان"],"en":["Salicylic Acid","Glycolic Acid","Fine Exfoliating Particles","Oat Extract"]}'::jsonb, '{"ar":"ضعي على البشرة بحركات دائرية، اشطفي بالماء جيداً ثم جففي بلطف، مرتين إلى ثلاث مرات أسبوعياً","en":"Apply to the skin, massaging gently. Rinse well with water, then pat dry. Two to three times a week."}'::jsonb, '["Apply to the skin, massaging gently.","Rinse well with water, then pat dry.","Two to three times a week."]'::jsonb, '["ضعي على البشرة بحركات دائرية","اشطفي بالماء جيداً ثم جففي بلطف","مرتين إلى ثلاث مرات أسبوعياً"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["acne","uneven_texture","pigmentation"]'::jsonb, '{"ar":["يقشر البشرة بلطف ويزيل الخلايا الميتة","يزيل الخلايا الميتة بلطف","تركيبة جل منعشة سهلة الاستخدام","ينقي المسام ويهدئ البشرة","يقشر البشرة بلطف","يساعد على تنظيم مظهر الحبوب"],"en":["gently exfoliates and removes dead cells","gently removes dead skin cells","a refreshing gel formula that is easy to use","cleanses pores and soothes the skin","gently exfoliates the skin","helps manage the look of blemishes"]}'::jsonb, 25, TRUE, 25, 4.5, 59, FALSE, FALSE, FALSE, FALSE, '["skincare","exfoliators","jumjum-pharma"]'::jsonb, '{"title":{"ar":"Jumjum Pharma جل ديفرين مقشرات - Luminous Derma","en":"Jumjum Pharma Exfoliator - Luminous Derma"},"description":{"ar":"Jumjum Pharma مقشرات، يعمل على يقشر البشرة بلطف ويزيل الخلايا الميتة ويلبي احتياجات البشرة التي تعاني من حب الشباب وملمس البشرة غير المتساوي ويتميز بمكونات تشمل حمض الساليسيليك وحمض الجليكوليك وحبيبات دقيقة وهو مناسب للبشرة عادية وجافة.","en":"Jumjum Pharma Exfoliator that gently exfoliates and removes dead cells, addressing حب الشباب and ملمس البشرة غير المتساوي, with key ingredients including Salicylic Acid, Glycolic Acid, Fine Exfoliating Particles, suitable for عادية and جافة skin."},"keywords":["Exfoliators","skincare"]}'::jsonb);
