INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('419808cf-c69b-5e3f-88b1-1a28e7824a74', 'yq-1402', 'yq-1402', 'YQ-1402', '{"ar":"هيربال إيسنسز‎ كريم يترك بخلاصه الصبار وزيت الافوكادو بلسم","en":"هيربال إيسنسز‎ Conditioner"}'::jsonb, '{"ar":"هيربال إيسنسز‎ بلسم، ينعم الشعر ويغذيه. كما أنه ينعم ويغذي الشعر، ويفك التشابك بسهولة. وهو مناسب للبشرة عادية وجافة ودهنية. تتضمن تركيبته مكونات مثل زيت الأرغان وكيراتين وبانثينول. طريقة الاستخدام: طبقي على أطراف الشعر.","en":"هيربال إيسنسز‎ Conditioner that softens and nourishes the hair. Suitable for عادية, جافة, دهنية skin. Key ingredients include Argan Oil, Keratin, Panthenol."}'::jsonb, 'd39b1d3b-45e0-575c-8bc3-2c2116aab606', '47bcbe12-258a-57fd-8e26-81b909e1b0fe', '{"price":4800,"currency":"YER"}'::jsonb, 0, '["/images/products/yq-1402.png"]'::jsonb, '["/images/products/yq-1402.png"]'::jsonb, '{"ar":["زيت الأرغان","كيراتين","بانثينول","زيوت طبيعية"],"en":["Argan Oil","Keratin","Panthenol","Natural Oils"]}'::jsonb, '{"ar":"ضعي على الشعر بطبقة متساوية، اتركيه لمدة دقيقة إلى دقيقتين، اشطفي بالماء جيداً ثم جففي بلطف","en":"Apply to the hair, massaging gently. Leave it for one to two minutes. Rinse well with water, then pat dry."}'::jsonb, '["Apply to the hair, massaging gently.","Leave it for one to two minutes.","Rinse well with water, then pat dry."]'::jsonb, '["ضعي على الشعر بطبقة متساوية","اتركيه لمدة دقيقة إلى دقيقتين","اشطفي بالماء جيداً ثم جففي بلطف"]'::jsonb, '["normal","dry","oily"]'::jsonb, '["normal","dry","oily"]'::jsonb, '[]'::jsonb, '{"ar":["ينعم الشعر ويغذيه","يساعد على فك تشابك الشعر","يغذي ويمنح ملمساً ناعماً","يساعد على دعم قوة الشعر ونعومته","مناسب للبشرة عادية وجافة ودهنية"],"en":["softens and nourishes the hair","helps detangle the hair","nourishes and gives a soft feel","helps support hair strength and softness","suitable for عادية and جافة and دهنية skin"]}'::jsonb, 25, TRUE, 25, 4.5, 74, FALSE, FALSE, FALSE, FALSE, '["haircare","conditioner","هيربال-إيسنسز‎"]'::jsonb, '{"title":{"ar":"هيربال إيسنسز‎ كريم يترك بخلاصه الصبار وزيت الافوكادو بلسم - Luminous Derma","en":"هيربال إيسنسز‎ Conditioner - Luminous Derma"},"description":{"ar":"هيربال إيسنسز‎ بلسم، يعمل على ينعم الشعر ويغذيه ويتميز بمكونات تشمل زيت الأرغان وكيراتين وبانثينول وهو مناسب للبشرة عادية وجافة.","en":"هيربال إيسنسز‎ Conditioner that softens and nourishes the hair, with key ingredients including Argan Oil, Keratin, Panthenol, suitable for عادية and جافة skin."},"keywords":["Conditioner","haircare"]}'::jsonb);
