INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('8f5fc952-12fc-57d3-8b99-8f75a46b8cdf', 'yq-1775', 'yq-1775', 'YQ-1775', '{"ar":"Lux غسول","en":"Lux Body Wash"}'::jsonb, '{"ar":"Lux غسول جسم، ينظف الجسم بلطف. كما أنه تنظيف لطيف للجسم، ورغوة غنية وناعمة. وهو مناسب للبشرة عادية وجافة ودهنية. تتضمن تركيبته مكونات مثل جلسرين ومستخلص الشوفان وزيت اللوز. طريقة الاستخدام: ضعي على إسفنجة أو مباشرة.","en":"Lux Body Wash that cleanses the body gently. Suitable for عادية, جافة, دهنية skin. Key ingredients include Glycerin, Oat Extract, Almond Oil."}'::jsonb, '1cfdc4ca-7151-569a-8c4e-d97a9a522586', 'a03abd5d-a2cf-545c-8e68-df8ba0ce8ac5', '{"price":2800,"currency":"YER"}'::jsonb, 0, '["/images/products/yq-1775.png"]'::jsonb, '["/images/products/yq-1775.png"]'::jsonb, '{"ar":["جلسرين","مستخلص الشوفان","زيت اللوز","بابونج"],"en":["Glycerin","Oat Extract","Almond Oil","Chamomile"]}'::jsonb, '{"ar":"ضعي على الجسم بحركات دائرية، اشطفي بالماء جيداً ثم جففي بلطف","en":"Apply to the body, massaging gently. Rinse well with water, then pat dry."}'::jsonb, '["Apply to the body, massaging gently.","Rinse well with water, then pat dry."]'::jsonb, '["ضعي على الجسم بحركات دائرية","اشطفي بالماء جيداً ثم جففي بلطف"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '[]'::jsonb, '{"ar":["ينظف الجسم بلطف","يعيد للبشرة إحساس النظافة","يجذب الرطوبة ويرطب البشرة","يهدئ البشرة الحساسة","مناسب للبشرة عادية وجافة ودهنية ومختلطة وحساسة"],"en":["cleanses the body gently","restores a clean feeling to the skin","attracts moisture and hydrates the skin","soothes sensitive skin","suitable for عادية and جافة and دهنية and مختلطة and حساسة skin"]}'::jsonb, 25, TRUE, 25, 4.5, 82, FALSE, FALSE, FALSE, FALSE, '["bodycare","body-wash","lux"]'::jsonb, '{"title":{"ar":"Lux غسول - Luminous Derma","en":"Lux Body Wash - Luminous Derma"},"description":{"ar":"Lux غسول جسم، يعمل على ينظف الجسم بلطف ويتميز بمكونات تشمل جلسرين ومستخلص الشوفان وزيت اللوز وهو مناسب للبشرة عادية وجافة.","en":"Lux Body Wash that cleanses the body gently, with key ingredients including Glycerin, Oat Extract, Almond Oil, suitable for عادية and جافة skin."},"keywords":["Body Wash","bodycare"]}'::jsonb);
