INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('6d7b9867-61ad-5e3e-8af4-1412344c0a39', 'yq-2312', 'yq-2312', 'YQ-2312', '{"ar":"Maybelline كريم اساس فيت مي مات اند بورليس للتحكم في مع حمايه مكياج face","en":"Maybelline Face Makeup"}'::jsonb, '{"ar":"Maybelline مكياج وجه، يمنح الوجه مظهراً متناسقاً. كما أنه ثبات طويل، وتغطية قابلة للطبقات. وهو مناسب للبشرة عادية وجافة ودهنية. تتضمن تركيبته مكونات مثل تالك وأكسيد الحديد وحمض الهيالورونيك. طريقة الاستخدام: طبقي على بشرة نظيفة.","en":"Maybelline Face Makeup that gives the face a balanced look. Suitable for عادية, جافة, دهنية skin. Key ingredients include Talc, Iron Oxide, Hyaluronic Acid."}'::jsonb, 'e59718df-8ee6-579d-8374-6f682e5904ac', '225421d0-3404-5809-80eb-4632966fdf67', '{"price":5800,"currency":"YER"}'::jsonb, 0, '["/images/products/yq-2312.png"]'::jsonb, '["/images/products/yq-2312.png"]'::jsonb, '{"ar":["تالك","أكسيد الحديد","حمض الهيالورونيك","فيتامين E"],"en":["Talc","Iron Oxide","Hyaluronic Acid","Vitamin E"]}'::jsonb, '{"ar":"ضعي المنتج على بشرة نظيفة، ضعي على البشرة بتوزيع متساوٍ، أعيدي الطبقة عند الحاجة","en":"Apply the product on clean skin. Apply to the skin, massaging gently. Reapply as needed."}'::jsonb, '["Apply the product on clean skin.","Apply to the skin, massaging gently.","Reapply as needed."]'::jsonb, '["ضعي المنتج على بشرة نظيفة","ضعي على البشرة بتوزيع متساوٍ","أعيدي الطبقة عند الحاجة"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '["normal","dry","oily","combination","sensitive"]'::jsonb, '[]'::jsonb, '{"ar":["يمنح الوجه مظهراً متناسقاً","يساعد على توزيع المنتج بسلاسة","يرطب البشرة بعمق ويحبس الرطوبة","يدعم حاجز البشرة الطبيعي","مناسب للبشرة عادية وجافة ودهنية ومختلطة وحساسة"],"en":["gives the face a balanced look","helps apply the product smoothly","deeply hydrates the skin and locks in moisture","supports the skin''s natural barrier","suitable for عادية and جافة and دهنية and مختلطة and حساسة skin"]}'::jsonb, 25, TRUE, 25, 4.5, 18, TRUE, FALSE, FALSE, FALSE, '["makeup","face-makeup","maybelline"]'::jsonb, '{"title":{"ar":"Maybelline كريم اساس فيت مي مات اند بورليس للتحكم في مع حمايه مكياج face - Luminous Derma","en":"Maybelline Face Makeup - Luminous Derma"},"description":{"ar":"Maybelline مكياج face، يعمل على يمنح الوجه مظهراً متناسقاً ويتميز بمكونات تشمل تالك وأكسيد الحديد وحمض الهيالورونيك وهو مناسب للبشرة عادية وجافة.","en":"Maybelline Face Makeup that gives the face a balanced look, with key ingredients including Talc, Iron Oxide, Hyaluronic Acid, suitable for عادية and جافة skin."},"keywords":["Face Makeup","makeup"]}'::jsonb);
