INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('fe392b81-a89b-5436-8a8a-b545911be346', 'yq-404', 'yq-404', 'YQ-404', '{"ar":"Depurdent معجون الاسنان للاطفال اعتبار رعاية أطفال","en":"Depurdent Baby Care"}'::jsonb, '{"ar":"Depurdent رعاية أطفال، يعتني ببشرة الأطفال الحساسة بلطف. كما أنه لطيف وآمن على بشرة الطفل، وتركيبة خالية من العطور القاسية. وهو مناسب للبشرة حساسة وعادية، يلبي احتياجات البشرة التي تعاني من البشرة الحساسة. تتضمن تركيبته مكونات مثل ماء وغليسيرين ومستخلص البابونج. طريقة الاستخدام: ضعي كمية لطيفة على البشرة.","en":"Depurdent Baby Care that cares for delicate baby skin gently. Suitable for حساسة, عادية skin. Key ingredients include Aqua, Glycerin, Chamomile Extract."}'::jsonb, 'aa0e3a4b-5bc8-57fe-82cb-7b6b106ff078', '8d384429-4128-5359-890d-21cfe393301e', '{"price":3300,"currency":"YER"}'::jsonb, 0, '["/images/products/yq-404.png"]'::jsonb, '["/images/products/yq-404.png"]'::jsonb, '{"ar":["ماء","غليسيرين","مستخلص البابونج","زيت اللوز"],"en":["Aqua","Glycerin","Chamomile Extract","Almond Oil"]}'::jsonb, '{"ar":"دلكي على البشرة، يومياً","en":"Massage into the skin. Use daily."}'::jsonb, '["Massage into the skin.","Use daily."]'::jsonb, '["دلكي على البشرة","يومياً"]'::jsonb, '["sensitive","normal"]'::jsonb, '["sensitive","normal"]'::jsonb, '["sensitivity"]'::jsonb, '{"ar":["يعتني ببشرة الأطفال الحساسة بلطف","يراعي بشرة الطفل الرقيقة","يجذب الرطوبة ويرطب البشرة","يهدئ البشرة بلطف","يراعي البشرة الحساسة بلطف","مناسب للبشرة حساسة وعادية"],"en":["cares for delicate baby skin gently","respects delicate baby skin","attracts moisture and hydrates the skin","gently calms the skin","respects sensitive skin gently","suitable for حساسة and عادية skin"]}'::jsonb, 25, TRUE, 25, 4.5, 19, FALSE, FALSE, FALSE, FALSE, '["baby","baby-care","depurdent"]'::jsonb, '{"title":{"ar":"Depurdent معجون الاسنان للاطفال اعتبار رعاية أطفال - Luminous Derma","en":"Depurdent Baby Care - Luminous Derma"},"description":{"ar":"Depurdent رعاية أطفال، يعمل على يعتني ببشرة الأطفال الحساسة بلطف ويلبي احتياجات البشرة التي تعاني من البشرة الحساسة ويتميز بمكونات تشمل ماء وغليسيرين ومستخلص البابونج وهو مناسب للبشرة حساسة وعادية.","en":"Depurdent Baby Care that cares for delicate baby skin gently, addressing البشرة الحساسة, with key ingredients including Aqua, Glycerin, Chamomile Extract, suitable for حساسة and عادية skin."},"keywords":["Baby Care","baby"]}'::jsonb);
