INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('3cba7eed-8db2-56ce-8bee-3d4cf0a3bc8a', 'yq-98', 'yq-98', 'YQ-98', '{"ar":"يوسرين تونر تنقيه اويل كنترول 200 مل","en":"Eucerin Toner 200 مل"}'::jsonb, '{"ar":"يوسرين تونر بحجم 200 مل، يوازن البشرة ويحضرها لخطوات العناية التالية. كما أنه إنتاج الزيوت الزائد والذي يعرف أيضًا باسم الزهم، والنمو البكتيري الذي يؤدي إلى التهاب واضح في شكل حبوب وبثرات. طريقة الاستخدام: يُنظف الوجه ويُجفف.","en":"يوسرين Toner (200 مل) that balances and prepares the skin for the next steps."}'::jsonb, 'bde3d316-a661-57b4-8070-887c5e0bd7bf', '6df7e4c7-e844-5b73-8b84-93f4d255cf53', '{"price":11800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/EucerinDermopurifyerToner200ml1.jpg?v=1768217978"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/EucerinDermopurifyerToner200ml1.jpg?v=1768217978"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه","en":"Apply to the face."}'::jsonb, '["Apply to the face."]'::jsonb, '["ضعي على الوجه"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يوازن البشرة ويحضرها لخطوات العناية التالية","يعيد للبشرة إحساس النقاء والانتعاش"],"en":["balances and prepares the skin for the next steps","restores a clean, refreshed feeling to the skin"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["toners","يوسرين"]'::jsonb, '{"title":{"ar":"يوسرين تونر تنقيه اويل كنترول 200 مل - Luminous Derma","en":"Eucerin Toner 200 مل - Luminous Derma"},"description":{"ar":"Eucerin تونر بحجم 200 مل، يعمل على يوازن البشرة ويحضرها لخطوات العناية التالية.","en":"Eucerin Toner (200 مل) that balances and prepares the skin for the next steps."},"keywords":["luminous","toners","يوسرين"]}'::jsonb);
