INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('17920bd3-c3fb-5b0a-843d-fd9afea3405a', 'yq-322', 'yq-322', 'YQ-322', '{"ar":"جاردن اوليان مقشر السكر بزيت الالوفيرا وزيوت الاعشاب الاساسيه 600 غرام","en":"جاردن اوليان 600 غرام"}'::jsonb, '{"ar":"جاردن اوليان مقشر جسم بحجم 600 غرام، يقشر الجسم بلطف ويحسن ملمسه. كما أنه مقشر سكر غني بزيت الالوفيرا وزبدة جوز الهند يتميز بمفعوله القوي كمقشر استثنائي لا مثيل له، ومكوناته الفريدة تساعد على ترطيب البشرة بعمق وتجديدها. طريقة الاستخدام: يوضع على الجسم بعد تبليله بالماء الدافئ، ثم يدلك عل شكل حركات دائرية للحصول على مفعول التقشير.","en":"جاردن اوليان Body Scrub (600 غرام) that gently exfoliates the body and improves texture."}'::jsonb, 'fe65be64-8785-5ecd-8af9-bdcccfa49dde', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":5800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1686698942_1.png","https://www.yaqootstoreye.com/files/items/item_1686698942_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1686698942_1.png","https://www.yaqootstoreye.com/files/items/item_1686698942_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"دلكي المنتج على بشرة مبللة بالماء الدافئ، دلكي على الوجه، اشطفي بالماء جيداً ثم جففي بلطف، تنبيه: توقفي عن الاستخدام عند حدوث تهيج","en":"Apply the product to بشرة مبللة بالماء الدافئ. Massage into the face. Rinse well with water, then pat dry. Note: discontinue use if irritation occurs."}'::jsonb, '["Apply the product to بشرة مبللة بالماء الدافئ.","Massage into the face.","Rinse well with water, then pat dry.","Note: discontinue use if irritation occurs."]'::jsonb, '["دلكي المنتج على بشرة مبللة بالماء الدافئ","دلكي على الوجه","اشطفي بالماء جيداً ثم جففي بلطف","تنبيه: توقفي عن الاستخدام عند حدوث تهيج"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يقشر الجسم بلطف ويحسن ملمسه","ينعم بشرة الجسم","يستخدم في روتين العناية المسائي"],"en":["gently exfoliates the body and improves texture","smooths the body''s skin","used in an evening care routine"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["body-scrubs","جاردن اوليان"]'::jsonb, '{"title":{"ar":"جاردن اوليان مقشر السكر بزيت الالوفيرا وزيوت الاعشاب الاساسيه 600 غرام - Luminous Derma","en":"جاردن اوليان 600 غرام - Luminous Derma"},"description":{"ar":"جاردن اوليان body-scrubs بحجم 600 غرام، يعمل على يقشر الجسم بلطف ويحسن ملمسه.","en":"جاردن اوليان body-scrubs (600 غرام) that gently exfoliates the body and improves texture."},"keywords":["luminous","body-scrubs","جاردن اوليان"]}'::jsonb);
