INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('6d8a004f-9eb2-5bba-8d8f-06e46d515432', 'yq-330', 'yq-330', 'YQ-330', '{"ar":"بايوديرما سيروم مضاد لتصبغات مفتح معا فيتامين سي 150 مل","en":"Bioderma Serum 150 مل"}'::jsonb, '{"ar":"بايوديرما سيروم بحجم 150 مل، يمنح البشرة عناية مركزة بمكونات فعالة. كما أنه منتج سيرومات يلبي احتياجك اليومي. طريقة الاستخدام: 1 خطوة عند الاستخدام لأول مرة، اضغط بقوة باستخدام كلا الإبهامين على غطاء العبوة حتى يتم إنزال الغطاء بالكامل لتحرير فيتامين سي.","en":"بايوديرما Serum (150 مل) that delivers concentrated, effective care."}'::jsonb, '29e558a9-3a4b-52d6-874c-0662648849c0', '889719a7-01a7-558a-8176-607fb2cddc44', '{"price":17800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/BiodermaBrumeInvisibleSpf50_150ml.jpg?v=1715845485"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/BiodermaBrumeInvisibleSpf50_150ml.jpg?v=1715845485"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه بضع قطرات، بعد التنظيف، مساءً، تنبيه: توقفي عن الاستخدام عند حدوث تهيج","en":"Apply a few drops to the face. . Note: discontinue use if irritation occurs."}'::jsonb, '["Apply a few drops to the face.",".","Note: discontinue use if irritation occurs."]'::jsonb, '["ضعي على الوجه بضع قطرات","بعد التنظيف، مساءً","تنبيه: توقفي عن الاستخدام عند حدوث تهيج"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يمنح البشرة عناية مركزة بمكونات فعالة","يوفر عناية مركزة للبشرة","يستخدم في روتين العناية المسائي"],"en":["delivers concentrated, effective care","delivers concentrated care","used in an evening care routine"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["serums","بايوديرما"]'::jsonb, '{"title":{"ar":"بايوديرما سيروم مضاد لتصبغات مفتح معا فيتامين سي 150 مل - Luminous Derma","en":"Bioderma Serum 150 مل - Luminous Derma"},"description":{"ar":"Bioderma سيروم بحجم 150 مل، يعمل على يمنح البشرة عناية مركزة بمكونات فعالة.","en":"Bioderma Serum (150 مل) that delivers concentrated, effective care."},"keywords":["luminous","serums","بايوديرما"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('a0200130-461d-52bf-81a6-b265ddd6b787', 'yq-331', 'yq-331', 'YQ-331', '{"ar":"جاردن اوليان مقشر السكر بزيت الارجان ومسحوق الورد 600 غرام","en":"جاردن اوليان 600 غرام"}'::jsonb, '{"ar":"جاردن اوليان مقشر جسم بحجم 600 غرام، يقشر الجسم بلطف ويحسن ملمسه. كما أنه إنه غني بـزيت الأرجان الذي يرطب بشرتك بعمق ويحافظ عليها ناعمة وسلسة، ووبالتالي، فإن مقشر السكر يترك بشرتك متوهجة صحية ونابضة بالحياة. طريقة الاستخدام: يوضع على الجسم بعد تبليله بالماء الدافئ، ثم يدلك عل شكل حركات دائرية للحصول على مفعول التقشير.","en":"جاردن اوليان Body Scrub (600 غرام) that gently exfoliates the body and improves texture."}'::jsonb, 'fe65be64-8785-5ecd-8af9-bdcccfa49dde', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":5800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1686760903_1.png","https://www.yaqootstoreye.com/files/items/item_1686760903_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1686760903_1.png","https://www.yaqootstoreye.com/files/items/item_1686760903_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"دلكي المنتج على بشرة مبللة بالماء الدافئ، دلكي على الوجه، اشطفي بالماء جيداً ثم جففي بلطف، تنبيه: توقفي عن الاستخدام عند حدوث تهيج","en":"Apply the product to بشرة مبللة بالماء الدافئ. Massage into the face. Rinse well with water, then pat dry. Note: discontinue use if irritation occurs."}'::jsonb, '["Apply the product to بشرة مبللة بالماء الدافئ.","Massage into the face.","Rinse well with water, then pat dry.","Note: discontinue use if irritation occurs."]'::jsonb, '["دلكي المنتج على بشرة مبللة بالماء الدافئ","دلكي على الوجه","اشطفي بالماء جيداً ثم جففي بلطف","تنبيه: توقفي عن الاستخدام عند حدوث تهيج"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يقشر الجسم بلطف ويحسن ملمسه","ينعم بشرة الجسم","يستخدم في روتين العناية المسائي"],"en":["gently exfoliates the body and improves texture","smooths the body''s skin","used in an evening care routine"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["body-scrubs","جاردن اوليان"]'::jsonb, '{"title":{"ar":"جاردن اوليان مقشر السكر بزيت الارجان ومسحوق الورد 600 غرام - Luminous Derma","en":"جاردن اوليان 600 غرام - Luminous Derma"},"description":{"ar":"جاردن اوليان body-scrubs بحجم 600 غرام، يعمل على يقشر الجسم بلطف ويحسن ملمسه.","en":"جاردن اوليان body-scrubs (600 غرام) that gently exfoliates the body and improves texture."},"keywords":["luminous","body-scrubs","جاردن اوليان"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('0fda795d-0f1d-56fc-8a8c-ea0a32a4539d', 'yq-332', 'yq-332', 'YQ-332', '{"ar":"بايوديرما واقي شمس كريم معا نسبه حمايه 50% مضاد لتجاعيد والبقع الداكنه 40 مل","en":"Bioderma Moisturizer 40 مل SPF50"}'::jsonb, '{"ar":"بايوديرما مرطب بحجم 40 مل بتركيز 50% بعامل حماية SPF50، يرطب البشرة ويدعم حاجزها الطبيعي. كما أنه يساعد في منع ظهور البقع الجديدة ويقلل من علامات الشيخوخة ويحسن من تجانس لون البشرة. طريقة الاستخدام: يوضع يومياً في الصباح قبل التعرض لأشعة الشمس و يكرر وضعه للمحافظة على الحماية الأولية.","en":"بايوديرما Moisturizer (40 مل, 50%) that hydrates the skin and supports its natural barrier."}'::jsonb, 'a16f522c-12bf-569c-8fd3-72a53a3a2c58', '889719a7-01a7-558a-8176-607fb2cddc44', '{"price":11800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/Bioderma_Sensibio_Ar_Visible_Redness_Reducing_Care_40ml_2_Free_Bioderma_Sensibio_H2o_10ml_1_5c23e283-e2d2-4f88-9d9a-44f49942ebcb.png?v=1740318125"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/Bioderma_Sensibio_Ar_Visible_Redness_Reducing_Care_40ml_2_Free_Bioderma_Sensibio_H2o_10ml_1_5c23e283-e2d2-4f88-9d9a-44f49942ebcb.png?v=1740318125"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه، قبل التعرض للشمس، يومياً، صباحاً","en":"Apply to the face. Use before sun exposure, use daily."}'::jsonb, '["Apply to the face.","Use before sun exposure, use daily."]'::jsonb, '["ضعي على الوجه","قبل التعرض للشمس، يومياً، صباحاً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يرطب البشرة ويدعم حاجزها الطبيعي","يساعد على تقوية حاجز البشرة","بمعامل حماية 50 من الشمس","يستخدم في روتين العناية الصباحي"],"en":["hydrates the skin and supports its natural barrier","helps strengthen the skin''s barrier","with sun protection factor 50","used in a morning care routine"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["moisturizers","بايوديرما"]'::jsonb, '{"title":{"ar":"بايوديرما واقي شمس كريم معا نسبه حمايه 50% مضاد لتجاعيد والبقع الداكنه 40 مل - Luminous Derma","en":"Bioderma Moisturizer 40 مل SPF50 - Luminous Derma"},"description":{"ar":"Bioderma مرطب بحجم 40 مل بتركيز 50%، يعمل على يرطب البشرة ويدعم حاجزها الطبيعي.","en":"Bioderma Moisturizer (40 مل), 50% that hydrates the skin and supports its natural barrier."},"keywords":["luminous","moisturizers","بايوديرما"]}'::jsonb);
