INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('6be4f230-f4d5-5a42-8fce-a6437dec3001', 'yq-406', 'yq-406', 'YQ-406', '{"ar":"فارماسيريز شامبو لتحفيز نمو 250 مل","en":"فارماسيريز Shampoo 250 مل"}'::jsonb, '{"ar":"فارماسيريز شامبو بحجم 250 مل، ينظف الشعر بلطف. كما أنه شامبو مصمم للنساء والرجال المتضررين من تساقط الشعر المفرط المؤقت أو المبكر، ومناسب لفروة الرأس الحساسة. طريقة الاستخدام: هو مزيج فريد من مكونين: عامل النمو الطبيعي FGF والكافيين (طلب براءة اختراع) يظهر فعالية مؤكدة علميًا في منع تساقط الشعر وتحفيز نمو الشعر في نفس الوقت.","en":"فارماسيريز Shampoo (250 مل) that cleanses the hair gently."}'::jsonb, 'e96e9919-f71c-53bd-80be-bd4e1416c366', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":10800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1691265999_1.png","https://www.yaqootstoreye.com/files/items/item_1691265999_2.png","https://www.yaqootstoreye.com/files/items/item_1691265999_3.png","https://www.yaqootstoreye.com/files/items/item_1691265999_4.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1691265999_1.png","https://www.yaqootstoreye.com/files/items/item_1691265999_2.png","https://www.yaqootstoreye.com/files/items/item_1691265999_3.png","https://www.yaqootstoreye.com/files/items/item_1691265999_4.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"هو مزيج فريد من مكونين: عامل النمو الطبيعي FGF والكافيين (طلب براءة اختراع) يظهر فعالية مؤكدة علميًا في منع تساقط الشعر وتحفيز نمو الشعر في نفس الوقت. تسري المكونات الموجودة في هذا المركب على المستوى الخلوي من خلال تنشيط الجينات المسؤولة عن نمو الشعر الجديد. أنها تعزز عمليات الحياة لبصيلات الشعر الموجودة لتعزيز نمو الشعر الطبيعي وإطالة العمر الافتراضي (مرحلة التنامي). يمنع الكافيين الصلع المحدد وراثيًا عن طريق تحييد التأثير السلبي للهرمونات (الأندروجينات ، DHT) المسؤولة عن تدهور الشعر وتساقط الشعر المبكر. مكونات التكييف المختارة بعناية: النياسيناميد (فيتامين PP) ، D- بانثينول والبيوتين لها تأثير مهدئ واستعادة التوازن الفسيولوجي لفروة الرأس. الشامبو ينظف شعرك وفروة رأسك بلطف وفعالية. ينعم ويقوي بنية الشعر ويعيد سماكة الشعر الطبيعي. يحتوي على درجة حموضة محايدة مماثلة لمستوى فروة الرأس. خالٍ من البارابين والمواد المثيرة للحساسية والملونات والسيليكون","en":"هو مزيج فريد من مكونين: عامل النمو الطبيعي FGF والكافيين (طلب براءة اختراع) يظهر فعالية مؤكدة علميًا في منع تساقط الشعر وتحفيز نمو الشعر في نفس الوقت. تسري المكونات الموجودة في هذا المركب على المستوى الخلوي من خلال تنشيط الجينات المسؤولة عن نمو الشعر الجديد. أنها تعزز عمليات الحياة لبصيلات الشعر الموجودة لتعزيز نمو الشعر الطبيعي وإطالة العمر الافتراضي (مرحلة التنامي). يمنع الكافيين الصلع المحدد وراثيًا عن طريق تحييد التأثير السلبي للهرمونات (الأندروجينات ، DHT) المسؤولة عن تدهور الشعر وتساقط الشعر المبكر. مكونات التكييف المختارة بعناية: النياسيناميد (فيتامين PP) ، D- بانثينول والبيوتين لها تأثير مهدئ واستعادة التوازن الفسيولوجي لفروة الرأس. الشامبو ينظف شعرك وفروة رأسك بلطف وفعالية. ينعم ويقوي بنية الشعر ويعيد سماكة الشعر الطبيعي. يحتوي على درجة حموضة محايدة مماثلة لمستوى فروة الرأس. خالٍ من البارابين والمواد المثيرة للحساسية والملونات والسيليكون"}'::jsonb, '["هو مزيج فريد من مكونين: عامل النمو الطبيعي FGF والكافيين (طلب براءة اختراع) يظهر فعالية مؤكدة علميًا في منع تساقط الشعر وتحفيز نمو الشعر في نفس الوقت","تسري المكونات الموجودة في هذا المركب على المستوى الخلوي من خلال تنشيط الجينات المسؤولة عن نمو الشعر الجديد","أنها تعزز عمليات الحياة لبصيلات الشعر الموجودة لتعزيز نمو الشعر الطبيعي وإطالة العمر الافتراضي (مرحلة التنامي)","يمنع الكافيين الصلع المحدد وراثيًا عن طريق تحييد التأثير السلبي للهرمونات (الأندروجينات ، DHT) المسؤولة عن تدهور الشعر وتساقط الشعر المبكر","مكونات التكييف المختارة بعناية: النياسيناميد (فيتامين PP) ، D- بانثينول والبيوتين ل