INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('5a76260d-9d4a-5bee-8334-477f8b56b8a9', 'yq-443', 'yq-443', 'YQ-443', '{"ar":"كاليفورنيا غولد نيوتريشن زيت جوز الهند البكر معصور البارد 473 مل","en":"كاليفورنيا غولد نيوتريشن Hair Oil 473 مل"}'::jsonb, '{"ar":"كاليفورنيا غولد نيوتريشن زيت شعر بحجم 473 مل، يغذي الشعر ويمنحه اللمعان. كما أنه * استخدامات زيت جوز الهند يمكن استخدام زيت جوز الهند داخليًا وخارجيًا، وهو خيار ممتاز لزيت طهي عند درجات حرارة متوسطة، ومثالي للاستخدام عند الخبز أو القلي.","en":"كاليفورنيا غولد نيوتريشن Hair Oil (473 مل) that nourishes the hair and adds shine."}'::jsonb, '20ef7886-9d7f-5583-81bb-b99eb35f29c9', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":8800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1691597199_1.png","https://www.yaqootstoreye.com/files/items/item_1691597199_2.png","https://www.yaqootstoreye.com/files/items/item_1691597199_3.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1691597199_1.png","https://www.yaqootstoreye.com/files/items/item_1691597199_2.png","https://www.yaqootstoreye.com/files/items/item_1691597199_3.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"نقدم لكم زيت جوز الهند البكر العضوي الممتاز غير المكرر والمعصور على البارد المثالي للاستخدام كزيت طهي عند درجات حرارة متوسطة – الأفضل للمخبوزات والقلي، لكنه غير مناسب للتحمير. يمكنك إضافته بسهولة إلى وصفاتك من المخفوقات، والأسموزي، وتتبيلات السلطة، أو يمكنك استخدامه كبديل للزبدة أو زيت الزيتون. كما يُعد زيت جوز الهند الخاص بنا ممتازًا للاستخدام الخارجي كدهان للبشرة والشعر، والاستخدام كزيت وسيط للتدليك.","en":"نقدم لكم زيت جوز الهند البكر العضوي الممتاز غير المكرر والمعصور على البارد المثالي للاستخدام كزيت طهي عند درجات حرارة متوسطة – الأفضل للمخبوزات والقلي، لكنه غير مناسب للتحمير. يمكنك إضافته بسهولة إلى وصفاتك من المخفوقات، والأسموزي، وتتبيلات السلطة، أو يمكنك استخدامه كبديل للزبدة أو زيت الزيتون. كما يُعد زيت جوز الهند الخاص بنا ممتازًا للاستخدام الخارجي كدهان للبشرة والشعر، والاستخدام كزيت وسيط للتدليك."}'::jsonb, '["نقدم لكم زيت جوز الهند البكر العضوي الممتاز غير المكرر والمعصور على البارد المثالي للاستخدام كزيت طهي عند درجات حرارة متوسطة – الأفضل للمخبوزات والقلي، لكنه غير مناسب للتحمير","يمكنك إضافته بسهولة إلى وصفاتك من المخفوقات، والأسموزي، وتتبيلات السلطة، أو يمكنك استخدامه كبديل للزبدة أو زيت الزيتون","كما يُعد زيت جوز الهند الخاص بنا ممتازًا للاستخدام الخارجي كدهان للبشرة والشعر، والاستخدام كزيت وسيط للتدليك"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يغذي الشعر ويمنحه اللمعان","يضفي على الشعر لمعاناً صحياً"],"en":["nourishes the hair and adds shine","adds a healthy shine to the hair"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["hair-oils","كاليفورنيا غولد نيوتريشن"]'::jsonb, '{"title":{"ar":"كاليفورنيا غولد نيوتريشن زيت جوز الهند البكر معصور البارد 473 مل - Luminous Derma","en":"كاليفورنيا غولد نيوتريشن Hair Oil 473 مل - Luminous Derma"},"description":{"ar":"كاليفورنيا غولد نيوتريشن زيت شعر بحجم 473 مل، يعمل على يغذي الشعر ويمنحه اللمعان.","en":"كاليفورنيا غولد نيوتريشن Hair Oil (473 مل) that nourishes the hair and adds shine."},"keywords":["luminous","hair-oils","كاليفورنيا غولد نيوتريشن"]}'::jsonb);
