INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('47ed3b29-617f-5a66-8a31-e1479a6bc281', 'yq-448', 'yq-448', 'YQ-448', '{"ar":"فاني كريم واقي شمس 85 غرام","en":"فاني كريم Moisturizer 85 غرام"}'::jsonb, '{"ar":"فاني كريم مرطب بحجم 85 غرام، يرطب البشرة ويدعم حاجزها الطبيعي. كما أنه الفوائد يحمي البشرة من تكون البقع الداكنة والتصبغات، وتركيبة خفيفة غير دهنية , سريعة الامتصاص. طريقة الاستخدام: ضع كمية وفيرة قبل 15 دقيقة من التعرض للشمس يعاد وضع الواقي بعد 40 دقيقة من السباحة أو التعرق ومباشرة بعد تجفيف المنشفة ، وعلى الأقل ساعتين.","en":"فاني كريم Moisturizer (85 غرام) that hydrates the skin and supports its natural barrier."}'::jsonb, 'a16f522c-12bf-569c-8fd3-72a53a3a2c58', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":14800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1691600451_1.png","https://www.yaqootstoreye.com/files/items/item_1691600451_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1691600451_1.png","https://www.yaqootstoreye.com/files/items/item_1691600451_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه كمية وفيرة، اتركيه لمدة دقيقة إلى دقيقتين","en":"Apply a generous amount to the face. Leave it for one to two minutes."}'::jsonb, '["Apply a generous amount to the face.","Leave it for one to two minutes."]'::jsonb, '["ضعي على الوجه كمية وفيرة","اتركيه لمدة دقيقة إلى دقيقتين"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يرطب البشرة ويدعم حاجزها الطبيعي","يساعد على تقوية حاجز البشرة"],"en":["hydrates the skin and supports its natural barrier","helps strengthen the skin''s barrier"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["moisturizers","فاني كريم"]'::jsonb, '{"title":{"ar":"فاني كريم واقي شمس 85 غرام - Luminous Derma","en":"فاني كريم Moisturizer 85 غرام - Luminous Derma"},"description":{"ar":"فاني كريم مرطب بحجم 85 غرام، يعمل على يرطب البشرة ويدعم حاجزها الطبيعي.","en":"فاني كريم Moisturizer (85 غرام) that hydrates the skin and supports its natural barrier."},"keywords":["luminous","moisturizers","فاني كريم"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('fe8bcb53-9923-573a-8666-a4e0cc397fad', 'yq-449', 'yq-449', 'YQ-449', '{"ar":"سيرافي غسول 236 مل","en":"CeraVe Cleanser 236 مل"}'::jsonb, '{"ar":"سيرافي منظف بحجم 236 مل، ينظف البشرة ويزيل الشوائب بلطف. كما أنه [ينظف و ينقي] غسول يومي للوجه والجسم ، يوزع كمنظف جل ويتحول إلى رغوة أثناء الاستخدام، وينعش بلطف ويزيل بشكل فعال الزيوت الزائدة والأوساخ والمكياج. طريقة الاستخدام: مناسب للتنظيف اليومي صباحًا ومساءً للبشرة العادية إلى الدهنية.","en":"سيرافي Cleanser (236 مل) that cleanses the skin and removes impurities gently."}'::jsonb, '1c48bc43-635e-5769-8a44-223edcb31ce7', 'b73b3a97-b924-5435-8662-59d9a0f2247f', '{"price":11800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/CeraVe_SA_Smoothing_Cleanser_for_normal_dry_and_rough_skin_236ml.jpg?v=1752919012"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/CeraVe_SA_Smoothing_Cleanser_for_normal_dry_and_rough_skin_236ml.jpg?v=1752919012"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه، مرتين يومياً، صباحاً ومساءً","en":"Apply to the face. Use daily, use morning and evening."}'::jsonb, '["Apply to the face.","Use daily, use morning and evening."]'::jsonb, '["ضعي على الوجه","مرتين يومياً، صباحاً ومساءً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["ينظف البشرة ويزيل الشوائب بلطف","يعيد للبشرة إحساس النظافة والانتعاش","يستخدم في روتين العناية صباحاً ومساءً"],"en":["cleanses the skin and removes impurities gently","restores a clean, refreshed feeling to the skin","used in both morning and evening care"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["cleansers","سيرافي"]'::jsonb, '{"title":{"ar":"سيرافي غسول 236 مل - Luminous Derma","en":"CeraVe Cleanser 236 مل - Luminous Derma"},"description":{"ar":"CeraVe منظف بحجم 236 مل، يعمل على ينظف البشرة ويزيل الشوائب بلطف.","en":"CeraVe Cleanser (236 مل) that cleanses the skin and removes impurities gently."},"keywords":["luminous","cleansers","سيرافي"]}'::jsonb);
