INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('718f9e87-d82d-5995-8ed0-7f3f061f9aad', 'yq-521', 'yq-521', 'YQ-521', '{"ar":"بيرفكت سيروم ترطيب واعاده بنا زيت شعر 100 مل","en":"بيرفكت Hair Oil 100 مل"}'::jsonb, '{"ar":"بيرفكت زيت شعر بحجم 100 مل، يغذي الشعر ويمنحه اللمعان. كما أنه يحتوي على سوائل عالية القيمة ومثبته وفعالة في الحفاظ على الشعر التالف والطبيعي على حد سواء، وهو مناسب ومبتكر لتسريح الشعر وتجعيده. طريقة الاستخدام: ضع 1 - 2 نقطة من سيروم الشعر على راحة اليدين، وافركه لمدة 5 ثوان بين يديك لجعله دافئًا.","en":"بيرفكت Hair Oil (100 مل) that nourishes the hair and adds shine."}'::jsonb, '20ef7886-9d7f-5583-81bb-b99eb35f29c9', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":4000,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1693048022_1.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1693048022_1.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي المنتج على شعر مبلل، ضعي على الشعر بالفرك","en":"Apply the product on damp hair. Apply to the hair, massaging gently."}'::jsonb, '["Apply the product on damp hair.","Apply to the hair, massaging gently."]'::jsonb, '["ضعي المنتج على شعر مبلل","ضعي على الشعر بالفرك"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يغذي الشعر ويمنحه اللمعان","يضفي على الشعر لمعاناً صحياً"],"en":["nourishes the hair and adds shine","adds a healthy shine to the hair"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["hair-oils","بيرفكت"]'::jsonb, '{"title":{"ar":"بيرفكت سيروم ترطيب واعاده بنا زيت شعر 100 مل - Luminous Derma","en":"بيرفكت Hair Oil 100 مل - Luminous Derma"},"description":{"ar":"بيرفكت زيت شعر بحجم 100 مل، يعمل على يغذي الشعر ويمنحه اللمعان.","en":"بيرفكت Hair Oil (100 مل) that nourishes the hair and adds shine."},"keywords":["luminous","hair-oils","بيرفكت"]}'::jsonb);
