INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('b24ddef0-4cb6-5adb-8741-937ca3112559', 'yq-568', 'yq-568', 'YQ-568', '{"ar":"لنس مي عدسات لاصقه كارميل","en":"لنس مي"}'::jsonb, '{"ar":"لنس مي عدسات لاصقة، ينظف العدسات اللاصقة ويحافظ عليها. كما أنه قدرة السطح على البلل، والمواد ومراقبة الجودة. طريقة الاستخدام: اغسل يديك بالماء والصابون.","en":"لنس مي Contact Lenses that cleans and preserves contact lenses."}'::jsonb, '8043af21-e349-5cd5-8ef8-16065fa94b2d', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":19800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1694215294_1.png","https://www.yaqootstoreye.com/files/items/item_1694215294_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1694215294_1.png","https://www.yaqootstoreye.com/files/items/item_1694215294_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"اغسل يديك بالماء والصابون . ضع العدسة على إصبعك السبابة. ارفع الجفن العلوي بلطف. اسحب الجفن السفلي لأسفل برفق. انظر جانبًا وضع العدسة على صلبة العين (المنطقة البيضاء). انظر للأمام حتى تتمركز العدسة في الزاوية. التحذيرات والاحتياطات : اغسل يديك جيدًا عند استخدام العدسات. تجنب تعرض العين للغبار مباشرة. تجنب دخول الصابون أو مستحضرات التجميل داخل العين. تجنب استخدام العدسات أكثر من الفترة المسموح بها. تجنب استخدام العدسات بعد انتهاء الصلاحية. يجب حفظ العدسات في المحلول بعد الاستعمال. المكونات : عدسات لنس مي مصنوعة من مادة البوليماكون وقطرها ١٤.٢ ونسبة الماء ٣٨٪ مما يجعل عينك براحة تامة بسبب الترطيب. مدة انتهاء صلاحية الاستعمال ٦ أشهر بعد اول استعمال.","en":"اغسل يديك بالماء والصابون . ضع العدسة على إصبعك السبابة. ارفع الجفن العلوي بلطف. اسحب الجفن السفلي لأسفل برفق. انظر جانبًا وضع العدسة على صلبة العين (المنطقة البيضاء). انظر للأمام حتى تتمركز العدسة في الزاوية. التحذيرات والاحتياطات : اغسل يديك جيدًا عند استخدام العدسات. تجنب تعرض العين للغبار مباشرة. تجنب دخول الصابون أو مستحضرات التجميل داخل العين. تجنب استخدام العدسات أكثر من الفترة المسموح بها. تجنب استخدام العدسات بعد انتهاء الصلاحية. يجب حفظ العدسات في المحلول بعد الاستعمال. المكونات : عدسات لنس مي مصنوعة من مادة البوليماكون وقطرها ١٤.٢ ونسبة الماء ٣٨٪ مما يجعل عينك براحة تامة بسبب الترطيب. مدة انتهاء صلاحية الاستعمال ٦ أشهر بعد اول استعمال."}'::jsonb, '["اغسل يديك بالماء والصابون","ضع العدسة على إصبعك السبابة","ارفع الجفن العلوي بلطف","اسحب الجفن السفلي لأسفل برفق","انظر جانبًا وضع العدسة على صلبة العين (المنطقة البيضاء)","انظر للأمام حتى تتمركز العدسة في الزاوية","التحذيرات والاحتياطات : اغسل يديك جيدًا عند استخدام العدسات","تجنب تعرض العين للغبار مباشرة","تجنب دخول الصابون أو مستحضرات التجميل داخل العين","تجنب استخدام العدسات أكثر من الفترة المسموح بها","تجنب استخدام العدسات بعد انتهاء الصلاحية","يجب حفظ العدسات في المحلول بعد الاستعمال","المكونات : عدسات لنس مي مصنوعة من مادة البوليماكون وقطرها ١٤","٢ ونسبة الماء ٣٨٪ مما يجعل عينك براحة تامة بسبب الترطيب","مدة انتهاء صلاحية الاستعمال ٦ أشهر بعد اول استعمال"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["ينظف العدسات اللاصقة ويحافظ عليها","يحافظ على نظافة العدسات"],"en":["cleans and preserves contact lenses","keeps lenses clean"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["contact-lenses","لنس مي"]'::jsonb, '{"title":{"ar":"لنس مي عدسات لاصقه كارميل - Luminous Derma","en":"لنس مي - Luminous Derma"},"description":{"ar":"لنس مي contact-lenses، يعمل على ينظف العدسات اللاصقة ويحافظ عليها.","en":"لنس مي contact-lenses that cleans and preserves contact lenses."},"keywords":["luminous","contact-lenses","لنس مي"]}'::jsonb);
