INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('d901b832-344f-5a0e-8e2b-cd889c08ac1f', 'yq-573', 'yq-573', 'YQ-573', '{"ar":"لاروش بوزية كريم علاج شوائب ديو بلس معا 30% حمايه من الشمس 40 مل","en":"La Roche-Posay Moisturizer 40 مل"}'::jsonb, '{"ar":"لاروش بوزية مرطب بحجم 40 مل بتركيز 30%، يرطب البشرة ويدعم حاجزها الطبيعي. كما أنه مختبر ضد النيكل (مطور للأشخاص الذين لديهم حساسية ضد النيكل)، ومناسب من عمر +12 سنة. طريقة الاستخدام: يستعمل على كل الوجه في الصباح و / أو المساء بعد تنظيف البشرة بجيل إيفاكلار جل غسول رغوي.","en":"لاروش بوزية Moisturizer (40 مل, 30%) that hydrates the skin and supports its natural barrier."}'::jsonb, 'a16f522c-12bf-569c-8fd3-72a53a3a2c58', '8c88bc9f-1413-5364-87ea-b2e44dfd4b5d', '{"price":11800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/LaRoche-PosayEffaclarHIsobiomeMoisturizingCreamforoily_andacneproneskin40ml.jpg?v=1714979708"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/LaRoche-PosayEffaclarHIsobiomeMoisturizingCreamforoily_andacneproneskin40ml.jpg?v=1714979708"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"بعد تنظيف البشرة، ضعي على الوجه، صباحاً","en":"بعد تنظيف البشرة. Apply to the face. ."}'::jsonb, '["بعد تنظيف البشرة.","Apply to the face.","."]'::jsonb, '["بعد تنظيف البشرة","ضعي على الوجه","صباحاً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يرطب البشرة ويدعم حاجزها الطبيعي","يساعد على تقوية حاجز البشرة","يستخدم في روتين العناية صباحاً ومساءً"],"en":["hydrates the skin and supports its natural barrier","helps strengthen the skin''s barrier","used in both morning and evening care"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["moisturizers","لاروش بوزية"]'::jsonb, '{"title":{"ar":"لاروش بوزية كريم علاج شوائب ديو بلس معا 30% حمايه من الشمس 40 مل - Luminous Derma","en":"La Roche-Posay Moisturizer 40 مل - Luminous Derma"},"description":{"ar":"La Roche-Posay مرطب بحجم 40 مل بتركيز 30%، يعمل على يرطب البشرة ويدعم حاجزها الطبيعي.","en":"La Roche-Posay Moisturizer (40 مل), 30% that hydrates the skin and supports its natural barrier."},"keywords":["luminous","moisturizers","لاروش بوزية"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('b1744191-aa27-52d8-87b2-0171febc0888', 'yq-574', 'yq-574', 'YQ-574', '{"ar":"كريم كاب مقشر والجسم مبيض علبه 500 مل","en":"كريم كاب 500 مل"}'::jsonb, '{"ar":"كريم كاب مقشر جسم بحجم 500 مل، يقشر الجسم بلطف ويحسن ملمسه. كما أنه تحافظ التركيبة المرطبة على بشرتك ناعمة ونضرة لاستعادة مظهرها الطبيعي، ويمكنك استخدام هذا الكريم مرة أو مرتين أسبوعيًا للحصول على نتائج متسقة. طريقة الاستخدام: بللي البشرة بماء دافيء.","en":"كريم كاب Body Scrub (500 مل) that gently exfoliates the body and improves texture."}'::jsonb, 'fe65be64-8785-5ecd-8af9-bdcccfa49dde', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":7300,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1694559308_1.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1694559308_1.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الجسم بحركات دائرية، اتركيه لمدة 2-3 دقائق، اشطفي بالماء جيداً ثم جففي بلطف","en":"Apply to the body, massaging gently. Leave it لمدة 2-3 دقائق. Rinse well with water, then pat dry."}'::jsonb, '["Apply to the body, massaging gently.","Leave it لمدة 2-3 دقائق.","Rinse well with water, then pat dry."]'::jsonb, '["ضعي على الجسم بحركات دائرية","اتركيه لمدة 2-3 دقائق","اشطفي بالماء جيداً ثم جففي بلطف"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يقشر الجسم بلطف ويحسن ملمسه","ينعم بشرة الجسم"],"en":["gently exfoliates the body and improves texture","smooths the body''s skin"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["body-scrubs","كريم كاب"]'::jsonb, '{"title":{"ar":"كريم كاب مقشر والجسم مبيض علبه 500 مل - Luminous Derma","en":"كريم كاب 500 مل - Luminous Derma"},"description":{"ar":"كريم كاب body-scrubs بحجم 500 مل، يعمل على يقشر الجسم بلطف ويحسن ملمسه.","en":"كريم كاب body-scrubs (500 مل) that gently exfoliates the body and improves texture."},"keywords":["luminous","body-scrubs","كريم كاب"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('05571b0c-8507-5350-89e2-7244c5a947ec', 'yq-575', 'yq-575', 'YQ-575', '{"ar":"فيشي شامبو ديركوس مضاد للقشره العادي والجاف 200 مل","en":"Vichy Shampoo 200 مل"}'::jsonb, '{"ar":"فيشي شامبو بحجم 200 مل، ينظف الشعر بلطف. كما أنه شامبو يعمل ضد القشرة مع العناية بالشعر الجاف. طريقة الاستخدام: قومي بالتدليك بلطف للشعر المبلل.","en":"فيشي Shampoo (200 مل) that cleanses the hair gently."}'::jsonb, 'e96e9919-f71c-53bd-80be-bd4e1416c366', '68578e61-8ce0-5cf4-8ef7-763d60703186', '{"price":11300,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/Vichy_Normaderm_Phytosolution_Face_Cleanser_Gel_for_Oily-Acne_Skin_with_Salicylic_Acid_200ml.jpg?v=1754382679"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/Vichy_Normaderm_Phytosolution_Face_Cleanser_Gel_for_Oily-Acne_Skin_with_Salicylic_Acid_200ml.jpg?v=1754382679"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"دلكي على الشعر، اشطفي بالماء جيداً ثم جففي بلطف","en":"Massage into the hair. Rinse well with water, then pat dry."}'::jsonb, '["Massage into the hair.","Rinse well with water, then pat dry."]'::jsonb, '["دلكي على الشعر","اشطفي بالماء جيداً ثم جففي بلطف"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["ينظف الشعر بلطف","يعتني بنظافة فروة الرأس"],"en":["cleanses the hair gently","cares for scalp cleanliness"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["shampoo","فيشي"]'::jsonb, '{"title":{"ar":"فيشي شامبو ديركوس مضاد للقشره العادي والجاف 200 مل - Luminous Derma","en":"Vichy Shampoo 200 مل - Luminous Derma"},"description":{"ar":"Vichy شامبو بحجم 200 مل، يعمل على ينظف الشعر بل