INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('1886999a-d9d9-539b-8498-c7a3910ed384', 'yq-610', 'yq-610', 'YQ-610', '{"ar":"انجلوت قطره مكياج eye 9 مل","en":"انجلوت Eye Makeup 9 مل"}'::jsonb, '{"ar":"انجلوت مكياج عيون بحجم 9 مل، يبرز جمال العينين. كما أنه وهي ملائمة للبشرة الحساسة ولا تتسبب في إثارة الجلد، وقطره تعمل على تثبيت ظلال العين وتحويله الى ايلاينر بمظهر متألق وثابت طوال اليوم. طريقة الاستخدام: انغلوت ديورالين هي عبارة عن سائل شفاف خالٍ من الماء يمكن استخدامها لتكثيف لون أيّ بودرة وتحويلها إلى مستحضر مقاوم للماء سهل التطبيق.","en":"انجلوت Eye Makeup (9 مل) that enhances the eyes."}'::jsonb, '794844d7-e95c-5b3b-8cd2-4e6ed5c56ab0', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":9800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1696306924_1.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1696306924_1.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"انغلوت ديورالين هي عبارة عن سائل شفاف خالٍ من الماء يمكن استخدامها لتكثيف لون أيّ بودرة وتحويلها إلى مستحضر مقاوم للماء سهل التطبيق. وهي ملائمة للبشرة الحساسة ولا تتسبب في إثارة الجلد. قطره تعمل على تثبيت ظلال العين وتحويله الى ايلاينر بمظهر متألق وثابت طوال اليوم. مستخلص من الهيدروكربون والسيلكون. اختيار مثالي للحصول على تثبيت عالي لمكياجك مما يزيد من تألق حضورك","en":"انغلوت ديورالين هي عبارة عن سائل شفاف خالٍ من الماء يمكن استخدامها لتكثيف لون أيّ بودرة وتحويلها إلى مستحضر مقاوم للماء سهل التطبيق. وهي ملائمة للبشرة الحساسة ولا تتسبب في إثارة الجلد. قطره تعمل على تثبيت ظلال العين وتحويله الى ايلاينر بمظهر متألق وثابت طوال اليوم. مستخلص من الهيدروكربون والسيلكون. اختيار مثالي للحصول على تثبيت عالي لمكياجك مما يزيد من تألق حضورك"}':