INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('bb3e9bdb-fe04-5631-8906-edca0e604077', 'yq-620', 'yq-620', 'YQ-620', '{"ar":"آرت ناتشورالز ماسك ب الارغان والصبار الطبيعي 226 غرام","en":"آرت ناتشورالز 226 غرام"}'::jsonb, '{"ar":"آرت ناتشورالز قناع شعر بحجم 226 غرام، يغذي الشعر بعمق. كما أنه نحن نؤمن أن منتجات التجميل العلاجية يجب أن تُستخرج من أنقى المصادر الطبيعية، ونحن نجمع أجود المكونات والمستخلصات من جميع أنحاء العالم. طريقة الاستخدام: بعد غسل الشعر بشامبو وبلسم artnaturals® بزيت الأرجان، يُوضع القناع ثم يُمشط الشعر حتى يتخلله.","en":"آرت ناتشورالز Hair Mask (226 غرام) that deeply nourishes the hair."}'::jsonb, 'ace4cbf7-da7a-5f25-8c15-68cf00271bf6', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":7000,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1696551183_1.png","https://www.yaqootstoreye.com/files/items/item_1696551183_2.png","https://www.yaqootstoreye.com/files/items/item_1696551183_3.png","https://www.yaqootstoreye.com/files/items/item_1696551183_4.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1696551183_1.png","https://www.yaqootstoreye.com/files/items/item_1696551183_2.png","https://www.yaqootstoreye.com/files/items/item_1696551183_3.png","https://www.yaqootstoreye.com/files/items/item_1696551183_4.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي المنتج على شعر نظيف ومبلل، ضعي على الشعر، اتركيه لمدة المحددة على العبوة، اشطفي بالماء جيداً ثم جففي بلطف، مرتين إلى ثلاث مرات أسبوعياً","en":"Apply the product to شعر نظيف ومبلل. Apply to the hair. Leave it لمدة المحددة على العبوة. Rinse well with water, then pat dry. Two to three times a week."}'::jsonb, '["Apply the product to شعر نظيف ومبلل.","Apply to the hair.","Leave it لمدة المحددة على العبوة.","Rinse well with water, then pat dry.","Two to three times a week."]'::jsonb, '["ضعي المنتج على شعر نظيف ومبلل","ضعي على الشعر","اتركيه لمدة المحددة على العبوة","اشطفي بالماء جيداً ثم جففي بلطف","مرتين إلى ثلاث مرات أسبوعياً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يغذي الشعر بعمق","يمنح الشعر ترطيباً مكثفاً"],"en":["deeply nourishes the hair","provides intensive hair hydration"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["hair-masks","آرت ناتشورالز"]'::jsonb, '{"title":{"ar":"آرت ناتشورالز ماسك ب الارغان والصبار الطبيعي 226 غرام - Luminous Derma","en":"آرت ناتشورالز 226 غرام - Luminous Derma"},"description":{"ar":"آرت ناتشورالز hair-masks بحجم 226 غرام، يعمل على يغذي الشعر بعمق.","en":"آرت ناتشورالز hair-masks (226 غرام) that deeply nourishes the hair."},"keywords":["luminous","hair-masks","آرت ناتشورالز"]}'::jsonb);
