INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('9bf47323-eb8e-585e-8721-eb84d35671ac', 'yq-684', 'yq-684', 'YQ-684', '{"ar":"يوني برو زجاجه محموله فارغه بمضخه رغوه","en":"يوني برو"}'::jsonb, '{"ar":"يوني برو أدوات تجميل، يساعد في العناية بالبشرة والجسم. كما أنه - يتميز بتصميم رأس الفرشاة، عملي لاستخدام موزع الرغوة، و- كل ما تحتاجه لرحلاتك عندما تريد إحضار سوائل الرغوة الخاصة بك.","en":"يوني برو Beauty Tools that supports skin and body care."}'::jsonb, '1cfb5456-8a59-5f1b-8ba2-e7c3af72be9a', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":4500,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1697957556_1.png","https://www.yaqootstoreye.com/files/items/item_1697957556_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1697957556_1.png","https://www.yaqootstoreye.com/files/items/item_1697957556_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"الخصائص - المادة: موزع رغوة بلاستيكي - اللون: زجاجة فرعية إسفنجية شفافة - السعة: زجاجة رغوة جل استحمام مريحة 120 مل - تتضمن المجموعة زجاجات فارغة متعددة القطع بكمية كافية لاستخدام الزجاجة الفرعية أو استبدالها أو مشاركتها. - يتميز بتصميم رأس الفرشاة، عملي لاستخدام موزع الرغوة. - كل ما تحتاجه لرحلاتك عندما تريد إحضار سوائل الرغوة الخاصة بك! حاويات رغوة - يمنع الإغلاق المحكم للزجاجة أي تسرب، لذلك يمكنك وضع الزجاجة بأمان في الحقيبة دون القلق بشأن تسرب السائل لمضخة الزجاجات الرغوية. - استخدامات واسعة، تناسب بشكل جيد الصابون أو الشامبو أو جل الاستحمام أو منظف الوجه، تلبي احتياجاتك المختلفة بسهولة زجاجة رغوة محمولة. وصف البضائع زجاجة صغيرة بمضخة - زجاجة الرغوة مصنوعة من مواد صغيرة الحجم وسهلة الحمل. زجاجة شامبو فارغة، هذه الزجاجة الرغوية قابلة لإعادة الملء وقابلة لإعادة الاستخدام ومتينة وآمنة للاستخدام. موزع للسفر لتخزين اللوشن والشامبو السائل ومنظف الوجه والبلسم وجل الاستحمام وما إلى ذلك. زجاجة فرشاة توزيع الرغوة، إنها حاوية مثالية للرحلات والتنزه والسفر وما إلى ذلك","en":"الخصائص - المادة: موزع رغوة بلاستيكي - اللون: زجاجة فرعية إسفنجية شفافة - السعة: زجاجة رغوة جل استحمام مريحة 120 مل - تتضمن المجموعة زجاجات فارغة متعددة القطع بكمية كافية لاستخدام الزجاجة الفرعية أو استبدالها أو مشاركتها. - يتميز بتصميم رأس الفرشاة، عملي لاستخدام موزع الرغوة. - كل ما تحتاجه لرحلاتك عندما تريد إحضار سوائل الرغوة الخاصة بك! حاويات رغوة - يمنع الإغلاق المحكم للزجاجة أي تسرب، لذلك يمكنك وضع الزجاجة بأمان في الحقيبة دون القلق بشأن تسرب السائل لمضخة الزجاجات الرغوية. - استخدامات واسعة، تناسب بشكل جيد الصابون أو الشامبو أو جل الاستحمام أو منظف الوجه، تلبي احتياجاتك المختلفة بسهولة زجاجة رغوة محمولة. وصف البضائع زجاجة صغيرة بمضخة - زجاجة الرغوة مصنوعة من مواد صغيرة الحجم وسهلة الحمل. زجاجة شامبو فارغة، هذه الزجاجة الرغوية قابلة لإعادة الملء وقابلة لإعادة الاستخدام ومتينة وآمنة للاستخدام. موزع للسفر لتخزين اللوشن والشامبو السائل ومنظف الوجه والبلسم وجل الاستحمام وما إلى ذلك. زجاجة فرشاة توزيع الرغوة، إنها حاوية مثالية للرحلات والتنزه والسفر وما إلى ذلك"}'::jsonb, '["الخصائص - المادة: موزع رغوة بلاستيكي - اللون: زجاجة فرعية إسفنجية شفافة - السعة: زجاجة رغوة جل استحمام مريحة 120 مل - تتضمن المجموعة زجاجات فارغة متعددة القطع بكمية كافية لاستخدام الزجاجة الفرعية أو استبدالها أو مشاركتها","- يتميز بتصميم رأس الفرشاة، عملي لاستخدام موزع الرغوة","- كل ما تحتاجه لرحلاتك عندما تريد إحضار سوائل الرغوة الخاصة بك! حاويات رغوة - يمنع الإغلاق المحكم للزجاجة أي تسرب، لذلك يمكنك وضع الزجاجة بأمان في الحقيبة دون القلق بشأن تسرب السائل لمضخة الزجاجات الرغوية","- استخدامات واسعة، تناسب بشكل جيد الصابون أو الشامبو أو جل الاستحمام أو منظف الوجه، تلبي احتياجاتك المختلفة بسهولة زجاجة رغوة محمولة","وصف البضائع زجاجة صغيرة بمضخة - زجاجة الرغوة مصنوعة من مواد صغيرة الحجم وسهلة الحمل","زجاجة شامبو فارغة، هذه الزجاجة الرغوية قابلة لإعادة الملء وقابلة لإعادة الاستخدام ومتينة وآمنة للاستخدام","موزع للسفر لتخزين اللوشن والشامبو السائل ومنظف الوجه والبلسم وجل الاستحمام وما إلى ذلك","زجاجة فرشاة توزيع الرغوة، إنها حاوية مثالية للرحلات والتنزه والسفر وما إلى ذلك"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يساعد في العناية بالبشرة والجسم","يساعد على إتمام العناية بسهولة"],"en":["supports skin and body care","helps complete care easily"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["beauty-tools","يوني برو"]'::jsonb, '{"title":{"ar":"يوني برو زجاجه محموله فارغه بمضخه رغوه - Luminous Derma","en":"يوني برو - Luminous Derma"},"description":{"ar":"يوني برو beauty-tools، يعمل على يساعد في العناية بالبشرة والجسم.","en":"يوني برو beauty-tools that supports skin and body care."},"keywords":["luminous","beauty-tools","يوني برو"]}'::jsonb);
