INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('889b5ca8-8cdc-5914-8fcb-8302b685cca0', 'yq-694', 'yq-694', 'YQ-694', '{"ar":"جمجوم فارما اكرتين 0.025% كريم 30 غرام","en":"جمجوم فارما Moisturizer 30 غرام"}'::jsonb, '{"ar":"جمجوم فارما مرطب بحجم 30 غرام بتركيز 0.025%، يرطب البشرة ويدعم حاجزها الطبيعي. كما أنه تريتينوين هو دواء يستخدم لعلاج حب الشباب، ولم يتم إثبات سلامة وفعالية الاستخدام طويل الأمد لهذا الدواء في علاج أمراض أخرى. طريقة الاستخدام: اغسل بشرتك بلطف بصابون لطيف غير علاجي مرتين إلى ثلاث مرات يوميًا ثم جفف الجلد بمنشفة.","en":"جمجوم فارما Moisturizer (30 غرام, 0.025%) that hydrates the skin and supports its natural barrier."}'::jsonb, 'a16f522c-12bf-569c-8fd3-72a53a3a2c58', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":2700,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1698049178_1.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1698049178_1.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"بعد التنظيف، ضعي على الوجه بالفرك، اتركيه لمدة دقيقة إلى دقيقتين، مرة واحدة يومياً، قبل النوم، تنبيه: توقفي عن الاستخدام عند حدوث تهيج","en":"After cleansing. Apply to the face, massaging gently. Leave it for one to two minutes. Use daily, use before bed. Note: discontinue use if irritation occurs."}'::jsonb, '["After cleansing.","Apply to the face, massaging gently.","Leave it for one to two minutes.","Use daily, use before bed.","Note: discontinue use if irritation occurs."]'::jsonb, '["بعد التنظيف","ضعي على الوجه بالفرك","اتركيه لمدة دقيقة إلى دقيقتين","مرة واحدة يومياً، قبل النوم","تنبيه: توقفي عن الاستخدام عند حدوث تهيج"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يرطب البشرة ويدعم حاجزها الطبيعي","يساعد على تقوية حاجز البشرة","بتركيز 0.025% من المكون النشط","يستخدم في روتين العناية صباحاً ومساءً"],"en":["hydrates the skin and supports its natural barrier","helps strengthen the skin''s barrier","with a 0.025% concentration of the active ingredient","used in both morning and evening care"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["moisturizers","جمجوم فارما"]'::jsonb, '{"title":{"ar":"جمجوم فارما اكرتين 0.025% كريم 30 غرام - Luminous Derma","en":"جمجوم فارما Moisturizer 30 غرام - Luminous Derma"},"description":{"ar":"جمجوم فارما مرطب بحجم 30 غرام بتركيز 0.025%، يعمل على يرطب البشرة ويدعم حاجزها الطبيعي.","en":"جمجوم فارما Moisturizer (30 غرام), 0.025% that hydrates the skin and supports its natural barrier."},"keywords":["luminous","moisturizers","جمجوم فارما"]}'::jsonb);
