INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('18f6f2d6-fd45-5b15-84c1-bafbe0d49f6e', 'yq-698', 'yq-698', 'YQ-698', '{"ar":"لوريال شامبو للعشر الفيف توتال ريبير 400 مل","en":"لوريال Shampoo 400 مل"}'::jsonb, '{"ar":"لوريال شامبو بحجم 400 مل، ينظف الشعر بلطف. طريقة الاستخدام: اتبع برنـامج إلفيف 5 للإصلاح الشامل: قومي بتنظيف شعرك واستعادة لمعانه باستخدام شامبو إلفيف 5 للإصلاح الشامل.","en":"لوريال Shampoo (400 مل) that cleanses the hair gently."}'::jsonb, 'e96e9919-f71c-53bd-80be-bd4e1416c366', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":8970,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/LorealParisElnettNormalHoldHairspray400ml.jpg?v=1768045616"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/LorealParisElnettNormalHoldHairspray400ml.jpg?v=1768045616"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"اتبع برنـامج إلفيف 5 للإصلاح الشامل: قومي بتنظيف شعرك واستعادة لمعانه باستخدام شامبو إلفيف 5 للإصلاح الشامل. قم بترطيب شعرك واستعادة لمعانه باستخدام بلسم إلفيف 5 للإصلاح الشامل. عالجي شعرك بانتظام باستخدام قناع إلفيف 5 للإصلاح الشامل، بخاخ بلسم ومعجزة فورية.","en":"اتبع برنـامج إلفيف 5 للإصلاح الشامل: قومي بتنظيف شعرك واستعادة لمعانه باستخدام شامبو إلفيف 5 للإصلاح الشامل. قم بترطيب شعرك واستعادة لمعانه باستخدام بلسم إلفيف 5 للإصلاح الشامل. عالجي شعرك بانتظام باستخدام قناع إلفيف 5 للإصلاح الشامل، بخاخ بلسم ومعجزة فورية."}'::jsonb, '["اتبع برنـامج إلفيف 5 للإصلاح الشامل: قومي بتنظيف شعرك واستعادة لمعانه باستخدام شامبو إلفيف 5 للإصلاح الشامل","قم بترطيب شعرك واستعادة لمعانه باستخدام بلسم إلفيف 5 للإصلاح الشامل","عالجي شعرك بانتظام باستخدام قناع إلفيف 5 للإصلاح الشامل، بخاخ بلسم ومعجزة فورية"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["ينظف الشعر بلطف","يعتني بنظافة فروة الرأس"],"en":["cleanses the hair gently","cares for scalp cleanliness"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["shampoo","لوريال"]'::jsonb, '{"title":{"ar":"لوريال شامبو للعشر الفيف توتال ريبير 400 مل - Luminous Derma","en":"لوريال Shampoo 400 مل - Luminous Derma"},"description":{"ar":"لوريال شامبو بحجم 400 مل، يعمل على ينظف الشعر بلطف.","en":"لوريال Shampoo (400 مل) that cleanses the hair gently."},"keywords":["luminous","shampoo","لوريال"]}'::jsonb);
