INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('b9d49b54-871e-5eff-831a-c1da1c8af933', 'yq-702', 'yq-702', 'YQ-702', '{"ar":"لوريال بديل الزيت ايلفيف معالجه كامله 300 مل","en":"لوريال 300 مل"}'::jsonb, '{"ar":"لوريال كريم شعر بحجم 300 مل، يغذي الشعر ويسهل تصفيفه. كما أنه بديل الزيت من لوريال باريس للشعر التالف، وبمستخلص الكيراتين و السيراميد سيعمل على إصلاح ألياف شعرك. طريقة الاستخدام: قبل الاستحمام: ضعي كمية هامة علي شعرك بعد استعمال الشامبو ثم اغسليه خلال الاستحمام: ضعيه علي شعرك بعد استعمال الشامبو ثم اغسليه.","en":"لوريال Hair Cream (300 مل) that nourishes the hair and eases styling."}'::jsonb, '186e55a4-e021-5598-830c-1cd2854d9c8c', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":3800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1698121027_1.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1698121027_1.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"بعد الاستحمام، ضعي على الشعر، اشطفي بالماء جيداً ثم جففي بلطف","en":"After showering. Apply to the hair. Rinse well with water, then pat dry."}'::jsonb, '["After showering.","Apply to the hair.","Rinse well with water, then pat dry."]'::jsonb, '["بعد الاستحمام","ضعي على الشعر","اشطفي بالماء جيداً ثم جففي بلطف"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يغذي الشعر ويسهل تصفيفه","يسهل تصفيف الشعر","يستخدم في روتين العناية المسائي"],"en":["nourishes the hair and eases styling","makes styling easier","used in an evening care routine"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["hair-creams","لوريال"]'::jsonb, '{"title":{"ar":"لوريال بديل الزيت ايلفيف معالجه كامله 300 مل - Luminous Derma","en":"لوريال 300 مل - Luminous Derma"},"description":{"ar":"لوريال hair-creams بحجم 300 مل، يعمل على يغذي الشعر ويسهل تصفيفه.","en":"لوريال hair-creams (300 مل) that nourishes the hair and eases styling."},"keywords":["luminous","hair-creams","لوريال"]}'::jsonb);
