INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('6b8080ce-009f-5d68-814c-8ecdeb3c85d3', 'yq-806', 'yq-806', 'YQ-806', '{"ar":"افين واقي شمس مرطب 50 مل","en":"Avene Moisturizer 50 مل"}'::jsonb, '{"ar":"افين مرطب بحجم 50 مل، يرطب البشرة ويدعم حاجزها الطبيعي. كما أنه حافظ على حماية بشرتك من أشعة الشمس باستخدام سائل أفين الواقي من الشمس، وإنه مـصنوع من مكونات عالية الجودة للحفاظ على رطوبة بشرتك. طريقة الاستخدام: ضعيه بشكل متساوٍ وبكمية وافرة قبل التعرض للشمس (كمية أقل من المنتج تقلل من مستوى الحماية من أشعة الشمس).","en":"افين Moisturizer (50 مل) that hydrates the skin and supports its natural barrier."}'::jsonb, 'a16f522c-12bf-569c-8fd3-72a53a3a2c58', 'b2855a57-b310-5b46-8eaf-690086e05c1f', '{"price":11800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/AveneVitaminActivCgRadianceIntensiveCream50ml.jpg?v=1783771173"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/AveneVitaminActivCgRadianceIntensiveCream50ml.jpg?v=1783771173"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه، بعد السباحة أو التعرق","en":"Apply to the face. ."}'::jsonb, '["Apply to the face.","."]'::jsonb, '["ضعي على الوجه","بعد السباحة أو التعرق"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يرطب البشرة ويدعم حاجزها الطبيعي","يساعد على تقوية حاجز البشرة"],"en":["hydrates the skin and supports its natural barrier","helps strengthen the skin''s barrier"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["moisturizers","افين"]'::jsonb, '{"title":{"ar":"افين واقي شمس مرطب 50 مل - Luminous Derma","en":"Avene Moisturizer 50 مل - Luminous Derma"},"description":{"ar":"Avene مرطب بحجم 50 مل، يعم