INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('9b7df714-f23d-55c1-8404-34ca628089cb', 'yq-820', 'yq-820', 'YQ-820', '{"ar":"جمجوم فارما اكرتين 0.5% كريم مقشرات 30 غرام","en":"جمجوم فارما Exfoliator 30 غرام"}'::jsonb, '{"ar":"جمجوم فارما مقشرات بحجم 30 غرام بتركيز 0.5%، يقشر البشرة بلطف ويزيل الخلايا الميتة. كما أنه تريتينوين هو دواء يستخدم لعلاج حب الشباب، ولم يتم إثبات سلامة وفعالية الاستخدام طويل الأمد لهذا الدواء في علاج أمراض أخرى. طريقة الاستخدام: اغسل بشرتك بلطف بصابون لطيف غير علاجي مرتين إلى ثلاث مرات يوميًا ثم جفف الجلد بمنشفة.","en":"جمجوم فارما Exfoliator (30 غرام, 0.5%) that gently exfoliates and removes dead cells."}'::jsonb, '7907841f-c414-5d82-814f-9ef070c20c6d', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":2700,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1703312586_1.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1703312586_1.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"بعد التنظيف، ضعي على الوجه بالفرك، اتركيه لمدة دقيقة إلى دقيقتين، مرة واحدة يومياً، قبل النوم، تنبيه: توقفي عن الاستخدام عند حدوث تهيج","en":"After cleansing. Apply to the face, massaging gently. Leave it for one to two minutes. Use daily, use before bed. Note: discontinue use if irritation occurs."}'::jsonb, '["After cleansing.","Apply to the face, massaging gently.","Leave it for one to two minutes.","Use daily, use before bed.","Note: discontinue use if irritation occurs."]'::jsonb, '["بعد التنظيف","ضعي على الوجه بالفرك","اتركيه لمدة دقيقة إلى دقيقتين","مرة واحدة يومياً، قبل النوم","تنبيه: توقفي عن الاستخدام عند حدوث تهيج"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يقشر البشرة بلطف ويزيل الخلايا الميتة","يزيل الخلايا الميتة بلطف","بتركيز 0.5% من المكون النشط","يستخدم في روتين العناية صباحاً ومساءً"],"en":["gently exfoliates and removes dead cells","gently removes dead skin cells","with a 0.5% concentration of the active ingredient","used in both morning and evening care"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["exfoliators","جمجوم فارما"]'::jsonb, '{"title":{"ar":"جمجوم فارما اكرتين 0.5% كريم مقشرات 30 غرام - Luminous Derma","en":"جمجوم فارما Exfoliator 30 غرام - Luminous Derma"},"description":{"ar":"جمجوم فارما مقشرات بحجم 30 غرام بتركيز 0.5%، يعمل على يقشر البشرة بلطف ويزيل الخلايا الميتة.","en":"جمجوم فارما Exfoliator (30 غرام), 0.5% that gently exfoliates and removes dead cells."},"keywords":["luminous","exfoliators","جمجوم فارما"]}'::jsonb);
