'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["hair-creams","كانتو"]'::jsonb, '{"title":{"ar":"كانتو كريم زبده الشيا للتنعيم يترك شعر طبيعي 340 غرام - Luminous Derma","en":"كانتو 340 غرام - Luminous Derma"},"description":{"ar":"كانتو hair-creams بحجم 340 غرام، يعمل على يغذي الشعر ويسهل تصفيفه.","en":"كانتو hair-creams (340 غرام) that nourishes the hair and eases styling."},"keywords":["luminous","hair-creams","كانتو"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('211bdf06-8d47-512a-80b4-94e23c6bfd79', 'yq-838', 'yq-838', 'YQ-838', '{"ar":"جيجون لصقات شرائح جل بالشاي الاخضر مدار مقشر","en":"جيجون Mask"}'::jsonb, '{"ar":"جيجون قناع بتركيبة جل، يمنح البشرة عناية مكثفة ومركزة. كما أنه لصقات جل للعين بالشاي الأخضر غنية بفوائد مضادة للأكسدة، مضادة للتجاعيد ومفتحة للبشرة، وتساعد على تهدئة وتلطيف البشرة الحساسة حول العين مع تحسين مرونتها واستعادة حيويتها. طريقة الاستخدام: توضع اللصقة على منطقة ما حول العين وتترك لمدة 20-30 دقيقة تتم ازالتها ويطبطب ما تبقى من المحلول على البشرة لامتصاصه.","en":"جيجون Mask that provides intensive, concentrated care."}'::jsonb, '7f592b99-dc96-5efe-84da-57dde42d581b', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":3960,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1704385992_1.png","https://www.yaqootstoreye.com/files/items/item_1704385992_2.png","https://www.yaqootstoreye.com/files/items/item_1704385992_3.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1704385992_1.png","https://www.yaqootstoreye.com/files/items/item_1704385992_2.png","https://www.yaqootstoreye.com/files/items/item_1704385992_3.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على البشرة، اتركيه لمدة دقيقة إلى دقيقتين","en":"Apply to the skin. Leave it for one to two minutes."}'::jsonb, '["Apply to the skin.","Leave it for one to two minutes."]'::jsonb, '["ضعي على البشرة","اتركيه لمدة دقيقة إلى دقيقتين"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يمنح البشرة عناية مكثفة ومركزة","يريح البشرة ويهدئها","تركيبة جل منعشة سهلة الاستخدام"],"en":["provides intensive, concentrated care","relaxes and soothes the skin","a refreshing gel formula that is easy to use"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["masks","جيجون"]'::jsonb, '{"title":{"ar":"جيجون لصقات شرائح جل بالشاي الاخضر مدار مقشر - Luminous Derma","en":"جيجون Mask - Luminous Derma"},"description":{"ar":"جيجون مقشر، يعمل على يمنح البشرة عناية مكثفة ومركزة ويأتي بتركيبة جل.","en":"جيجون Mask that provides intensive, concentrated care."},"keywords":["luminous","masks","جيجون"]}'::jsonb);
