INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('ab134e9f-89d1-5a21-8d92-4c7ea6d8822c', 'yq-871', 'yq-871', 'YQ-871', '{"ar":"يوسرين غسول المرطب الرغوي بحمض الهيالورونيك 150 مل","en":"Eucerin Cleanser 150 مل"}'::jsonb, '{"ar":"يوسرين منظف بتركيبة رغوية بحجم 150 مل، ينظف البشرة ويزيل الشوائب بلطف. كما أنه غسول الوجه اللطيف والقوي هذا يزيل المكياج العنيد المقاوم للماء وواقيات الشمس، وبشرة ناعمة ومنعشة هي مجرد تنظيف عند استخدام غسول الوجه الرغوي هذا. طريقة الاستخدام: استخدميه صباحًا ومساءً.","en":"يوسرين Cleanser (150 مل) that cleanses the skin and removes impurities gently."}'::jsonb, '1c48bc43-635e-5769-8a44-223edcb31ce7', '6df7e4c7-e844-5b73-8b84-93f4d255cf53', '{"price":9800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1708719530_1.jpg"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1708719530_1.jpg"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"دلكي على اليدين، اشطفي بالماء جيداً ثم جففي بلطف، مرتين يومياً، صباحاً ومساءً","en":"Massage into the hands. Rinse well with water, then pat dry. Use daily, use morning and evening."}'::jsonb, '["Massage into the hands.","Rinse well with water, then pat dry.","Use daily, use morning and evening."]'::jsonb, '["دلكي على اليدين","اشطفي بالماء جيداً ثم جففي بلطف","مرتين يومياً، صباحاً ومساءً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["ينظف البشرة ويزيل الشوائب بلطف","يعيد للبشرة إحساس النظافة والانتعاش","تركيبة رغوية خفيفة سهلة التوزيع","يستخدم في روتين العناية صباحاً ومساءً"],"en":["cleanses the skin and removes impurities gently","restores a clean, refreshed feeling to the skin","a light foam formula that spreads easily","used in both morning and evening care"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["cleansers","يوسرين"]'::jsonb, '{"title":{"ar":"يوسرين غسول المرطب الرغوي بحمض الهيالورونيك 150 مل - Luminous Derma","en":"Eucerin Cleanser 150 مل - Luminous Derma"},"description":{"ar":"Eucerin منظف بحجم 150 مل، يعمل على ينظف البشرة ويزيل الشوائب بلطف ويأتي بتركيبة رغوية.","en":"Eucerin Cleanser (150 مل) that cleanses the skin and removes impurities gently."},"keywords":["luminous","cleansers","يوسرين"]}'::jsonb);
