INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('0d2ff3d3-5d3c-5e92-8421-d8444682b270', 'yq-975', 'yq-975', 'YQ-975', '{"ar":"شيسيدو ماسك فينو الياباني لمعالجه 230 غرام","en":"شيسيدو 230 غرام"}'::jsonb, '{"ar":"شيسيدو علاج شعر بحجم 230 غرام، يعتني بفروة الرأس والشعر. كما أنه تغذية فائقة: يمنح الشعر تغذية فائقة ويساعد في استعادة ليونته ونعومته الطبيعية. طريقة الاستخدام: ضعي كمية مناسبة من المنتج (ملعقتين صغيرتين للشعر شبه الطويل) حول الجزء التالف من الشعر واتركيه حتى 2-5 دقائق.","en":"شيسيدو Hair Treatment (230 غرام) that cares for the scalp and hair."}'::jsonb, 'c25a581a-1a96-5e2f-8b7a-17ee7dee7bb1', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":12400,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1715743689_1.png","https://www.yaqootstoreye.com/files/items/item_1715743689_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1715743689_1.png","https://www.yaqootstoreye.com/files/items/item_1715743689_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الشعر كمية مناسبة، اتركيه لمدة دقيقة إلى دقيقتين، اشطفي بالماء جيداً ثم جففي بلطف، مرتين إلى ثلاث مرات أسبوعياً","en":"Apply an appropriate amount to the hair. Leave it for one to two minutes. Rinse well with water, then pat dry. Two to three times a week."}'::jsonb, '["Apply an appropriate amount to the hair.","Leave it for one to two minutes.","Rinse well with water, then pat dry.","Two to three times a week."]'::jsonb, '["ضعي على الشعر كمية مناسبة","اتركيه لمدة دقيقة إلى دقيقتين","اشطفي بالماء جيداً ثم جففي بلطف","مرتين إلى ثلاث مرات أسبوعياً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يعتني بفروة الرأس والشعر","يدعم