INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('bd339c14-6f81-5923-85f9-5cd92f50d18f', 'yq-1033', 'yq-1033', 'YQ-1033', '{"ar":"ريال تكنك بيوتي بلندر عدد 2 قطع","en":"ريال تكنك 2 قطع"}'::jsonb, '{"ar":"ريال تكنك أدوات مكياج بحجم 2 قطع، يساعد في تطبيق المكياج بدقة. كما أنه تم جمع اسفنجة ميراكل كومبليكشن مع اسفنجة ميراكل باودر للحصول على ثنائي ديناميكي، وابدئي بوضع كريم الأساس السائل بواسطة اسفنجة ميراكل كومبليكشن. طريقة الاستخدام: تم جمع اسفنجة ميراكل كومبليكشن مع اسفنجة ميراكل باودر للحصول على ثنائي ديناميكي.","en":"ريال تكنك Makeup Tools (2 قطع) that helps apply makeup precisely."}'::jsonb, '6aca8d3a-a783-5bc6-8bfc-dfe5d8cab962', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":4800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1722309102_1.png","https://www.yaqootstoreye.com/files/items/item_1722309102_2.png","https://www.yaqootstoreye.com/files/items/item_1722309102_3.png","https://www.yaqootstoreye.com/files/items/item_1722309102_4.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1722309102_1.png","https://www.yaqootstoreye.com/files/items/item_1722309102_2.png","https://www.yaqootstoreye.com/files/items/item_1722309102_3.png","https://www.yaqootstoreye.com/files/items/item_1722309102_4.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"تم جمع اسفنجة ميراكل كومبليكشن مع اسفنجة ميراكل باودر للحصول على ثنائي ديناميكي! ابدئي بوضع كريم الأساس السائل بواسطة اسفنجة ميراكل كومبليكشن. ضعي مساحيق اللمسات النهائية بواسطة اسفنجة ميراكل باودر للحصول على مزيج جميل استخدمها مبللة لإطلالة مشرقة أو جافة للحصول على تغطية كاملة. يمنحك لمسة نهائية أنيقة تدوم طويلاً أطراف اسفنجية ثلاثة في واحد","en":"تم ج