INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('185ef242-025b-5591-893d-4c98b6e39b0d', 'yq-1056', 'yq-1056', 'YQ-1056', '{"ar":"اجمل مسك باودر 12 غرام","en":"اجمل 12 غرام"}'::jsonb, '{"ar":"اجمل عطر بحجم 12 غرام، يمنح رائحة عطرية مميزة. كما أنه ملمس ناعم: يعتبر الملمس الباودر لطيفًا على البشرة ويمنح شعورًا بالنظافة والانتعاش، واستخدامات متعددة: يمكن استخدامه كعطر للجسم أو الملابس، ويتميز بأنه مناسب للاستخدام اليومي. طريقة الاستخدام: استخدامه بعد الاستحمام: بعد الانتهاء من الاستحمام وتجفيف الجسم، قومي بتطبيق المسك الباودر على المناطق التي ترغبين في تعطيرها، مثل الرقبة والمعصمين وخلف الأذنين.","en":"اجمل Perfume (12 غرام) that offers a distinctive scent."}'::jsonb, '29e94958-2760-5325-88e8-30cd7f939685', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":9800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1726196450_1.png","https://www.yaqootstoreye.com/files/items/item_1726196450_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1726196450_1.png","https://www.yaqootstoreye.com/files/items/item_1726196450_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"بعد الاستحمام، ضعي على الشعر كمية صغيرة، يومياً، قبل النوم","en":"After showering. Apply a small amount to the hair. Use daily, use before bed."}'::jsonb, '["After showering.","Apply a small amount to the hair.","Use daily, use before bed."]'::jsonb, '["بعد الاستحمام","ضعي على الشعر كمية صغيرة","يومياً، قبل النوم"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يمنح رائحة عطرية مميزة","يمنح حضوراً عطرياً لافتاً"],"en":["offers a distinctive scent","leaves a noticeable scent presence"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["perfume","اجمل"]'::jsonb, '{"title":{"ar":"اجمل مسك باودر 12 غرام - Luminous Derma","en":"اجمل 12 غرام - Luminous Derma"},"description":{"ar":"اجمل perfume بحجم 12 غرام، يعمل على يمنح رائحة عطرية مميزة.","en":"اجمل perfume (12 غرام) that offers a distinctive scent."},"keywords":["luminous","perfume","اجمل"]}'::jsonb);
