INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('b25b4b5e-227e-5e2e-8d57-8f3996035038', 'yq-1068', 'yq-1068', 'YQ-1068', '{"ar":"ايزنتري واقي شمس جل مائي بحمض الهيالورونيك مرطب 50 مل","en":"ايزنتري Moisturizer 50 مل"}'::jsonb, '{"ar":"ايزنتري مرطب بتركيبة جل بحجم 50 مل، يرطب البشرة ويدعم حاجزها الطبيعي. كما أنه منتج المرطبات يلبي احتياجك اليومي. طريقة الاستخدام: كيفية الاستخدام في المرحلة الأخيرة من العناية بالبشرة ، ضعي كمية مناسبة على الوجه وربتي بالمنتج بلطف على البشرة حتى يتم امتصاصه.","en":"ايزنتري Moisturizer (50 مل) that hydrates the skin and supports its natural barrier."}'::jsonb, 'a16f522c-12bf-569c-8fd3-72a53a3a2c58', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":11800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1727889661_1.png","https://www.yaqootstoreye.com/files/items/item_1727889661_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1727889661_1.png","https://www.yaqootstoreye.com/files/items/item_1727889661_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه كمية مناسبة","en":"Apply an appropriate amount to the face."}'::jsonb, '["Apply an appropriate amount to the face."]'::jsonb, '["ضعي على الوجه كمية مناسبة"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يرطب البشرة ويدعم حاجزها الطبيعي","يساعد على تقوية حاجز البشرة","تركيبة جل منعشة سهلة الاستخدام"],"en":["hydrates the skin and supports its natural barrier","helps strengthen the skin''s barrier","a refreshing gel formula that is easy to use"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["moisturizers","ايزنتري"]'::jsonb, '{"title":{"ar":"ايزنتري واقي شمس جل مائي بحمض الهيالورونيك مرطب 50 مل - Luminous Derma","en":"ايزنتري Moisturizer 50 مل - Luminous Derma"},"description":{"ar":"ايزنتري مرطب بحجم 50 مل، يعمل على يرطب البشرة ويدعم حاجزها الطبيعي ويأتي بتركيبة جل.","en":"ايزنتري Moisturizer (50 مل) that hydrates the skin and supports its natural barrier."},"keywords":["luminous","moisturizers","ايزنتري"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('048f5067-f1ae-5fc8-8e26-e12072f04e77', 'yq-1069', 'yq-1069', 'YQ-1069', '{"ar":"بانوكسيل تونر منقي 2% حمض الساليسيليك لحب الشباب 118 مل","en":"بانوكسيل Toner 118 مل"}'::jsonb, '{"ar":"بانوكسيل تونر بحجم 118 مل بتركيز 2%، يوازن البشرة ويحضرها لخطوات العناية التالية. كما أنه تمتع ببشرة خالية من حب الشباب مع مقشر بانوكسيل، وتركيبته تعمل على تقشير البشرة بلطف لاحتوائها على حمض الساليسيليك. طريقة الاستخدام: يُرج المنتج جيدًا قبل الاستخدام.","en":"بانوكسيل Toner (118 مل, 2%) that balances and prepares the skin for the next steps."}'::jsonb, 'bde3d316-a661-57b4-8070-887c5e0bd7bf', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":11800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1727890003_1.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1727890003_1.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه طبقة رقيقة، مرة واحدة يومياً","en":"Apply a thin layer to the face. Use daily."}'::jsonb, '["Apply a thin layer to the face.","Use daily."]'::jsonb, '["ضعي على الوجه طبقة رقيقة","مرة واحدة يومياً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يوازن البشرة ويحضرها لخطوات العناية التالية","يعيد للبشرة إحساس النقاء والانتعاش"],"en":["balances and prepares the skin for the next steps","restores a clean, refreshed feeling to the skin"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["toners","بانوكسيل"]'::jsonb, '{"title":{"ar":"بانوكسيل تونر منقي 2% حمض الساليسيليك لحب الشباب 118 مل - Luminous Derma","en":"بانوكسيل Toner 118 مل - Luminous Derma"},"description":{"ar":"بانوكسيل تونر بحجم 118 مل بتركيز 2%، يعمل على يواز