INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('4ff8552e-a2dc-5b0f-8304-554a425a4e5d', 'yq-1102', 'yq-1102', 'YQ-1102', '{"ar":"بيوتي اوف جوسيهون واقي شمس سائل ريليف صن اكوا فريش مرطب 50 مل","en":"بيوتي اوف جوسيهون Moisturizer 50 مل"}'::jsonb, '{"ar":"بيوتي اوف جوسيهون مرطب بتركيبة سائلة بحجم 50 مل، يرطب البشرة ويدعم حاجزها الطبيعي. طريقة الاستخدام: هذه التركيبة الجديدة مصنوعة من ماء بذور الأرز والبانثينول لتوفير ترطيب منعش مع حماية بشرتك من الأشعة فوق البنفسجية الضارة والضغوط البيئية.","en":"بيوتي اوف جوسيهون Moisturizer (50 مل) that hydrates the skin and supports its natural barrier."}'::jsonb, 'a16f522c-12bf-569c-8fd3-72a53a3a2c58', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":9800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1730307567_1.png","https://www.yaqootstoreye.com/files/items/item_1730307567_2.png","https://www.yaqootstoreye.com/files/items/item_1730307567_3.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1730307567_1.png","https://www.yaqootstoreye.com/files/items/item_1730307567_2.png","https://www.yaqootstoreye.com/files/items/item_1730307567_3.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"هذه التركيبة الجديدة مصنوعة من ماء بذور الأرز والبانثينول لتوفير ترطيب منعش مع حماية بشرتك من الأشعة فوق البنفسجية الضارة والضغوط البيئية. مصمم لأولئك الذين يفضلون لمسة نهائية شفافة وغير دهنية، يوفر منتج Relief Sun Aqua-fresh نفس الفوائد التي يوفرها منتج Relief Sun الأصلي - بدون قالب أبيض أو لزج - بالإضافة إلى ترطيب معزز ولمسة نهائية ندية سريعة الامتصاص. ترطيب وتهدئة الدفاع عن الأشعة فوق البنفسجية غني بماء بذور الأرز المغذي والبانثينول المهدئ، هذا الواقي من الشمس لا يحمي البشرة فحسب، بل ينشطها أيضًا بسبب التعرض للأشعة فوق البنفسجية والحرارة. تركيبة لوشن سريعة الامتصاص مثل منتجنا Relief Sun الأصلي، يتميز Aqua-fresh بملمس مائي سريع الامتصاص يمتزج بسلاسة مع البشرة دون ترك طبقة بيضاء أو بقايا دهنية. تركيبة خفيفة الوزن تضمن لمسة نهائية منعشة، حتى مع طبقات متعددة.","en":"هذه التركيبة الجديدة مصنوعة من ماء بذور الأرز والبانثينول لتوفير ترطيب منعش مع حماية بشرتك من الأشعة فوق البنفسجية الضارة والضغوط البيئية. مصمم لأولئك الذين يفضلون لمسة نهائية شفافة وغير دهنية، يوفر منتج Relief Sun Aqua-fresh نفس الفوائد التي يوفرها منتج Relief Sun الأصلي - بدون قالب أبيض أو لزج - بالإضافة إلى ترطيب معزز ولمسة نهائية ندية سريعة الامتصاص. ترطيب وتهدئة الدفاع عن الأشعة فوق البنفسجية غني بماء بذور الأرز المغذي والبانثينول المهدئ، هذا الواقي من الشمس لا يحمي البشرة فحسب، بل ينشطها أيضًا بسبب التعرض للأشعة فوق البنفسجية والحرارة. تركيبة لوشن سريعة الامتصاص مثل منتجنا Relief Sun الأصلي، يتميز Aqua-fresh بملمس مائي سريع الامتصاص يمتزج بسلاسة مع البشرة دون ترك طبقة بيضاء أو بقايا دهنية. تركيبة خفيفة الوزن تضمن لمسة نهائية منعشة، حتى مع طبقات متعددة."}'::jsonb, '["هذه التركيبة الجديدة مصنوعة من ماء بذور الأرز والبانثينول لتوفير ترطيب منعش مع حماية بشرتك من الأشعة فوق البنفسجية الضارة والضغوط البيئية","مصمم لأولئك الذين يفضلون لمسة نهائية شفافة وغير دهنية، يوفر منتج Relief Sun Aqua-fresh نفس الفوائد التي يوفرها منتج Relief Sun الأصلي - بدون قالب أبيض أو لزج - بالإضافة إلى ترطيب معزز ولمسة نهائية ندية سريعة الامتصاص","ترطيب وتهدئة الدفاع عن الأشعة فوق البنفسجية غني بماء بذور الأرز المغذي والبانثينول المهدئ، هذا الواقي من الشمس لا يحمي البشرة فحسب، بل ينشطها أيضًا بسبب التعرض للأشعة فوق البنفسجية والحرارة","تركيبة لوشن سريعة الامتصاص مثل منتجنا Relief Sun الأصلي، يتميز Aqua-fresh بملمس مائي سريع الامتصاص يمتزج بسلاسة مع البشرة دون ترك طبقة بيضاء أو بقايا دهنية","تركيبة خفيفة الوزن تضمن لمسة نهائية منعشة، حتى مع طبقات متعددة"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يرطب البشرة ويدعم حاجزها الطبيعي","يساعد على تقوية حاجز البشرة","تركيبة سائلة خفيفة سهلة الاستخدام"],"en":["hydrates the skin and supports its natural barrier","helps strengthen the skin''s barrier","a light liquid formula that is easy to use"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["moisturizers","بيوتي اوف جوسيهون"]'::jsonb, '{"title":{"ar":"بيوتي اوف جوسيهون واقي شمس سائل ريليف صن اكوا فريش مرطب 50 مل - Luminous Derma","en":"بيوتي اوف جوسيهون Moisturizer 50 مل - Luminous Derma"},"description":{"ar":"بيوتي اوف جوسيهون مرطب بحجم 50 مل، يعمل على يرطب البشرة ويدعم حاجزها الطبيعي ويأتي بتركيبة سائلة.","en":"بيوتي اوف جوسيهون Moisturizer (50 مل) that hydrates the skin and supports its natural barrier."},"keywords":["luminous","moisturizers","بيوتي اوف جوسيهون"]}'::jsonb);
