INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('e4ee256c-722c-57d0-8dfd-45c292bac9c2', 'yq-1138', 'yq-1138', 'YQ-1138', '{"ar":"سي سي ميد امبولات ضد تساقط 30 مل","en":"سي سي ميد 30 مل"}'::jsonb, '{"ar":"سي سي ميد علاج شعر بحجم 30 مل، يعتني بفروة الرأس والشعر. كما أنه تحتوي عل ١٦ ماده فعالة لوقف تساقط الشعر تنبت اكثر من ٢٥، ومنتج علاجات الشعر يلبي احتياجك اليومي. طريقة الاستخدام: توزع الأمبولة على الشعر ويدلك جيداً على فروة الرأس، مدة الاستخدام 3 شهور، لا يُنصح باستخدام أكثر م ن أمبولة واحدة يومياً.","en":"سي سي ميد Hair Treatment (30 مل) that cares for the scalp and hair."}'::jsonb, 'c25a581a-1a96-5e2f-8b7a-17ee7dee7bb1', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":9600,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1731960628_1.png","https://www.yaqootstoreye.com/files/items/item_1731960628_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1731960628_1.png","https://www.yaqootstoreye.com/files/items/item_1731960628_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"دلكي على فروة الرأس، يومياً","en":"Massage into the scalp. Use daily."}'::jsonb, '["Massage into the scalp.","Use daily."]'::jsonb, '["دلكي على فروة الرأس","يومياً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يعتني بفروة الرأس والشعر","يدعم صحة فروة الرأس"],"en":["cares for the scalp and hair","supports scalp health"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["hair-treatments","سي سي ميد"]'::jsonb, '{"title":{"ar":"سي سي ميد امبولات ضد تساقط 30 مل - Luminous Derma","en":"سي سي ميد 30 مل - Luminous Derma"},"description":{"ar":"سي سي ميد hair-treatments بحجم 30 مل، يعمل على يعتني بفروة الرأس