INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('c8c22c4d-a2f8-51a5-8d52-44cd72eb62f3', 'yq-1327', 'yq-1327', 'YQ-1327', '{"ar":"جيجون قناع ورقي العسل الاحمر الندي مقشر","en":"جيجون Mask"}'::jsonb, '{"ar":"جيجون قناع، يمنح البشرة عناية مكثفة ومركزة. كما أنه قناع العسل الأحمر من جيجون، سيعتني ببشرتك عناية فائقة لتدوم نضرة وصحية، وهذا القناع المضاد للأكسدة يحمي بشرتك من التجاعيد ويوفر تغذية عالية للبشرة الجافة والمتعبة. طريقة الاستخدام: بعد غسل الوجه، ضعي القناع على الوجه واتركيه لمدة 10-20 دقيقة.","en":"جيجون Mask that provides intensive, concentrated care."}'::jsonb, '7f592b99-dc96-5efe-84da-57dde42d581b', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":3300,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1736998060_1.png","https://www.yaqootstoreye.com/files/items/item_1736998060_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1736998060_1.png","https://www.yaqootstoreye.com/files/items/item_1736998060_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"بعد التنظيف، دلكي على الوجه، اتركيه لمدة دقيقة إلى دقيقتين","en":"After cleansing. Massage into the face. Leave it for one to two minutes."}'::jsonb, '["After cleansing.","Massage into the face.","Leave it for one to two minutes."]'::jsonb, '["بعد التنظيف","دلكي على الوجه","اتركيه لمدة دقيقة إلى دقيقتين"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يمنح البشرة عناية مكثفة ومركزة","يريح البشرة ويهدئها"],"en":["provides intensive, concentrated care","relaxes and soothes the skin"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["masks","جيجون"]'::jsonb, '{"title":{"ar":"جيجون قناع ورقي العسل الاحمر الندي مقشر - Luminous Derma","en":"جيجون Mask - Luminous Derma"},"description":{"ar":"جيجون مقشر، يعمل على يمنح البشرة عناية مكثفة ومركزة.","en":"جيجون Mask that provides intensive, concentrated care."},"keywords":["luminous","masks","جيجون"]}'::jsonb);
