INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('38882056-e5eb-50b8-8b81-d3cb93b030c9', 'yq-1390', 'yq-1390', 'YQ-1390', '{"ar":"بانوكسيل غسول رغوي لحب الشباب من ماده البنزويل بيروكسايد 10% 28 غرام","en":"بانوكسيل Cleanser 28 غرام"}'::jsonb, '{"ar":"بانوكسيل منظف بتركيبة رغوية بحجم 28 غرام بتركيز 10%، ينظف البشرة ويزيل الشوائب بلطف. كما أنه منتج المنظفات يلبي احتياجك اليومي. طريقة الاستخدام: قة الاستخدام تُبلل المنطقة المراد تنظيفها يُوضع غسول حب الشباب ويُدلك بلطف لمدة دقيقة إلى دقيقتين يُشطف الوجه جيدًا ويُجفف بالتربيت.","en":"بانوكسيل Cleanser (28 غرام, 10%) that cleanses the skin and removes impurities gently."}'::jsonb, '1c48bc43-635e-5769-8a44-223edcb31ce7', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":1980,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1738178262_1.png","https://www.yaqootstoreye.com/files/items/item_1738178262_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1738178262_1.png","https://www.yaqootstoreye.com/files/items/item_1738178262_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"دلكي على الوجه، اتركيه لمدة 2-3 دقائق، اشطفي بالماء جيداً ثم جففي بلطف، مرة واحدة يومياً، تنبيه: توقفي عن الاستخدام عند حدوث تهيج","en":"Massage into the face. Leave it لمدة 2-3 دقائق. Rinse well with water, then pat dry. Use daily. Note: discontinue use if irritation occurs."}'::jsonb, '["Massage into the face.","Leave it لمدة 2-3 دقائق.","Rinse well with water, then pat dry.","Use daily.","Note: discontinue use if irritation occurs."]'::jsonb, '["دلكي على الوجه","اتركيه لمدة 2-3 دقائق","اشطفي بالماء جيداً ثم جففي بلطف","مرة واحدة يومياً","تنبيه: توقفي عن الاستخدام عند حدوث تهيج"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["ينظف البشرة ويزيل الشوائب بلطف","يعيد للبشرة إحساس النظافة والانتعاش","تركيبة رغوية خفيفة سهلة التوزيع","بتركيز 10% من المكون النشط","يستخدم في روتين العناية المسائي"],"en":["cleanses the skin and removes impurities gently","restores a clean, refreshed feeling to the skin","a light foam formula that spreads easily","with a 10% concentration of the active ingredient","used in an evening care routine"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["cleansers","بانوكسيل"]'::jsonb, '{"title":{"ar":"بانوكسيل غسول رغوي لحب الشباب من ماده البنزويل بيروكسايد 10% 28 غرام - Luminous Derma","en":"بانوكسيل Cleanser 28 غرام - Luminous Derma"},"description":{"ar":"بانوكسيل منظف بحجم 28 غرام بتركيز 10%، يعمل على ينظف البشرة ويزيل الشوائب بلطف ويأتي بتركيبة رغوية.","en":"بانوكسيل Cleanser (28 غرام), 10% that cleanses the skin and removes impurities gently."},"keywords":["luminous","cleansers","بانوكسيل"]}'::jsonb);
