INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('f98cae45-105e-564d-828b-024256e66275', 'yq-1430', 'yq-1430', 'YQ-1430', '{"ar":"شيدا كحل اثمد باودر اسود غامق مكياج eye","en":"شيدا Eye Makeup"}'::jsonb, '{"ar":"شيدا مكياج عيون، يبرز جمال العينين. كما أنه يتيح لك تحديد عيون المرأة الشرقية وإبراز المظهر الذي يصبح مكثفًا وجذابًا وعميقًا، وكما أنه يحمي من الغبار وأشعة الشمس ويطرد الذباب والحشرات، فلا تتجمع حول العينين.","en":"شيدا Eye Makeup that enhances the eyes."}'::jsonb, '794844d7-e95c-5b3b-8cd2-4e6ed5c56ab0', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":5800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1740012511_1.png","https://www.yaqootstoreye.com/files/items/item_1740012511_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1740012511_1.png","https://www.yaqootstoreye.com/files/items/item_1740012511_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي حول العينين","en":"Apply around the eyes."}'::jsonb, '["Apply around the eyes."]'::jsonb, '["ضعي حول العينين"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يبرز جمال العينين","يساعد على إبراز جمال العينين"],"en":["enhances the eyes","helps enhance the eyes"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["eye-makeup","شيدا"]'::jsonb, '{"title":{"ar":"شيدا كحل اثمد باودر اسود غامق مكياج eye - Luminous Derma","en":"شيدا Eye Makeup - Luminous Derma"},"description":{"ar":"شيدا مكياج eye، يعمل على يبرز جمال العينين.","en":"شيدا Eye Makeup that enhances the eyes."},"keywords":["luminous","eye-makeup","شيدا"]}'::jsonb);
