INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('9962dde5-80a6-5fdc-8481-3e65b1d8cc5c', 'yq-1438', 'yq-1438', 'YQ-1438', '{"ar":"كوسركس تونر لاخفاء المسام وتنعيم 2 1 100 مل","en":"COSRX Toner 100 مل"}'::jsonb, '{"ar":"كوسركس تونر بحجم 100 مل، يوازن البشرة ويحضرها لخطوات العناية التالية. كما أنه مرطب ومقشر للبشرة في منتج واحد، يعمل على شد وتقليل ظهور المسام بشكل مرئي، ويمنحكِ هذا المصل بشرة ناعمة ومشرقة، ويقلل من ظهور المسام الواسعة. طريقة الاستخدام: بعد تنظيف بشرتك، ضعي كمية من المستحضر على كفة يدك أو على قطنة وطبقيه بلطف على بشرتك.","en":"كوسركس Toner (100 مل) that balances and prepares the skin for the next steps."}'::jsonb, 'bde3d316-a661-57b4-8070-887c5e0bd7bf', 'caf6a63c-8b40-58d7-8ea6-105bc989076b', '{"price":9800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1740200045_1.png","https://www.yaqootstoreye.com/files/items/item_1740200045_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1740200045_1.png","https://www.yaqootstoreye.com/files/items/item_1740200045_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه بطبقة متساوية","en":"Apply to the face, massaging gently."}'::jsonb, '["Apply to the face, massaging gently."]'::jsonb, '["ضعي على الوجه بطبقة متساوية"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يوازن البشرة ويحضرها لخطوات العناية التالية","يعيد للبشرة إحساس النقاء والانتعاش"],"en":["balances and prepares the skin for the next steps","restores a clean, refreshed feeling to the skin"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["toners","كوسركس"]'::jsonb, '{"title":{"ar":"كوسركس تونر لاخفاء المسام وتنعيم 2 1 100 مل - Luminous Derma","en":"COSRX Toner 100 مل - Luminous Derma"},"description":{"ar":"COSRX تونر بحجم 100 مل، يعمل على يوازن البشرة ويحضرها لخطوات العناية التالية.","en":"COSRX Toner (100 مل) that balances and prepares the skin for the next steps."},"keywords":["luminous","toners","كوسركس"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('9af22d83-d977-5a79-805d-b9d37c1aa719', 'yq-1439', 'yq-1439', 'YQ-1439', '{"ar":"كريم كاب مقشر والجسم عصار 75 مل","en":"كريم كاب Exfoliator 75 مل"}'::jsonb, '{"ar":"كريم كاب مقشرات بحجم 75 مل، يقشر البشرة بلطف ويزيل الخلايا الميتة. كما أنه تحافظ التركيبة المرطبة على بشرتك ناعمة ونضرة لاستعادة مظهرها الطبيعي، ويمكنك استخدام هذا الكريم مرة أو مرتين أسبوعيًا للحصول على نتائج متسقة. طريقة الاستخدام: بللي البشرة بماء دافيء.","en":"كريم كاب Exfoliator (75 مل) that gently exfoliates and removes dead cells."}'::jsonb, '7907841f-c414-5d82-814f-9ef070c20c6d', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":2800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1740200434_1.png","https://www.yaqootstoreye.com/files/items/item_1740200434_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1740200434_1.png","https://www.yaqootstoreye.com/files/items/item_1740200434_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الجسم بحركات دائرية، اتركيه لمدة 2-3 دقائق، اشطفي بالماء جيداً ثم جففي بلطف","en":"Apply to the body, massaging gently. Leave it لمدة 2-3 دقائق. Rinse well with water, then pat dry."}'::jsonb, '["Apply to the body, massaging gently.","Leave it لمدة 2-3 دقائق.","Rinse well with water, then pat dry."]'::jsonb, '["ضعي على الجسم بحركات دائرية","اتركيه لمدة 2-3 دقائق","اشطفي بالماء جيداً ثم جففي بلطف"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يقشر البشرة بلطف ويزيل الخلايا الميتة","يزيل الخلايا الميتة بلطف"],"en":["gently exfoliates and removes dead cells","gently removes dead skin cells"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["exfoliators","كريم كاب"]'::jsonb, '{"title":{"ar":"كريم كاب مقشر والجسم عصار 75 مل - Luminous Derma","en":"كريم كاب Exfoliator 75 مل - Luminous Derma"},"description":{"ar":"كريم كاب مقشرات بحجم 75 مل، يعمل على يقشر البشرة بلطف ويزيل الخلايا الميتة.","en":"كريم كاب Exfoliator (75 مل) that gently exfoliates and removes dead cells."},"keywords":["luminous","exfoliators","كريم كاب"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('c9b39690-b728-5618-86e8-36852fc58926', 'yq-1440', 'yq-1440', 'YQ-1440', '{"ar":"اليكا كريم لوشن جسم 30 جم","en":"Body Lotion 30 جم"}'::jsonb, '{"ar":"لوشن جسم بحجم 30 جم، يرطب الجسم ويحافظ على نعومته. كما أنه لتكون جافة ومثيرة للحكة وأحيانًا تظهر طفح جلدي أحمر متقشر، ويعمل عن طريق تنشيط المواد الطبيعية في الجلد لتقليل التورم والاحمرار والحكة. طريقة الاستخدام: ضع طبقًا لتوجيهات الطبيب ، عادة طبقة رقيقة من الدواء على المنطقة المصابة مرة واحدة يوميًا.","en":"Body Lotion (30 جم) that moisturizes and keeps the body soft."}'::jsonb, 'efddd25b-8cfc-590c-830f-8991a96b6d17', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":4800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1740200875_1.png","https://www.yaqootstoreye.com/files/items/item_1740200875_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1740200875_1.png","https://www.yaqootstoreye.com/files/items/item_1740200875_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه طبقة رقيقة بالفرك، اتركيه لمدة دقيقة إلى دقيقتين، مرة واحدة يومياً، تنبيه: توقفي عن الاستخدام عند حدوث تهيج","en":"Apply a thin layer to the face, massaging gently. Leave it for one to two minutes. Use daily. Note: discontinue use if irritation occurs."}'::jsonb, '["Apply a thin layer to the face, massaging gently.","Leave it for one to two minutes.","Use daily.","Note: discontinue use if irritation occurs."]'::jsonb, '["ضعي على الوجه طبقة رقيقة بالفرك","اتركيه لمدة دقيقة إلى دقيقتين","مرة واحدة يومياً","تنبيه: توقفي عن الاستخدام عند حدوث تهيج"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يرطب الجسم ويحافظ على نعومته","يساعد على الحفاظ على نعومة الجسم"],"en":["moisturizes and keeps the body soft","helps keep the body soft"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["body-lotion","ماركة غير محددة"]'::jsonb, '{"title":{"ar":"اليكا كريم لوشن جسم 30 جم - Luminous Derma","en":"Body Lotion 30 جم - Luminous Derma"},"description":{"ar":"undefined لوشن جسم بحجم 30 جم، يعمل على يرطب الجسم ويحافظ على نعومته.","en":"undefined Body Lotion (30 جم) that moisturizes and keeps the body soft."},"keywords":["luminous","body-lotion","ماركة غير محددة"]}'::jsonb);
