INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('d0b9a988-633b-58e6-80a6-3ca18ed06cc6', 'yq-1746', 'yq-1746', 'YQ-1746', '{"ar":"غارنييه ماسك الترا دو بخلاصه ماء الارز والنشا المرطب العلاجي الجاف 340 مل","en":"غارنييه 340 مل"}'::jsonb, '{"ar":"غارنييه قناع شعر بحجم 340 مل، يغذي الشعر بعمق. كما أنه احصل على معالجة فعالة للشعر الجاف والمتعطش للترطيب مع ماسك غارنييه ألترا دو، ويعزز من مرونة وحيوية الشعر. طريقة الاستخدام: توضع كمية مناسبة من الماسك على شعر نظيف ومبلل، ثم قم بتوزيعه بالتساوي على طول الشعر مع التركيز على الأطراف.","en":"غارنييه Hair Mask (340 مل) that deeply nourishes the hair."}'::jsonb, 'ace4cbf7-da7a-5f25-8c15-68cf00271bf6', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":5800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1752522307_1.png","https://www.yaqootstoreye.com/files/items/item_1752522307_2.png","https://www.yaqootstoreye.com/files/items/item_1752522307_3.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1752522307_1.png","https://www.yaqootstoreye.com/files/items/item_1752522307_2.png","https://www.yaqootstoreye.com/files/items/item_1752522307_3.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي المنتج على شعر نظيف ومبلل، ضعي على الشعر كمية مناسبة، اتركيه لمدة دقيقة إلى دقيقتين، اشطفي بالماء جيداً ثم جففي بلطف","en":"Apply the product to شعر نظيف ومبلل. Apply an appropriate amount to the hair. Leave it for one to two minutes. Rinse well with water, then pat dry."}'::jsonb, '["Apply the product to شعر نظيف ومبلل.","Apply an appropriate amount to the hair.","Leave it for one to two minutes.","Rinse well with water, then pat dry."]'::jsonb, '["ضعي المنتج على شعر نظي