INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('ae4f46e6-c7c5-5ec2-8c6f-8907fbca8f70', 'yq-1880', 'yq-1880', 'YQ-1880', '{"ar":"ايكوال بيري سيروم بفيتامين c والنياسيناميد 30 مل","en":"ايكوال بيري سيروم بفيتامين c والنياسيناميد Serum 30 مل"}'::jsonb, '{"ar":"ايكوال بيري سيروم بحجم 30 مل، يمنح البشرة عناية مركزة بمكونات فعالة. كما أنه النياسيناميد (فيتامين B3): يساعد على توحيد لون البشرة وتقليل مظهر المسام الواسعة، والسيراميد: يدعم حاجز البشرة الطبيعي ويحافظ على ترطيبها. طريقة الاستخدام: التنظيف: ابدئي بتنظيف وجهك بالغسول المناسب لنوع بشرتك لإزالة الشوائب والمكياج.","en":"ايكوال بيري Serum (30 مل) that delivers concentrated, effective care."}'::jsonb, '29e558a9-3a4b-52d6-874c-0662648849c0', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":15800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1756068307_1.png","https://www.yaqootstoreye.com/files/items/item_1756068307_2.png","https://www.yaqootstoreye.com/files/items/item_1756068307_3.png","https://www.yaqootstoreye.com/files/items/item_1756068307_4.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1756068307_1.png","https://www.yaqootstoreye.com/files/items/item_1756068307_2.png","https://www.yaqootstoreye.com/files/items/item_1756068307_3.png","https://www.yaqootstoreye.com/files/items/item_1756068307_4.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه بضع قطرات بحركات دائرية، اتركيه حتى يُمتص، صباحاً","en":"Apply a few drops to the face, massaging gently. Leave it until absorbed. ."}'::jsonb, '["Apply a few drops to the face, massaging gently.","Leave it until absorbed.","."]'::jsonb, '["ضعي على الوجه بضع قطرات بحركات دائرية","