INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('2e9097fb-efc6-5587-88ba-c8da09b3bb6e', 'yq-1971', 'yq-1971', 'YQ-1971', '{"ar":"بايوديرما كريم سيكابيو مرطب ومرمم 50 مل","en":"Bioderma 50 مل"}'::jsonb, '{"ar":"بايوديرما عناية يدين بحجم 50 مل، يعتني بيدين ناعمتين ومرطبتين. كما أنه منتج العناية باليدين يلبي احتياجك اليومي. طريقة الاستخدام: كل يوم - كلما دعت الحاجة 1 خطوة يوضع على اليدين.","en":"بايوديرما Hand Care (50 مل) that keeps hands soft and moisturized."}'::jsonb, '3d92696e-f89d-576c-82a4-dc70630b67c6', '889719a7-01a7-558a-8176-607fb2cddc44', '{"price":5800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/BiodermaAtodermHandsAndNails50ml.jpg?v=1702212822"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/BiodermaAtodermHandsAndNails50ml.jpg?v=1702212822"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"دلكي على اليدين، يومياً","en":"Massage into the hands. Use daily."}'::jsonb, '["Massage into the hands.","Use daily."]'::jsonb, '["دلكي على اليدين","يومياً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يعتني بيدين ناعمتين ومرطبتين","يساعد على الحفاظ على نعومة اليدين"],"en":["keeps hands soft and moisturized","helps keep hands soft"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["hand-care","بايوديرما"]'::jsonb, '{"title":{"ar":"بايوديرما كريم سيكابيو مرطب ومرمم 50 مل - Luminous Derma","en":"Bioderma 50 مل - Luminous Derma"},"description":{"ar":"Bioderma hand-care بحجم 50 مل، يعمل على يعتني بيدين ناعمتين ومرطبتين.","en":"Bioderma hand-care (50 مل) that keeps hands soft and moisturized."},"keywords":["luminous","hand-care","بايوديرما"]}'::jsonb);
