INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('ed82cd4e-0c64-525d-8539-6210c2249035', 'yq-1977', 'yq-1977', 'YQ-1977', '{"ar":"لوريال بلسم الفيف بخلاصه الزيوت الاستثنائيه بالشعر العادي الي الجاف شامبو 360 مل","en":"لوريال Shampoo 360 مل"}'::jsonb, '{"ar":"لوريال شامبو بحجم 360 مل، ينظف الشعر بلطف. كما أنه يوفر التوازن المثالي بين الشعور بالخفة على الجذور والتغذية على الأطراف، وهذه التركيبة الشفافة ستترك شعرك يشعر بالتغذية والنعومة والمرونة بشكلٍ جمي. طريقة الاستخدام: بعد تنظيف الشعر بالشامبو توضع كمية من البلسم ويدلك الشعر لمدة 3 إلى 5 دقائق للحصول على أفضل النتائج.","en":"لوريال Shampoo (360 مل) that cleanses the hair gently."}'::jsonb, 'e96e9919-f71c-53bd-80be-bd4e1416c366', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":3800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/LorealParisElviveHyaluronPure72hRehydratingConditioner360ml.jpg?v=1733226739"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/LorealParisElviveHyaluronPure72hRehydratingConditioner360ml.jpg?v=1733226739"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"دلكي على الشعر، اتركيه لمدة دقيقة إلى دقيقتين، اشطفي بالماء جيداً ثم جففي بلطف","en":"Massage into the hair. Leave it for one to two minutes. Rinse well with water, then pat dry."}'::jsonb, '["Massage into the hair.","Leave it for one to two minutes.","Rinse well with water, then pat dry."]'::jsonb, '["دلكي على الشعر","اتركيه لمدة دقيقة إلى دقيقتين","اشطفي بالماء جيداً ثم جففي بلطف"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["ينظف الشعر بلطف","يعتني بنظافة فروة الرأس"],"en":["cleanses the hair gently","cares for scalp cleanliness"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["shampoo","لوريال"]'::jsonb, '{"title":{"ar":"لوريال بلسم الفيف بخلاصه الزيوت الاستثنائيه بالشعر العادي الي الجاف شامبو 360 مل - Luminous Derma","en":"لوريال Shampoo 360 مل - Luminous Derma"},"description":{"ar":"لوريال شامبو بحجم 360 مل، يعمل على ينظف الشعر بلطف.","en":"لوريال Shampoo (360 مل) that cleanses the hair gently."},"keywords":["luminous","shampoo","لوريال"]}'::jsonb);
