INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('aa75b06a-d6ab-5bb1-813f-01ef3661b54c', 'yq-2013', 'yq-2013', 'YQ-2013', '{"ar":"ويلا اوكسجين بروكسيد 6% 60 مل","en":"ويلا 60 مل"}'::jsonb, '{"ar":"ويلا عناية جسم بحجم 60 مل بتركيز 6%، يعتني بجسم البشرة. كما أنه سهل الاستخدام – احصلي على نتائج بجودة صالون في راحة منزلك مع تركيبة سهلة المزج والتطبيق. طريقة الاستخدام: هذه السلعة درجات غنية وطبيعية – مثالي لتلوين الشعر بدرجة أغمق، الحفاظ على نفس الدرجة، أو للحصول على تفتيح بسيط في درجات الأسود والبني.","en":"ويلا Body Care (60 مل, 6%) that cares for the body skin."}'::jsonb, 'ea414f88-565e-5b69-8704-5f94e25e5b27', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":1800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1765145644_1.png","https://www.yaqootstoreye.com/files/items/item_1765145644_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1765145644_1.png","https://www.yaqootstoreye.com/files/items/item_1765145644_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"هذه السلعة درجات غنية وطبيعية – مثالي لتلوين الشعر بدرجة أغمق، الحفاظ على نفس الدرجة، أو للحصول على تفتيح بسيط في درجات الأسود والبني. مناسب لجميع ألوان الشعر – مناسب للاستخدام مع جميع أنواع وألوان الشعر، مما يضمن لك الحصول على نتائج غنية ومتساوية بغض النظر عن لون شعرك الأساسي. سهل الاستخدام – احصلي على نتائج بجودة صالون في راحة منزلك مع تركيبة سهلة المزج والتطبيق. نتائج بجودة صالون – يوفر ويلا ويلوكسون مظهر نتائج بمستوى احترافي كما تتوقعين من صالون التجميل، مما يضمن أن يبقى لون شعرك مشرقاً وصحياً. متوافق مع منتجات صبغ الشعر والتفتيح من ويلا – مصمم للعمل بشكل مثالي مع صبغات الشعر أو منتجات التفتيح من ويلا لتجربة تلوين شعر كاملة.","en":