INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('a3abcb67-b1e7-54fa-8127-5a6d88b340b1', 'yq-2016', 'yq-2016', 'YQ-2016', '{"ar":"سكين 1004 غسول رغوي سنتيلا بمستخلص شجر الشاي تريكا وحمض الساليسيليك لحب الشباب 125 مل","en":"سكين 1004 Cleanser 125 مل"}'::jsonb, '{"ar":"سكين 1004 منظف بتركيبة رغوية بحجم 125 مل، ينظف البشرة ويزيل الشوائب بلطف. كما أنه ناية تنظيف احترافية لمشكلات البشرة ومكوّن فعّال يوفّر الراحة للبشرة المعرضة لحب الشباب، و- قوة تنظيف عالية تزيل الإفرازات الدهنية الزائدة المفرطة، وهي السبب الرئيسي لمشكلات البشرة. طريقة الاستخدام: توضع كمية مناسبة من الغسول على أيدي مبللة وتفرك حتى تظهر الرغوة الغنية.","en":"سكين 1004 Cleanser (125 مل) that cleanses the skin and removes impurities gently."}'::jsonb, '1c48bc43-635e-5769-8a44-223edcb31ce7', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":9800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/KinAloeVeraToothpaste125ml.jpg?v=1753016308"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/KinAloeVeraToothpaste125ml.jpg?v=1753016308"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"دلكي على البشرة كمية مناسبة","en":"Massage an appropriate amount into the skin."}'::jsonb, '["Massage an appropriate amount into the skin."]'::jsonb, '["دلكي على البشرة كمية مناسبة"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["ينظف البشرة ويزيل الشوائب بلطف","يعيد للبشرة إحساس النظافة والانتعاش","تركيبة رغوية خفيفة سهلة التوزيع"],"en":["cleanses the skin and removes impurities gently","restores a clean, refreshed feeling to the skin","a light foam formula that spreads easily"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["cleansers","سكين 1004"]'::jsonb, '{"title":{"ar":"سكين 1004 غسول رغوي سنتيلا بمستخلص شجر الشاي تريكا وحمض الساليسيليك لحب الشباب 125 مل - Luminous Derma","en":"سكين 1004 Cleanser 125 مل - Luminous Derma"},"description":{"ar":"سكين 1004 منظف بحجم 125 مل، يعمل على ينظف البشرة ويزيل الشوائب بلطف ويأتي بتركيبة رغوية.","en":"سكين 1004 Cleanser (125 مل) that cleanses the skin and removes impurities gently."},"keywords":["luminous","cleansers","سكين 1004"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('78159656-e729-5029-8639-c98ccf852a44', 'yq-2017', 'yq-2017', 'YQ-2017', '{"ar":"شريط سيليكون للندبات الجراحيه الولاده القيصريه وشفط الدهون والجدره والحروق وقابله لاعاده الاستخدام لوشن جسم 15 متر","en":"Body Lotion 15 متر"}'::jsonb, '{"ar":"لوشن جسم بحجم 15 متر، يرطب الجسم ويحافظ على نعومته. كما أنه لا يسبب التهيج ويمكن وضعه وإزالته وتغيير موضعه بسهولة وبدون ألم، وكل ما عليك وضعها على الندوب القديمة أو الجديدة لتقليل الحكة والاحمرار والأعراض المزعجة. طريقة الاستخدام: تخفيف أثار الندوب بدون ألم- شريط الندوب السيليكون الطبي خاصتنا مصنوع من السيليكون المرن المناسب للاستخدام في المستشفيات.","en":"Body Lotion (15 متر) that moisturizes and keeps the body soft."}'::jsonb, 'efddd25b-8cfc-590c-830f-8991a96b6d17', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":5800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1765149203_1.png","https://www.yaqootstoreye.com/files/items/item_1765149203_2.png","https://www.yaqootstoreye.com/files/items/item_1765149203_3.png","https://www.yaqootstoreye.com/files/items/item_1765149203_4.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1765149203_1.png","https://www.yaqootstoreye.com/files/items/item_1765149203_2.png","https://www.yaqootstoreye.com/files/items/item_1765149203_3.png","https://www.yaqootstoreye.com/files/items/item_1765149203_4.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الجسم، تنبيه: توقفي عن الاستخدام عند حدوث تهيج","en":"Apply to the body. Note: discontinue use if irritation occurs."}'::jsonb, '["Apply to the body.","Note: discontinue use if irritation occurs."]'::jsonb, '["ضعي على الجسم",