, 0, FALSE, FALSE, FALSE, FALSE, '["hair-oils","غارنييه"]'::jsonb, '{"title":{"ar":"غارنييه سيروم قطرات حرير بماء الارز لتنعيم الطويل والباهت زيت شعر 120 مل - Luminous Derma","en":"غارنييه Hair Oil 120 مل - Luminous Derma"},"description":{"ar":"غارنييه زيت شعر بحجم 120 مل، يعمل على يغذي الشعر ويمنحه اللمعان.","en":"غارنييه Hair Oil (120 مل) that nourishes the hair and adds shine."},"keywords":["luminous","hair-oils","غارنييه"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('b301b6d5-fa99-5a11-8daf-7a846c70c037', 'yq-2059', 'yq-2059', 'YQ-2059', '{"ar":"باولاز مقشر سائل بي اتش ايه بنسبه 2% حمض الساليسيليك يحارب الرؤوس السوداء والمسام تونر 118 مل","en":"باولاز Toner 118 مل"}'::jsonb, '{"ar":"باولاز تونر بتركيبة سائلة بحجم 118 مل بتركيز 2%، يوازن البشرة ويحضرها لخطوات العناية التالية. كما أنه الفوائد: تصبح البشرة باهتة ومزدحمة عندما تتراكم خلايا الجلد الميتة على سطحها. طريقة الاستخدام: بعد التنظيف والتونر، ضعيه بلطف على رقبة الوجه بالكامل بأصابعك أو باستخدام وسادة قطنية، بما في ذلك منطقة العين (تجنبي خط الرموش والجفون).","en":"باولاز Toner (118 مل, 2%) that balances and prepares the skin for the next steps."}'::jsonb, 'bde3d316-a661-57b4-8070-887c5e0bd7bf', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":21800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1766870962_1.png","https://www.yaqootstoreye.com/files/items/item_1766870962_2.png","https://www.yaqootstoreye.com/files/items/item_1766870962_3.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1766870962_1.png","https://www.yaqootstoreye.com/files/items/item_1766870962_2.png","https://www.yaqootstoreye.com/files/items/item_1766870962_3.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه، اشطفي بالماء جيداً ثم جففي بلطف، كخطوة أخيرة، مرتين يومياً","en":"Apply to the face. Rinse well with water, then pat dry. As a final step, use daily."}'::jsonb, '["Apply to the face.","Rinse well with water, then pat dry.","As a final step, use daily."]'::jsonb, '["ضعي على الوجه","اشطفي بالماء جيداً ثم جففي بلطف","كخطوة أخيرة، مرتين يومياً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يوازن البشرة ويحضرها لخطوات العناية التالية","يعيد للبشرة إحساس النقاء والانتعاش","تركيبة سائلة خفيفة سهلة الاستخدام","بتركيز 2% من المكون النشط","يستخدم في روتين العناية الصباحي"],"en":["balances and prepares the skin for the next steps","restores a clean, refreshed feeling to the skin","a light liquid formula that is easy to use","with a 2% concentration of the active ingredient","used in a morning care routine"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["toners","باولاز"]'::jsonb, '{"title":{"ar":"باولاز مقشر سائل بي اتش ايه بنسبه 2% حمض الساليسيليك يحارب الرؤوس السوداء والمسام تونر 118 مل - Luminous Derma","en":"باولاز Toner 118 مل - Luminous Derma"},"description":{"ar":"باولاز تونر بحجم 118 مل بتركيز 2%، يعمل على يوازن البشرة ويحضرها لخطوات العناية التالية ويأتي بتركيبة سائلة.","en":"باولاز Toner (118 مل), 2% that balances and prepares the skin for the next steps."},"keywords":["luminous","toners","باولاز"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('7e86c868-b92d-5ad9-8ca3-9de8c22f6d6b', 'yq-2060', 'yq-2060', 'YQ-2060', '{"ar":"يوسرين كريم المضاد للتصبغات للمناطق والجسم لوشن جسم 200 مل","en":"Eucerin Body Lotion 200 مل"}'::jsonb, '{"ar":"يوسرين لوشن جسم بحجم 200 مل، يرطب الجسم ويحافظ على نعومته. كما أنه مصمم هذا الكريم على تقليل ظهور البقع والتصبغات مع معالجتها في المناطق المستهدفة. طريقة الاستخدام: ضعي طبقة رقيقة من الكريم على المناطق المتأثرة من بشرة الجسم، ثم قومي بتدليكها بلطف حتى يتم امتصاصها بالكامل.","en":"يوسرين Body Lotion (200 مل) that moisturizes and keeps the body soft."}'::jsonb, 'efddd25b-8cfc-590c-830f-8991a96b6d17', '6df7e4c7-e844-5b73-8b84-93f4d255cf53', '{"price":19800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/EucerinDermopurifyerToner200ml1.jpg?v=1768217978"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/EucerinDermopurifyerToner200ml1.jpg?v=1768217978"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الجسم طبقة رقيقة، اتركيه حتى يُمتص، مرتين يومياً، صباحاً","en":"Apply a thin layer to the body. Leave it until absorbed. Use daily."}'::jsonb, '["Apply a thin layer to the body.","Leave it until absorbed.","Use daily."]'::jsonb, '["ضعي على الجسم طبقة رقيقة","اتركيه حتى يُمتص","مرتين يومياً، صباحاً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يرطب الجسم ويحافظ على نعومته","يساعد على الحفاظ على نعومة الجسم","يستخدم في روتين العناية صباحاً ومساءً"],"en":["moisturizes and keeps the body soft","helps keep the body soft","used in both morning and evening care"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["body-lotion","يوسرين"]'::jsonb, '{"title":{"ar":"يوسرين كريم المضاد للتصبغات للمناطق والجسم لوشن جسم 200 مل - Luminous Derma","en":"Eucerin Body Lotion 200 مل - Luminous Derma"},"description":{"ar":"Eucerin لوشن جسم بحجم 200 مل، يعمل على يرطب الجسم ويحافظ على نعومته.","en":"Eucerin Body Lotion (200 مل) that moisturizes and keeps the body soft."},"keywords":["luminous","body-lotion","يوسرين"]}'::jsonb);
