INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('57d6eeb3-b8d4-5dba-87da-5567ca8992de', 'yq-2101', 'yq-2101', 'YQ-2101', '{"ar":"فير ليدي صابونه التقشير مع مسحوق الافوكادو غسول جسم 200 غرام","en":"فير ليدي Body Wash 200 غرام"}'::jsonb, '{"ar":"فير ليدي غسول جسم بحجم 200 غرام، ينظف الجسم بلطف. كما أنه هل تبحث عن صابونة تجمع بين التقشير اللطيف والتفتيح الطبيعي لبشرتك، مع تغذية عميقة، وهل تعاني بشرتك من خلايا الجلد الميتة والشوائب، وتحتاج إلى منتج يجددها ويرطبها بعمق. طريقة الاستخدام: تبلل البشرة بالماء الفاتر.","en":"فير ليدي Body Wash (200 غرام) that cleanses the body gently."}'::jsonb, '1cfdc4ca-7151-569a-8c4e-d97a9a522586', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":2800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1770161888_1.png","https://www.yaqootstoreye.com/files/items/item_1770161888_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1770161888_1.png","https://www.yaqootstoreye.com/files/items/item_1770161888_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه بحركات دائرية، اتركيه لمدة دقيقة إلى دقيقتين","en":"Apply to the face, massaging gently. Leave it for one to two minutes."}'::jsonb, '["Apply to the face, massaging gently.","Leave it for one to two minutes."]'::jsonb, '["ضعي على الوجه بحركات دائرية","اتركيه لمدة دقيقة إلى دقيقتين"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["ينظف الجسم بلطف","يعيد للبشرة إحساس النظافة"],"en":["cleanses the body gently","restores a clean feeling to the skin"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["body-wash","فير ليدي"]'::jsonb, '{"title":{"ar":"فير ليدي صابونه التقشير مع مسحوق الافوكادو غسول جسم 200 غرام - Luminous Derma","en":"فير ليدي Body Wash 200 غرام - Luminous Derma"},"description":{"ar":"فير ليدي غسول جسم بحجم 200 غرام، يعمل على ينظف الجسم بلطف.","en":"فير ليدي Body Wash (200 غرام) that cleanses the body gently."},"keywords":["luminous","body-wash","فير ليدي"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('a46ea401-2fef-5854-8896-0a518fc5b03e', 'yq-2102', 'yq-2102', 'YQ-2102', '{"ar":"لوريال سيروم ريفيتاليفت لايزر مرطب ومضاد للتجاعيد مع حمض الهيالورونيك 30 مل","en":"لوريال Serum 30 مل"}'::jsonb, '{"ar":"لوريال سيروم بحجم 30 مل، يمنح البشرة عناية مركزة بمكونات فعالة. كما أنه ترطيب مكثف: تركيبة تحتوي على حمض الهيالورونيك لترطيب البشرة وإعادة الحيوية لها، وتضييق المسام: يساعد في تحسين ملمس البشرة وتصغير المسام. طريقة الاستخدام: يوضع 2-3 قطرات على بشرة نظيفة وجافة (الوجه والرقبة) صباحاً ومساءً.","en":"لوريال Serum (30 مل) that delivers concentrated, effective care."}'::jsonb, '29e558a9-3a4b-52d6-874c-0662648849c0', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":6800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/Loreal_Hyaluron_Expert_Serum_30_Ml.jpg?v=1753529025"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/Loreal_Hyaluron_Expert_Serum_30_Ml.jpg?v=1753529025"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي المنتج على بشرة نظيفة وجافة، ضعي على البشرة بضع قطرات، مرتين يومياً، صباحاً ومساءً","en":"Apply the product on clean, dry skin. Apply a few drops to the skin. Use daily, use morning and evening."}'::jsonb, '["Apply the product on clean, dry skin.","Apply a few drops to the skin.","Use daily, use morning and evening."]'::jsonb, '["ضعي المنتج على بشرة نظيفة وجافة","ضعي على البشرة بضع قطرات","مرتين يومياً، صباحاً ومساءً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يمنح البشرة عناية مركزة بمكونات فعالة","يوفر عناية مركزة للبشرة","يستخدم في روتين العناية صباحاً ومساءً"],"en":["delivers concentrated, effective care","delivers concentrated care","used in both morning and evening care"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["serums","لوريال"]'::jsonb, '{"title":{"ar":"لوريال سيروم ريفيتاليفت لايزر مرطب ومضاد للتجاعيد مع حمض الهيالورونيك 30 مل - Luminous Derma","en":"لوريال Serum 30 مل - Luminous Derma"},"description":{"ar":"لوريال سيروم بحجم 30 مل، يعمل على يمنح البشرة عناية مركزة بمكونات فعالة.","en":"لوريال Serum (30 مل) that delivers concentrated, effective care."},"keywords":["luminous","serums","لوريال"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('4663f5cb-bad5-568e-8938-98897e86d06e', 'yq-2105', 'yq-2105', 'YQ-2105', '{"ar":"لوريال واقي شمس سائل 50+ غير مرئي حمايه عاليه مرطب 50 مل","en":"لوريال Moisturizer 50 مل"}'::jsonb, '{"ar":"لوريال مرطب بتركيبة سائلة بحجم 50 مل، يرطب البشرة ويدعم حاجزها الطبيعي. كما أنه يترك ملمساً نظيفاً دون أي بقايا بيضاء ويشكل طبقة واقية على الجلد. طريقة الاستخدام: فورًا: يتم حماية بشرتك من الأشعة فوق البنفسجية وتبدو أكثر إشراقًا على الفور.","en":"لوريال Moisturizer (50 مل) that hydrates the skin and supports its natural barrier."}'::jsonb, 'a16f522c-12bf-569c-8fd3-72a53a3a2c58', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":6800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/products/LOREALPARISGLYCOLIC-BRIGHTNIGHTCREAM50ML.jpg?v=1673431225"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/products/LOREALPARISGLYCOLIC-BRIGHTNIGHTCREAM50ML.jpg?v=1673431225"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الوجه، يومياً","en":"Apply to the face. Use daily."}'::jsonb, '["Apply to the face.","Use daily."]'::jsonb, '["ضعي على الوجه","يومياً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يرطب البشرة ويدعم حاجزها الطبيعي","يساعد على تقوية حاجز البشرة","تركيبة سائلة خفيفة سهلة الاستخدام"],"en":["hydrates the skin and supports its natural barrier","helps strengthen the skin''s barrier","a light liquid formula that is easy to use"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["moisturizers","لوريال"]'::jsonb, '{"title":{"ar":"لوريال واقي شمس سائل 50+ غير مرئي حمايه عاليه مرطب 50 مل - Luminous Derma","en":"لوريال Moisturizer 50 مل - Luminous Derma"},"description":{"ar":"لوريال مرطب بحجم 50 مل، يعمل على يرطب البشرة ويدعم حاجزها الطبيعي ويأتي بتركيبة سائلة.","en":"لوريال Moisturizer (50 مل) that hydrates the skin and supports its natural barrier."},"keywords":["luminous","moisturizers","لوريال"]}'::jsonb);
