onb, '[]'::jsonb, '{"ar":["يوازن البشرة ويحضرها لخطوات العناية التالية","يعيد للبشرة إحساس النقاء والانتعاش","يستخدم في روتين العناية المسائي"],"en":["balances and prepares the skin for the next steps","restores a clean, refreshed feeling to the skin","used in an evening care routine"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["toners","ميديكيوب"]'::jsonb, '{"title":{"ar":"ميديكيوب مسحات قطنيه زيرو تنقيه وتضييق المسام وتنضيف تونر - Luminous Derma","en":"Medicube Toner - Luminous Derma"},"description":{"ar":"Medicube تونر، يعمل على يوازن البشرة ويحضرها لخطوات العناية التالية.","en":"Medicube Toner that balances and prepares the skin for the next steps."},"keywords":["luminous","toners","ميديكيوب"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('47103a19-f0a0-5669-841e-028859cebf0e', 'yq-2151', 'yq-2151', 'YQ-2151', '{"ar":"انوا كريم مرطب بالسيراميد والبانثينول لتقويه حاجز 100 مل","en":"انوا Moisturizer 100 مل"}'::jsonb, '{"ar":"انوا مرطب بحجم 100 مل، يرطب البشرة ويدعم حاجزها الطبيعي. كما أنه كريم تم تطويره لتقوية حاجز البشرة باستخدام السيراميد والبانثينول، ومختبر سريريًا تركيبة غير مهيّجة لا تسد المسام، مثالي للبشرة الحساسة. طريقة الاستخدام: في الخطوة الأخيرة من روتين العناية بالبشرة، ضعي كمية معتدلة من الكريم على الوجه، ودلّكي بلطف حتى يتم امتصاصه بالكامل.","en":"انوا Moisturizer (100 مل) that hydrates the skin and supports its natural barrier."}'::jsonb, 'a16f522c-12bf-569c-8fd3-72a53a3a2c58', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":15800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1771222386_1.png","https://www.yaqootstoreye.com/files/items/item_1771222386_2.png","https://www.yaqootstoreye.com/files/items/item_1771222386_3.png","https://www.yaqootstoreye.com/files/items/item_1771222386_4.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1771222386_1.png","https://www.yaqootstoreye.com/files/items/item_1771222386_2.png","https://www.yaqootstoreye.com/files/items/item_1771222386_3.png","https://www.yaqootstoreye.com/files/items/item_1771222386_4.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"دلكي على الوجه","en":"Massage into the face."}'::jsonb, '["Massage into the face."]'::jsonb, '["دلكي على الوجه"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يرطب البشرة ويدعم حاجزها الطبيعي","يساعد على تقوية حاجز البشرة"],"en":["hydrates the skin and supports its natural barrier","helps strengthen the skin''s barrier"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["moisturizers","انوا"]'::jsonb, '{"title":{"ar":"انوا كريم مرطب بالسيراميد والبانثينول لتقويه حاجز 100 مل - Luminous Derma","en":"انوا Moisturizer 100 مل - Luminous Derma"},"description":{"ar":"انوا مرطب بحجم 100 مل، يعمل على يرطب البشرة ويدعم حاجزها الطبيعي.","en":"انوا Moisturizer (100 مل) that hydrates the skin and supports its natural barrier."},"keywords":["luminous","moisturizers","انوا"]}'::jsonb);
