re"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["serums","جاردن اوليان"]'::jsonb, '{"title":{"ar":"جاردن اوليان سيروم فيتامين سي لبشره اكثر نضاره واشراقه 30 مل - Luminous Derma","en":"جاردن اوليان Serum 30 مل - Luminous Derma"},"description":{"ar":"جاردن اوليان سيروم بحجم 30 مل، يعمل على يمنح البشرة عناية مركزة بمكونات فعالة.","en":"جاردن اوليان Serum (30 مل) that delivers concentrated, effective care."},"keywords":["luminous","serums","جاردن اوليان"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('e4e90683-1fd8-5f33-8f89-01fe6f59d451', 'yq-2396', 'yq-2396', 'YQ-2396', '{"ar":"جاردن اوليان سيروم الانتوين والفيتامينات المتعدده 30 مل","en":"جاردن اوليان Serum 30 مل"}'::jsonb, '{"ar":"جاردن اوليان سيروم بحجم 30 مل، يمنح البشرة عناية مركزة بمكونات فعالة. كما أنه ما يميز جاردن اوليان - سيروم الوجه بـ الانتوين والفيتامينات، ومصنوع من مزيج الانتوين وفيتامينات أساسية تحتاجها بشرتك بشدة. طريقة الاستخدام: اغسلي وجهك جيدًا بغسول مناسب لبشرتك ضعي بضع قطرات من السيروم على أطراف أصابعك دلكي الوجه برفق وبشكل دائري بالسيروم لا تشطفي وجهك بالماء بعدها.","en":"جاردن اوليان Serum (30 مل) that delivers concentrated, effective care."}'::jsonb, '29e558a9-3a4b-52d6-874c-0662648849c0', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":3800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1776643550_1.png","https://www.yaqootstoreye.com/files/items/item_1776643550_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1776643550_1.png","https://www.yaqootstoreye.com/files/items/item_1776643550_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"دلكي على الوجه بضع قطرات، اشطفي بالماء جيداً ثم جففي بلطف","en":"Massage a few drops into the face. Rinse well with water, then pat dry."}'::jsonb, '["Massage a few drops into the face.","Rinse well with water, then pat dry."]'::jsonb, '["دلكي على الوجه بضع قطرات","اشطفي بالماء جيداً ثم جففي بلطف"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يمنح البشرة عناية مركزة بمكونات فعالة","يوفر عناية مركزة للبشرة"],"en":["delivers concentrated, effective care","delivers concentrated care"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["serums","جاردن اوليان"]'::jsonb, '{"title":{"ar":"جاردن اوليان سيروم الانتوين والفيتامينات المتعدده 30 مل - Luminous Derma","en":"جاردن اوليان Serum 30 مل - Luminous Derma"},"description":{"ar":"جاردن اوليان سيروم بحجم 30 مل، يعمل على يمنح البشرة عناية مركزة بمكونات فعالة.","en":"جاردن اوليان Serum (30 مل) that delivers concentrated, effective care."},"keywords":["luminous","serums","جاردن اوليان"]}'::jsonb);
