INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('9943d257-a3dc-5d69-8729-7a585fb0aa8f', 'yq-2408', 'yq-2408', 'YQ-2408', '{"ar":"جاردن اوليان صابونه بزيت الارغان والنيله الزرقاء جرام غسول جسم 100 غرام","en":"جاردن اوليان Body Wash 100 غرام"}'::jsonb, '{"ar":"جاردن اوليان غسول جسم بحجم 100 غرام، ينظف الجسم بلطف. كما أنه يأتي بوزن 100 جم، ليكون جزءًا مثاليًا من روتين العناية اليومية، ومرحبا بكم في متجر \"دار الأميرات\" لمنتجات العناية بالبشرة. طريقة الاستخدام: للاستخدام، بللي بشرتك بالماء ثم ضعي صابون الارغان للوجه على يديك أو على لوفة، وافركيه حتى تتكون رغوة غنية.","en":"جاردن اوليان Body Wash (100 غرام) that cleanses the body gently."}'::jsonb, '1cfdc4ca-7151-569a-8c4e-d97a9a522586', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":1800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1776647743_1.png","https://www.yaqootstoreye.com/files/items/item_1776647743_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1776647743_1.png","https://www.yaqootstoreye.com/files/items/item_1776647743_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"دلكي على البشرة، اتركيه لمدة دقيقة إلى دقيقتين، اشطفي بالماء جيداً ثم جففي بلطف، يومياً","en":"Massage into the skin. Leave it for one to two minutes. Rinse well with water, then pat dry. Use daily."}'::jsonb, '["Massage into the skin.","Leave it for one to two minutes.","Rinse well with water, then pat dry.","Use daily."]'::jsonb, '["دلكي على البشرة","اتركيه لمدة دقيقة إلى دقيقتين","اشطفي بالماء جيداً ثم جففي بلطف","يومياً"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["ينظف الجسم بلطف","يعيد للبشرة إحساس النظافة"],"en":["cleanses the body gently","restores a clean feeling to the skin"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["body-wash","جاردن اوليان"]'::jsonb, '{"title":{"ar":"جاردن اوليان صابونه بزيت الارغان والنيله الزرقاء جرام غسول جسم 100 غرام - Luminous Derma","en":"جاردن اوليان Body Wash 100 غرام - Luminous Derma"},"description":{"ar":"جاردن اوليان غسول جسم بحجم 100 غرام، يعمل على ينظف الجسم بلطف.","en":"جاردن اوليان Body Wash (100 غرام) that cleanses the body gently."},"keywords":["luminous","body-wash","جاردن اوليان"]}'::jsonb);
INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('e9852b85-2d59-55a4-88e5-ed28a8b7a663', 'yq-2409', 'yq-2409', 'YQ-2409', '{"ar":"سوم باي مي قناع ورقي بالهيالورون ترطيب واشراقه مقشر 25 غرام","en":"Some By Mi Mask 25 غرام"}'::jsonb, '{"ar":"سوم باي مي قناع بحجم 25 غرام، يمنح البشرة عناية مكثفة ومركزة. طريقة الاستخدام: سوم من مي قناع أمبولة مضيء مرطب من هيالورون هو قناع مضاد للحساسية لتعزيز ترطيب البشرة ومستويات الرطوبة.","en":"سوم باي مي Mask (25 غرام) that provides intensive, concentrated care."}'::jsonb, '7f592b99-dc96-5efe-84da-57dde42d581b', '26d46fa1-07b5-5d3d-8252-49eac8d5f882', '{"price":2300,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1777191809_1.png","https://www.yaqootstoreye.com/files/items/item_1777191809_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1777191809_1.png","https://www.yaqootstoreye.com/files/items/item_1777191809_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"سوم من مي قناع أمبولة مضيء مرطب من هيالورون هو قناع مضاد للحساسية لتعزيز ترطيب البشرة ومستويات الرطوبة. ينقع القناع في زجاجة واحدة كاملة من الأمبولات الممزوجة بحمض الهيالورونيك الثلاثي وماء أكسجين جيجو لإعطاء البشرة دفعة من الرطوبة. باستخدام قماش نباتي من الدرجة الأولى بنسبة 100% معتمد من اويكو-تكس، سيلتصق هذا القناع ببشرتك كبشرة ثانية ويوفر بفعالية جميع المكونات المثالية للحصول على لمسة نهائية ممتلئة ومرطبة.","en":"سوم من مي قناع أمبولة مضيء مرطب من هيالورون هو قناع مضاد للحساسية لتعزيز ترطيب البشرة ومستويات الرطوبة. ينقع القناع في زجاجة واحدة كاملة من الأمبولات الممزوجة بحمض الهيالورونيك الثلاثي وماء أكسجين جيجو لإعطاء البشرة دفعة من الرطوبة. باستخدام قماش نباتي من الدرجة الأولى بنسبة 100% معتمد من اويكو-تكس، سيلتصق هذا القناع ببشرتك كبشرة ثانية ويوفر بفعالية جميع المكونات المثالية للحصول على لمسة نهائية ممتلئة ومرطبة."}'::jsonb, '["سوم من مي قناع أمبولة مضيء مرطب من هيالورون هو قناع مضاد للحساسية لتعزيز ترطيب البشرة ومستويات الرطوبة","ينقع القناع في زجاجة واحدة كاملة من الأمبولات الممزوجة بحمض الهيالورونيك الثلاثي وماء أكسجين جيجو لإعطاء البشرة دفعة من الرطوبة","باستخدام قماش نباتي من الدرجة الأولى بنسبة 100% معتمد من اويكو-تكس، سيلتصق هذا القناع ببشرتك كبشرة ثانية ويوفر بفعالية جميع المكونات المثالية للحصول على لمسة نهائية ممتلئة ومرطبة"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يمنح البشرة عناية مكثفة ومركزة","يريح البشرة ويهدئها"],"en":["provides intensive, concentrated care","relaxes and soothes the skin"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["masks","سوم باي مي"]'::jsonb, '{"title":{"ar":"سوم باي مي قناع ورقي بالهيالورون ترطيب واشراقه مقشر 25 غرام - Luminous Derma","en":"Some By Mi Mask 25 غرام - Luminous Derma"},"description":{"ar":"Some By Mi مقشر بحجم 25 غرام، يعمل على يمنح البشرة عناية مكثفة ومركزة.","en":"Some By Mi Mask (25 غرام) that provides intensive, concentrated care."},"keywords":["luminous","masks","سوم باي مي"]}'::jsonb);
