INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('ffacaaa5-1e47-5e74-898c-2999372a60ec', 'yq-2423', 'yq-2423', 'YQ-2423', '{"ar":"ميكسا لوشن يوريا سيكا+ للترميم​​​ 250 مل","en":"ميكسا Body Lotion 250 مل"}'::jsonb, '{"ar":"ميكسا لوشن جسم بحجم 250 مل، يرطب الجسم ويحافظ على نعومته. كما أنه وفر لوشن ميكسا يوريا سيكا + لوشن ترميم الجسم 400 مل عناية مكثفة للبشرة الجافة جدًا والخشنة، ونتائج مرئية في أسبوع واحد، مع ترطيب وحماية لمدة تصل إلى 48 ساعة. طريقة الاستخدام: وفر لوشن ميكسا يوريا سيكا + لوشن ترميم الجسم 400 مل عناية مكثفة للبشرة الجافة جدًا والخشنة.","en":"ميكسا Body Lotion (250 مل) that moisturizes and keeps the body soft."}'::jsonb, 'efddd25b-8cfc-590c-830f-8991a96b6d17', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":7800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1777331905_1.png","https://www.yaqootstoreye.com/files/items/item_1777331905_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1777331905_1.png","https://www.yaqootstoreye.com/files/items/item_1777331905_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"وفر لوشن ميكسا يوريا سيكا + لوشن ترميم الجسم 400 مل عناية مكثفة للبشرة الجافة جدًا والخشنة. تحتوي تركيبته على 5% من اليوريا والبانثينول بنسبة 5%، ويعمل على ترطيب البشرة بعمق وتلطيفها وتنعيمها. نتائج مرئية في أسبوع واحد، مع ترطيب وحماية لمدة تصل إلى 48 ساعة. ميزات المنتجات: يصلح البشرة وينعمها ويقلل من جفافها الشديد. لا يسبب الحساسية. 5% يوريا وبانثينول. تم اختباره تحت رقابة طبية. نتائج مثبتة سريريًا","en":"وفر لوشن ميكسا يوريا سيكا + لوشن ترميم الجسم 400 مل عناية مكثفة للبشرة الجافة جدًا والخشنة. تحتوي تركيبته على 5% من اليوريا والبانثينول بنسبة 5%، ويعمل على ترطيب البشرة بعمق وتلطيفها وتنعيمها. نتائج مرئية في أسبوع واحد، مع ترطيب وحماية لمدة تصل إلى 48 ساعة. ميزات المنتجات: يصلح البشرة وينعمها ويقلل من جفافها الشديد. لا يسبب الحساسية. 5% يوريا وبانثينول. تم اختباره تحت رقابة طبية. نتائج مثبتة سريريًا"}'::jsonb, '["وفر لوشن ميكسا يوريا سيكا + لوشن ترميم الجسم 400 مل عناية مكثفة للبشرة الجافة جدًا والخشنة","تحتوي تركيبته على 5% من اليوريا والبانثينول بنسبة 5%، ويعمل على ترطيب البشرة بعمق وتلطيفها وتنعيمها","نتائج مرئية في أسبوع واحد، مع ترطيب وحماية لمدة تصل إلى 48 ساعة","ميزات المنتجات: يصلح البشرة وينعمها ويقلل من جفافها الشديد","لا يسبب الحساسية","5% يوريا وبانثينول","تم اختباره تحت رقابة طبية","نتائج مثبتة سريريًا"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يرطب الجسم ويحافظ على نعومته","يساعد على الحفاظ على نعومة الجسم"],"en":["moisturizes and keeps the body soft","helps keep the body soft"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["body-lotion","ميكسا"]'::jsonb, '{"title":{"ar":"ميكسا لوشن يوريا سيكا+ للترميم​​​ 250 مل - Luminous Derma","en":"ميكسا Body Lotion 250 مل - Luminous Derma"},"description":{"ar":"ميكسا لوشن جسم بحجم 250 مل، يعمل على يرطب الجسم ويحافظ على نعومته.","en":"ميكسا Body Lotion (250 مل) that moisturizes and keeps the body soft."},"keywords":["luminous","body-lotion","ميكسا"]}'::jsonb);
