INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('34362c4a-d36d-52f5-8ff4-6d4a291e44da', 'yq-2541', 'yq-2541', 'YQ-2541', '{"ar":"مافالا زيت مافاديرما المغذي للاظافر 10 مل","en":"مافالا 10 مل"}'::jsonb, '{"ar":"مافالا عناية أظافر بحجم 10 مل، يقوي الأظافر ويدعم صحتها. كما أنه اختيار مثالي لأظافر قوية وطويلة.","en":"مافالا Nail Care (10 مل) that strengthens nails and supports nail health."}'::jsonb, 'df877a47-e213-5f57-84dc-675a5e7659f2', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":9800,"currency":"YER"}'::jsonb, 0, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/MAVALAOILSEALDRYER10ML.jpg?v=1686661212"]'::jsonb, '["https://cdn.shopify.com/s/files/1/0306/5004/0458/files/MAVALAOILSEALDRYER10ML.jpg?v=1686661212"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"يت مغذي للأظافر يعمل على إطالتها والمحافظة على صحتها. يأتي بمزيج متوازن من بذرة القمح والزيتون وزيت اللوز الحلو لتدليك جذور الأظافر مما يجعل أطراف الجلد ناعمة و مرنة. لا تستخدمي زيت مافاديرما قبل وضع طلاء الأظافر، لأنه يشكل طبقة زيتية تؤثر على تماسك طبقة القاعدة أو لون الطلاء. اختيار مثالي لأظافر قوية وطويلة","en":"يت مغذي للأظافر يعمل على إطالتها والمحافظة على صحتها. يأتي بمزيج متوازن من بذرة القمح والزيتون وزيت اللوز الحلو لتدليك جذور الأظافر مما يجعل أطراف الجلد ناعمة و مرنة. لا تستخدمي زيت مافاديرما قبل وضع طلاء الأظافر، لأنه يشكل طبقة زيتية تؤثر على تماسك طبقة القاعدة أو لون الطلاء. اختيار مثالي لأظافر قوية وطويلة"}'::jsonb, '["يت مغذي للأظافر يعمل على إطالتها والمحافظة على صحتها","يأتي بمزيج متوازن من بذرة القمح والزيتون وزيت اللوز الحلو لتدليك جذور الأظافر مما يجعل أطراف الجلد ناعمة و مرنة","لا تستخدمي زيت مافاديرما قبل وضع طلاء الأظافر، لأنه يشكل طبقة زيتية تؤثر على تماسك طبقة القاعدة أو لون الطلاء","اختيار مثالي لأظافر قوية وطويلة"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يقوي الأظافر ويدعم صحتها","يدعم صحة الأظافر"],"en":["strengthens nails and supports nail health","supports nail health"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["nail-care","مافالا"]'::jsonb, '{"title":{"ar":"مافالا زيت مافاديرما المغذي للاظافر 10 مل - Luminous Derma","en":"مافالا 10 مل - Luminous Derma"},"description":{"ar":"مافالا nail-care بحجم 10 مل، يعمل على يقوي الأظافر ويدعم صحتها.","en":"مافالا nail-care (10 مل) that strengthens nails and supports nail health."},"keywords":["luminous","nail-care","مافالا"]}'::jsonb);
