INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('a36def8b-5acc-52eb-8f20-287f74216b21', 'yq-2547', 'yq-2547', 'YQ-2547', '{"ar":"فلورمار كحل سائل ديب لينر فينل اسود مطفي ضد الماء","en":"فلورمار"}'::jsonb, '{"ar":"فلورمار مكياج بتركيبة سائلة، يمنح إطلالة مكياج متناسقة. كما أنه بفضل سهولة تطبيقه وسرعة جفافه، يمكنكِ رسم خطوط دقيقة ومثالية بدون تلطخ أو انتقال، والمميزات دقة عالية: يمنحكِ خطوطًا واضحة ونظيفة مع تحكم كامل—مثالي لرسم الأجنحة وخط الرموش. طريقة الاستخدام: آيلاينر سائل مطفي مقاوم للماء من فلورمار آيلاينر فلورمار المطفي المقاوم للماء هو السر لإطلالة عيون تدوم طويلاً.","en":"فلورمار Makeup that creates a balanced makeup look."}'::jsonb, 'd20bc4a1-31b8-5b9a-80c2-c76ec216c086', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":2300,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1779490722_1.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1779490722_1.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"ضعي على الرموش، اتركيه لمدة دقيقة إلى دقيقتين","en":"Apply to the lashes. Leave it for one to two minutes."}'::jsonb, '["Apply to the lashes.","Leave it for one to two minutes."]'::jsonb, '["ضعي على الرموش","اتركيه لمدة دقيقة إلى دقيقتين"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يمنح إطلالة مكياج متناسقة","يساعد على ثبات المكياج","تركيبة سائلة خفيفة سهلة الاستخدام"],"en":["creates a balanced makeup look","helps makeup last","a light liquid formula that is easy to use"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["makeup","فلورمار"]'::jsonb, '{"title":{"ar":"فلورمار كحل سائل ديب لينر فينل اسود مطفي ضد الماء - Luminous Derma","en":"فلورمار - Luminous Derma"},"description":{"ar":"فلورمار makeup، يعمل على يمنح إطلالة مكياج متناسقة ويأتي بتركيبة سائلة.","en":"فلورمار makeup that creates a balanced makeup look."},"keywords":["luminous","makeup","فلورمار"]}'::jsonb);
