INSERT INTO products (id, legacy_id, slug, sku, name, description, category_id, brand_id, pricing, discount, gallery, images, ingredients, usage_instructions, how_to_use, how_to_use_ar, skin_types, suitable_for, skin_concerns, benefits, stock, in_stock, stock_quantity, rating, review_count, is_featured, is_new, is_best_seller, is_doctor_recommended, tags, seo_metadata) VALUES ('0222cf51-996f-5b91-8248-b40072c58edf', 'yq-2661', 'yq-2661', 'YQ-2661', '{"ar":"فلورمار قلم حواجب مائل انجلد مع فرشه لون بني رقم 3 مكياج eye","en":"فلورمار Eye Makeup"}'::jsonb, '{"ar":"فلورمار مكياج عيون بتركيبة جل، يبرز جمال العينين. كما أنه يتميز بطرف مائل أوتوماتيكي لسهولة التحكم، ومتوفر بعدة درجات تناسب جميع ألوان الحواجب، والمميزات تحديد الحواجب: يمنحكِ حواجب مرتبة ومحددة بمظهر أنيق—من طبيعي إلى جريء حسب رغبتك. طريقة الاستخدام: قلم حواجب مائل من فلورمار يمنحكِ قلم الحواجب المائل من فلورمار حواجب أكثر كثافة وتحديدًا بسهولة.","en":"فلورمار Eye Makeup that enhances the eyes."}'::jsonb, '794844d7-e95c-5b3b-8cd2-4e6ed5c56ab0', 'b86ae4ed-e91c-584a-889b-de2ed382793c', '{"price":3800,"currency":"YER"}'::jsonb, 0, '["https://www.yaqootstoreye.com/files/items/item_1782747378_1.png","https://www.yaqootstoreye.com/files/items/item_1782747378_2.png"]'::jsonb, '["https://www.yaqootstoreye.com/files/items/item_1782747378_1.png","https://www.yaqootstoreye.com/files/items/item_1782747378_2.png"]'::jsonb, '{"ar":[],"en":[]}'::jsonb, '{"ar":"قلم حواجب مائل من فلورمار يمنحكِ قلم الحواجب المائل من فلورمار حواجب أكثر كثافة وتحديدًا بسهولة. بفضل قوامه الناعم، يمكنكِ ملء الفراغات بسرعة ودقة، بينما تساعدكِ الفرشاة المدمجة على ترتيب الحواجب وتشكيلها بشكل مثالي. يتميز بطرف مائل أوتوماتيكي لسهولة التحكم، ومتوفر بعدة درجات تناسب جميع ألوان الحواجب. المميزات تحديد الحواجب: يمنحكِ حواجب مرتبة ومحددة بمظهر أنيق—من طبيعي إلى جريء حسب رغبتك. ملء وتكثيف: يساعد على ملء الفراغات للحصول على حواجب أكثر كثافة وتوازنًا. تطبيق متحكم به: تركيبة مريحة تنساب بسهولة دون تقطيع، مع إمكانية دمج الأطراف لنتيجة ناعمة. ثبات طويل: يمنحكِ مظهرًا مرتبًا يدوم لفترة أطول خلال اليوم. تقنية احترافية: استخدمي الفرشاة أثناء التطبيق لدمج اللون، ثم مرّريها مرة أخيرة لتوزيع المنتج بشكل متساوٍ.","en":"قلم حواجب مائل من فلورمار يمنحكِ قلم الحواجب المائل من فلورمار حواجب أكثر كثافة وتحديدًا بسهولة. بفضل قوامه الناعم، يمكنكِ ملء الفراغات بسرعة ودقة، بينما تساعدكِ الفرشاة المدمجة على ترتيب الحواجب وتشكيلها بشكل مثالي. يتميز بطرف مائل أوتوماتيكي لسهولة التحكم، ومتوفر بعدة درجات تناسب جميع ألوان الحواجب. المميزات تحديد الحواجب: يمنحكِ حواجب مرتبة ومحددة بمظهر أنيق—من طبيعي إلى جريء حسب رغبتك. ملء وتكثيف: يساعد على ملء الفراغات للحصول على حواجب أكثر كثافة وتوازنًا. تطبيق متحكم به: تركيبة مريحة تنساب بسهولة دون تقطيع، مع إمكانية دمج الأطراف لنتيجة ناعمة. ثبات طويل: يمنحكِ مظهرًا مرتبًا يدوم لفترة أطول خلال اليوم. تقنية احترافية: استخدمي الفرشاة أثناء التطبيق لدمج اللون، ثم مرّريها مرة أخيرة لتوزيع المنتج بشكل متساوٍ."}'::jsonb, '["قلم حواجب مائل من فلورمار يمنحكِ قلم الحواجب المائل من فلورمار حواجب أكثر كثافة وتحديدًا بسهولة","بفضل قوامه الناعم، يمكنكِ ملء الفراغات بسرعة ودقة، بينما تساعدكِ الفرشاة المدمجة على ترتيب الحواجب وتشكيلها بشكل مثالي","يتميز بطرف مائل أوتوماتيكي لسهولة التحكم، ومتوفر بعدة درجات تناسب جميع ألوان الحواجب","المميزات تحديد الحواجب: يمنحكِ حواجب مرتبة ومحددة بمظهر أنيق—من طبيعي إلى جريء حسب رغبتك","ملء وتكثيف: يساعد على ملء الفراغات للحصول على حواجب أكثر كثافة وتوازنًا","تطبيق متحكم به: تركيبة مريحة تنساب بسهولة دون تقطيع، مع إمكانية دمج الأطراف لنتيجة ناعمة","ثبات طويل: يمنحكِ مظهرًا مرتبًا يدوم لفترة أطول خلال اليوم","تقنية احترافية: استخدمي الفرشاة أثناء التطبيق لدمج اللون، ثم مرّريها مرة أخيرة لتوزيع المنتج بشكل متساوٍ"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"ar":["يبرز جمال العينين","يساعد على إبراز جمال العينين","تركيبة جل منعشة سهلة الاستخدام"],"en":["enhances the eyes","helps enhance the eyes","a refreshing gel formula that is easy to use"]}'::jsonb, 10, TRUE, 10, 0, 0, FALSE, FALSE, FALSE, FALSE, '["eye-makeup","فلورمار"]'::jsonb, '{"title":{"ar":"فلورمار قلم حواج