INSERT INTO articles (id, slug, title, title_ar, excerpt, excerpt_ar, content, content_ar, author, author_ar, avatar, category, category_ar, cover_image, publish_date, read_time, tags, seo_metadata) VALUES ('aea841db-ae3a-5bc0-8f44-db7e3e5f3ecc', 'best-moisturizer-for-dry-skin', 'Best Moisturizer for Dry Skin', 'أفضل مرطب للبشرة الجافة', 'Discover the best products to hydrate your dry skin and maintain its radiance.', 'اكتشف أفضل المنتجات لترطيب بشرتك الجافة والحفاظ على نضارتها.', 'Dry skin needs moisturizers rich in hydrating ingredients like hyaluronic acid and ceramides. Choose fragrance-free, non-drying products.', 'البشرة الجافة تحتاج إلى مرطبات غنية بالمكونات المرطبة مثل حمض الهيالورونيك والسيراميد.', 'Dr. Nora Al-Mansour', 'دكتورة نورة المنصور', NULL, 'Skincare', 'العناية بالبشرة', '/images/articles/hyaluronic-acid-benefits.svg', '2026-06-05', 4, '["moisturizer","dry-skin","hydration"]'::jsonb, '{"title":{"ar":"أفضل مرطب للبشرة الجافة","en":"Best Moisturizer for Dry Skin"},"description":{"ar":"أفضل المنتجات لترطيب البشرة الجافة.","en":"Best products for hydrating dry skin."},"keywords":["moisturizer","dry skin","hydration"]}'::jsonb);
