INSERT INTO articles (id, slug, title, title_ar, excerpt, excerpt_ar, content, content_ar, author, author_ar, avatar, category, category_ar, cover_image, publish_date, read_time, tags, seo_metadata) VALUES ('ae808767-4522-5be7-8432-837b5908b06d', 'vitamin-c-benefits-for-skin', 'Benefits of Vitamin C for Skin', 'فوائد فيتامين سي للبشرة', 'Learn how vitamin C can improve your skin''s radiance and even out its tone.', 'تعرف على كيف يمكن لفيتامين سي أن يحسن نضارة بشرتك ويوحد لونها.', 'Vitamin C is one of the most powerful antioxidants that help brighten skin, reduce dark spots, and boost collagen production. Use it in the morning for best results.', 'فيتامين سي هو من أقوى مضادات الأكسدة التي تساعد في تفتيح البشرة وتقليل البقع الداكنة.', 'Dr. Youssef Khalil', 'الدكتور يوسف خليل', NULL, 'Ingredients', 'المكونات', '/images/articles/vitamin-c-guide.svg', '2026-06-10', 6, '["vitamin-c","brightening","ingredients"]'::jsonb, '{"title":{"ar":"فوائد فيتامين سي للبشرة","en":"Benefits of Vitamin C for Skin"},"description":{"ar":"تعرف على فوائد فيتامين سي للبشرة.","en":"Learn about vitamin C benefits for skin."},"keywords":["vitamin c","brightening","skin benefits"]}'::jsonb);
