INSERT INTO articles (id, slug, title, title_ar, excerpt, excerpt_ar, content, content_ar, author, author_ar, avatar, category, category_ar, cover_image, publish_date, read_time, tags, seo_metadata) VALUES ('d1ccf061-fe97-5515-86a9-bb6f78a6a5ad', 'sensitive-skin-care-tips', 'Sensitive Skin Care Tips', 'نصائح للعناية بالبشرة الحساسة', 'Practical tips for caring for your sensitive skin and avoiding irritation and redness.', 'نصائح عملية للعناية ببشرتك الحساسة وتجنب التهيج والاحمرار.', 'Sensitive skin needs gentle, fragrance-free, alcohol-free products. Use gentle cleansers, soothing moisturizers, and avoid harsh exfoliation.', 'البشرة الحساسة تحتاج إلى منتجات لطيفة خالية من العطور والكحول.', 'Dr. Lina Omar', 'دكتورة لينا عمر', NULL, 'Skincare', 'العناية بالبشرة', '/images/articles/sunscreen-myths.svg', '2026-06-15', 4, '["sensitive-skin","tips","gentle-care"]'::jsonb, '{"title":{"ar":"نصائح للعناية بالبشرة الحساسة","en":"Sensitive Skin Care Tips"},"description":{"ar":"نصائح عملية للبشرة الحساسة.","en":"Practical tips for sensitive skin."},"keywords":["sensitive skin","care tips","gentle"]}'::jsonb);
