INSERT INTO articles (id, slug, title, title_ar, excerpt, excerpt_ar, content, content_ar, author, author_ar, avatar, category, category_ar, cover_image, publish_date, read_time, tags, seo_metadata) VALUES ('9f0fa684-022a-5298-8571-48760ea8f60c', 'anti-aging-skincare-guide', 'Anti-Aging Skincare Guide', 'دليل مكافحة الشيخوخة للبشرة', 'Your complete guide to fighting signs of aging and maintaining youthful skin.', 'دليلك الشامل لمكافحة علامات الشيخوخة والحفاظ على شباب البشرة.', 'Anti-aging starts with retinol, vitamin C, and hyaluronic acid. Use sunscreen daily and start your anti-aging routine early.', 'مكافحة الشيخوخة تبدأ بالريتينول وفيتامين سي وحمض الهيالورونيك.', 'Dr. Sarah Ahmed', 'دكتورة سارة أحمد', NULL, 'Skincare', 'العناية بالبشرة', '/images/articles/vitamin-c-guide.svg', '2026-06-20', 7, '["anti-aging","retinol","skincare"]'::jsonb, '{"title":{"ar":"دليل مكافحة الشيخوخة للبشرة","en":"Anti-Aging Skincare Guide"},"description":{"ar":"دليلك الشامل لمكافحة الشيخوخة.","en":"Complete guide to fighting signs of aging."},"keywords":["anti-aging","retinol","skincare guide"]}'::jsonb);
