INSERT INTO articles (id, slug, title, title_ar, excerpt, excerpt_ar, content, content_ar, author, author_ar, avatar, category, category_ar, cover_image, publish_date, read_time, tags, seo_metadata) VALUES ('739072ef-d2be-5f65-8bcf-ce14c5226c46', 'how-to-choose-right-skincare-products', 'How to Choose the Right Skincare Products', 'كيف تختار منتجات العناية بالبشرة المناسبة', 'Your guide to choosing the right products for your skin type and concerns.', 'دليلك لاختيار المنتجات المناسبة لنوع بشرتك ومشاكلها.', 'Choosing the right products starts with knowing your skin type and concerns. Look for ingredients that suit your skin and avoid products with irritating ingredients.', 'اختيار المنتجات المناسبة يبدأ بمعرفة نوع بشرتك ومشاكلها.', 'Dr. Khaled Mahmoud', 'الدكتور خالد محمود', NULL, 'Skincare', 'العناية بالبشرة', '/images/articles/hyaluronic-acid-benefits.svg', '2026-06-25', 5, '["skincare","product-selection","tips"]'::jsonb, '{"title":{"ar":"كيف تختار منتجات العناية بالبشرة","en":"How to Choose Skincare Products"},"description":{"ar":"دليلك لاختيار المنتجات المناسبة.","en":"Guide to choosing the right products."},"keywords":["skincare","product selection","tips"]}'::jsonb);
