INSERT INTO articles (id, slug, title, title_ar, excerpt, excerpt_ar, content, content_ar, author, author_ar, avatar, category, category_ar, cover_image, publish_date, read_time, tags, seo_metadata) VALUES ('a748faaf-d8fb-5e2f-8160-58389d0b5c19', 'hair-care-routine-for-healthy-hair', 'Hair Care Routine for Healthy Hair', 'روتين العناية بالشعر للشعر الصحي', 'Tips for building a hair care routine that maintains hair health and smoothness.', 'نصائح لبناء روتين عناية بالشعر يحافظ على صحته ونعومته.', 'A good hair routine starts with a gentle shampoo, then conditioner, then care oil. Avoid frequent washing and use sulfate-free products.', 'الروتين الجيد للشعر يبدأ بالشامبو اللطيف ثم البلسم ثم زيت العناية.', 'Dr. Ahmed Hassan', 'الدكتور أحمد حسن', NULL, 'Haircare', 'العناية بالشعر', '/images/articles/sunscreen-myths.svg', '2026-07-01', 5, '["haircare","healthy-hair","routine"]'::jsonb, '{"title":{"ar":"روتين العناية بالشعر","en":"Hair Care Routine"},"description":{"ar":"نصائح للشعر الصحي.","en":"Tips for healthy hair."},"keywords":["haircare","hair routine","healthy hair"]}'::jsonb);
